/* 平成19年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h19.committeeSessions.push(...[{"id":"h19-20070305-3","meetingId":"h19-c-budget","date":"2007年3月5日","dateIso":"2007-03-05","committee":"予算特別委員会","time":"午前１０時０４分～午後５時５９分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を134件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"中塚副委員長","kind":"質問・要望","question":"第１項、理事および理事会の設置についてです。１人当たりの質問時間は、答弁時間も含めて、１０分、１５分、２０分のいずれかとし、会派で割り振ることとしております。なお、無所属の委員の質問時間は、答弁時間も含めて１０分といたします。終了時間のお知らせにつきましては、残り時間がなくなった時点で振鈴を２回鳴らしますので、質問の途中でありましても直ちにとりやめていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":4,"id":"exchange-001"},{"speaker":"大沢委員","kind":"確認","question":"おはようあります。第１点目なんですが、子どもすこやか医療費助成、これは新規事業ということで、本年の１０月から実施をされるということになりました。これは１,４００万円ということで増額をされているわけですが、確認といたしまして、この増額分は中学生の拡大された部分の増額と考えてまずいいわけでしょうか。確認をさせてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":9,"id":"exchange-002"},{"speaker":"大沢委員","kind":"質問","question":"すみません。間違いました。ちょっとチームワークが乱れました。申しわけありません。じゃあ、すみません。約１,４００万円の追加になるわけですけれども、この追加分、自己負担額と入院時の食事の負担金ということなんですけれども、どういうふうにこの金額が算出をされたのか教えてください。","respondent":"諸岡児童課長","answer":"そういったことで算定をいたしまして、約１,４００万円強の補正ということで、このたびお願いしているわけです。","voiceIndex":11,"id":"exchange-003"},{"speaker":"大沢委員","kind":"質問","question":"１２.７回ということが基準になっているということなんですけれども、１２.７回、この数字に関しては、他の区と比べて多いほうなんでしょうか、少ないほうなんでしょうか。","respondent":"諸岡児童課長","answer":"１人当たりの受診回数におきまして、他区との比較というのはちょっとしてございませんけれども、概ね同程度というふうに考えてあります。","voiceIndex":13,"id":"exchange-004"},{"speaker":"大沢委員","kind":"質問","question":"自己負担額が３割、これが区からということで無料になるということですけども、先ほどちょっとお伺いしました入院時の食事の標準の負担金というのは、幾らなんでしょうか。","respondent":"諸岡児童課長","answer":"入院時の自己負担額ですけれども、保険適用のほうで算定をやっていまして、今ちょっと金額は具体的に把握してございませんが、それについて自己負担額がなくなるように助成をしているというものです。","voiceIndex":15,"id":"exchange-005"},{"speaker":"大沢委員","kind":"質問・要望","question":"ちょっとすみません。その次に、入院時食事標準負担金ということですから、標準ということで今お伺いをさせていただいたわけですが、この数字が出てくるからには、負担額というのも数字が出ているだろうと思いますので、おわかりになりましたら、また後ほどでもいいので教えていただきたいと思います。その充実をしていただくようにこれは要望して、次の質問に移りたいと思います。","respondent":"谷田部健康課長","answer":"１点目の不妊治療の減額ですけれども、平成１８年度新規事業で取り組んだ事業でございまして、平成１８年度当初におきまして、一般不妊治療にかかわる検査も含めた治療費、それから人工受精という二つの助成内容に分けて制度を組み立てたものでして。","voiceIndex":17,"id":"exchange-006"},{"speaker":"大沢委員","kind":"意見","question":"不妊治療のほうで、２５０名あるだろうという予想で、実際なかったということで、そのなかったということ、決して揚げ足をとるわけじゃないんですが、知らない方もかなりの数いらっしゃると思うんですけれども、区の事業を区民の方に広報する場合に、私思うんですけれども、広報の仕方、確かに区のほうは一生懸命されているんでしょうけれども、一つ最後の何かコショウ、味の決め手。","respondent":"谷田部健康課長","answer":"それと、不妊治療に取り組める医療機関というものを私ども独自に調査いたしまして、そういうリストで私どももご案内をすると同時に、これは平成１９年度予算の中身の話になってしまいますけども、１年間やった結果を。","voiceIndex":19,"id":"exchange-007"},{"speaker":"大沢委員","kind":"質問・要望","question":"所得制限の撤廃とか、もろもろいろんな使いやすい制度にしていただいて、それをより充実して皆さんに周知できるような体制をつくっていただきたいと思います。すみません、あと３分ちょっとになりましたので、次の質問に移らせていただきます。最初からそのような形でわかっていれば、何も補正をプラス・マイナスしなくてもいいのではなかろうかと思いますけれども、そこのあたりのやりくりを教えてください。","respondent":"原国保年金課長","answer":"今年は、この平成１８年１２月までやりますと、月４７人ということで、出生の数が若干減ったり増えたりということで、ここのところ増えてありますので、そういった背景の中で２４人の分を追加させていただいたということでご理解いただきたいと思います。","voiceIndex":21,"id":"exchange-008"},{"speaker":"大沢委員","kind":"意見","question":"２４名分の追加ということで、すみません、時間が短くなっちゃいましたけども、会計の処理の、あくまでも子どもが出生するというのは神のみぞ知ることなんですけれども、予算書にする場合に、常にこのような補正の計算を立てる場合に、プラス・マイナスすることがいいのかどうか、ちょっとご見解をください。","respondent":"日下部企画財政課長","answer":"当初予算以降のいろんな事情の変更もありますので、できるだけ最小限にこしたことはないんですが、必要なものについては増減計上すると、その辺はご理解いただきたいと思います。","voiceIndex":23,"id":"exchange-009"},{"speaker":"宮崎委員","kind":"質問","question":"私は５９ページの公共施設整備基金積立金の追加分と、これに関連して基金についてもちょっとお伺いしたいと思います。今時点で取り崩し可能な基金の額はどうなっているのか。それとあと、積立額のところの主な財源ですね。どういうふうなものが積み立てになってきているのかというところをまずお伺いしたいと思います。","respondent":"日下部企画財政課長","answer":"その財源でありますけれども、今回の９２億円の、確かに額が大きいことは事実でありますけれども、これにつきましては、基本的に年度末までの財源の見通しがはっきりいたしましたので、これに基づいて最終補正をさせていただいているわけでありますけれども。","voiceIndex":26,"id":"exchange-010"},{"speaker":"宮崎委員","kind":"質問","question":"その全体の増額が５６億円なんですけれども、積み立てが９２億円ということで、普通の家計から考えると、この積み立てる額が非常に大きいというのは、いわゆるやりくりがどういうふうにやるのかというところが非常に私もよくわからなくて、何回聞いてもよくわからないんですけれども、改めてやりくりの考え方、そして基金積み立てのあわせて公共施設整備だけじゃなくて、基金の積み立ての考え方といいますか。","respondent":"日下部企画財政課長","answer":"ただ、最終段階で、これは非常に単純なちょっと説明で申しわけないんですが、そういう形で予定をしてまいりますけれども、それだけでは必ずしも十分に基金の積み立てに回るとは限りません。","voiceIndex":28,"id":"exchange-011"},{"speaker":"宮崎委員","kind":"質問・要望","question":"それとあと、基金については、いろいろ出入りもあるんですが、大体このぐらいは置いておくんだとか、そういう目標額はあるんでしょうか。毎年これだけは積み立てるんだと、そういう目標額というのはあるのかどうか、教えていただきたいと思います。","respondent":"日下部企画財政課長","answer":"ですから、そういったことも含めまして、別に青天井ということではありませんが、当面する施設需要に対応していくためには、もうしばらくはできる限りの積み増しをしていかないと、なかなかこれに対応し切れないんではないか、このように考えてあります。","voiceIndex":30,"id":"exchange-012"},{"speaker":"宮崎委員","kind":"意見","question":"そういうやり方なのかなというふうに思うんですけれども、今の２０年間かけて、毎年四、五十億円かかっていくというお話なんですけども、そもそも区の財源を先行で使って進めていくと、そういう考え方というのをなぜとるのかなというのが私よくわからないんですけども、国あるいは東京都の予算化を待ってそういうものを進めていくということではなくて。","respondent":"日下部企画財政課長","answer":"起債につきましても、最大２割程度であります。起債は当然借金で返すものですから、そういった意味では、財源２５億円で１校を建て替える、そのうち１割ぐらいしか補助金というのは見込めません。それ以外のものは区が負担するわけです。","voiceIndex":32,"id":"exchange-013"},{"speaker":"宮崎委員","kind":"質問","question":"いろいろ負担軽減だとか、そういうところにもやっぱり財源の考え方というのがいっていいんじゃないかと思うんです。先ほどちょっと聞き忘れたんですが、基金の積み立てのところでは、区税、財調、いろいろな財源がありますというお話だったんですけど、今回の９２億円のところでいくと、おおよそどういう財源が何パーセントぐらいなのかというのが何かわかったら教えていただければと思うんですが。","respondent":"日下部企画財政課長","answer":"先ほど申し上げました９２億円に関しましては、基本的には一般財源が大半です。つまり、特定財源が増える、そうすると、その分一般財源の負担が減りますので、そういったいわば残余の余裕の出た一般財源を基金に積み立てると、それが基本的な考え方です。","voiceIndex":34,"id":"exchange-014"},{"speaker":"宮崎委員","kind":"提案","question":"特に今回も、私も一般質問でも、例えばお年寄りの医療費無料化なんかも区でもやれるんじゃないかと、そういう提案をさせていただいたんですけれども、ちょっと改めて伺いたいんですが、今回子どもたちの医療費無料化、中学校まで拡大になりましたけれども、そういうこっちのほうの財源と、例えばお年寄りのほうの医療費無料化とか、そういうところに考えようによっては回すのも可能、この基金は。","respondent":"日下部企画財政課長","answer":"単純な物の言い方をしますれば、一般財源で予算を計上するものについて、特段そういう一つの制約というものは具体的にはないと考えています。最後はやはり政策判断以外の何物でもないと考えております。","voiceIndex":36,"id":"exchange-015"},{"speaker":"宮崎委員","kind":"質問・要望","question":"もう一つ、やっぱり今の格差が広がっているというふうに言われておりますが、代表質問のところでもなかなか格差が広がっているという認識があまり聞かれなかったんですけども、やっぱり暮らしのところでは、非常に格差が広がっております。そういう立場で、今後の活用のところもいろいろ検討していただければということで、今日は要望させていただいて、終わりにいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":38,"id":"exchange-016"},{"speaker":"武内委員","kind":"質問・要望","question":"私は７ページの歳入、それから４７ページの安全・安心な学校づくり交付金、それから４８ページの小中学校改築事業特別交付金、それから６９ページの不妊治療相談・助成事業更正減額、８３ページの大間窪小学校用地取得減をお聞きしたいと思います。この辺の理由というか、傾向というか、この辺をまず教えていただきたいと思います。","respondent":"日下部企画財政課長","answer":"これにつきましては、先ほどもちょっとご説明を申し上げましたけれども、一つには再開発事業、やはり、これも主要５課題の関係で、平成１８年度の当初の段階では計上できませんでしたけれども、財調協議の最終段階で市街地再開発事業に対する補助金について。","voiceIndex":40,"id":"exchange-017"},{"speaker":"武内委員","kind":"質問","question":"そうすると、都の支出金のほうは、都市計画交付金に再開発事業が対象になって、これが大幅に増えてきたと、こういうことだと思うんですけれども、そうすると、再開発事業というのは、今までは都のほうからは支出されていなかったということで、それが支出されるようになったと、こういうことでよろしいでしょうか。","respondent":"日下部企画財政課長","answer":"結果からすれば、都市計画交付金の対象になるわけですから、その分２３区側にとっては財調全体の算定の一つのパイが広がるというような効果を見込めるというものです。","voiceIndex":42,"id":"exchange-018"},{"speaker":"武内委員","kind":"質問","question":"続きまして、４７ページの安全・安心な学校づくり交付金、これについてお伺いします。これは先ほど平成１８年度新設というご説明がありましたけれども、この辺の経緯、背景と、それから関連しますので、４８ページの小中学校改築事業特別交付金、これも先ほどの説明で過去の清算分２００億円のうちの品川の分がこれだという説明があったので、その辺のところをもう少し詳しく教えてください。","respondent":"市川庶務課長、日下部企画財政課長","answer":"具体的に申し上げますと、この事業の中で従来の校舎改築、それから耐震補強の工事、こういったものが事業の対象として見られるようになった、こういうものです。最後にどーんと平成１８年度分で約６００億円近くが来ることになりましたので、その相差の１５０億円に若干それにプラスアルファで２００億円、これを小中学校の改築の交付金として。","voiceIndex":44,"id":"exchange-019"},{"speaker":"武内委員","kind":"質問","question":"そうしますと、今後耐震補強、また耐震改修、また学校改築、それぞれ違うとは思うんですけども、国と東京都と、また区がそれぞれ予算を出し合う配分比率というのは今後どういうふうになっていくのか、教えていただけますか。","respondent":"日下部企画財政課長","answer":"今申し上げました特別交付金の２００億円というのは、あくまで一時金でございまして、今回１回限りです。ですから、東京都からこういう形での交付金は今後はおそらく来ることはないと思います。","voiceIndex":47,"id":"exchange-020"},{"speaker":"武内委員","kind":"質問","question":"そうしますと、今回補正で幼稚園、小学校、中学校それぞれありますけれども、あとどれぐらいでこの小中学校、幼稚園、例えば保育園とか、この辺のいわゆる教育施設とか、区有施設はどれぐらいの予定で終わるという予定になっているんでしょうか、教えていただければ。","respondent":"市川庶務課長、小林保育課長","answer":"これの設計を来年度、平成１９年度に行います。実質所要経費については、その実施設計を待って確定される、こういった今後の見通しです。最終的には平成１９年度、平成２０年度と品川保育園の建て替えを除きまして、それぞれ５園、７園、実施を予定しておりまして、合計２０園で、平成２０年度までにすべての耐震を完了する予定です。","voiceIndex":51,"id":"exchange-021"},{"speaker":"武内委員","kind":"質問","question":"わかりました。続きまして、６９ページ、先ほど大沢委員のほうからもちょっと質問がありましたんですが、私もこれをちょっと聞こうと思っていて、理由についてはわかったんですけど、そうしますと、平成１８年の当初予算では、２５０組ということで予算組みがされていたわけですけど、実際まだ３月途中でありますけども、何件ぐらい不妊治療の件数があったのか、実績を教えていただければと思います。","respondent":"谷田部健康課長","answer":"２月末での申請の受け付けですけれども、１６件の申請がございまして、助成額は約５０万円という状況です。","voiceIndex":54,"id":"exchange-022"},{"speaker":"武内委員","kind":"質問・要望","question":"そうしますと、２５０件の予算組み、東京都にあわせて検討して、それで、実際にはやっぱり１６件ということで、かなりまだ少なかったなという気はするんですけども、その辺はやっぱり理由としては、見込み違いということもあるんでしょうけれども、そのほかに何かもし理由があれば教えていただきたいと思います。","respondent":"谷田部健康課長","answer":"先ほど申し上げましたけども、件数につきましては、特定不妊治療にかかっている東京都の助成事業を受けている方、これは品川区民の方は大体６０件から７０件ありまして。","voiceIndex":56,"id":"exchange-023"},{"speaker":"武内委員","kind":"質問","question":"最後に、８３ページの大間窪小学校の用地取得についてですが、これが平成１８年度の当初予算ではたしか２３億円ほど計上されておりましたが、今回約１３億円ぐらいですか、減になっておるわけですけども、そうすると、大体１０億円で購入できたということで考えておけばよろしいんでしょうか。","respondent":"市川庶務課長","answer":"したがいまして、今年度当初におきまして、先ほど申し上げたような計算で出しました２３億円という額で計上いたしました。結果、２分の１の減額ということで、９億３,８００万円という購入価格で、その差額について今回補正をお願いする次第です。","voiceIndex":58,"id":"exchange-024"},{"speaker":"大西委員","kind":"質問・要望","question":"私は、まず４４ページ、こっちのほうで、先ほどの企画財政課長のほうの話の中で、温水プールというのがありましたけども、このことについてと、それとあと６０ページ、選挙費、それと区民施設費、その部分についてちょっとお尋ねをしたいと思います。","respondent":"富田生涯学習課長、野田口選挙管理委員会事務局長","answer":"学校温水プールにつきましては、現在は日野学園温水プールと戸越台中学校温水プール、２校です。それと、一般開放につきましては、本年５月から伊藤学園温水プールをオープンする予定でおります。給料の差です。更正した理由ですけれども、予算を編成した１０月１日時点では再任用職員が選挙管理委員会事務局の職員として１名いましたけども、４月１日正規職員に変わったために必要な額を更正したものです。","voiceIndex":61,"id":"exchange-025"},{"speaker":"大西委員","kind":"質問・要望","question":"それとあと、選挙費のことですけども、これは昨年区長選挙ならびに区議会議員選挙の補欠というのがありましたけども、これは４年ごとにこういう形で選挙が行われてくるという形になると、その部分の費用等も通常の自治体よりも統一地方選でなくなってくるので費用がかかってくるというふうに考えるわけですけれども、そういう部分は、当然品川区の税金がなくなっていく部分があろうかと思いますけど。","respondent":"日下部企画財政課長、野田口選挙管理委員会事務局長","answer":"例えば、荏原文化センターにも温水プールはあります。そういったことも含めまして、地域バランスに配慮した上でこれは考えていくべき、そういう性格のものだ、このように考えてあります。国政選挙とか都知事選挙というのは、それぞれ国で持つとか、都で負担するとかということになりますけれども、これについてはやむを得ないものというふうに理解しております。","voiceIndex":64,"id":"exchange-026"},{"speaker":"大西委員","kind":"質問・要望","question":"これは議員としても同じような形で、選挙をこのわずかな期間で２回もやらなきゃいけないというのは、資金的なものであったり、いろんな面で負担があるということなんかがありますので、これを解消するには、それではどういう働きかけをしていかなければならないかというのを品川区としても少し考えるべきで、よその自治体と協調しながら、何らかの圧力をどこかにかけていって改善を図っていけるものなのか。","respondent":"日下部企画財政課長、野田口選挙管理委員会事務局長、市川庶務課長","answer":"温水プールの関係でありますけれども、先ほどお答え申し上げましたが、この間地域バランスに配慮をして。それで、委員がお尋ねのように、半年ぐらい違うものについて、任期を統一しようとすると。そのほかはすべて解体工事の対象となりました。方角で申し上げますと、旧校舎の立会道路側の一部分です。","voiceIndex":67,"id":"exchange-027"},{"speaker":"大西委員","kind":"質問","question":"今選挙管理委員会事務局長の話の中で、私からすると、公職選挙法を変えないと、このこと自体はできないんじゃないかというふうに考えているんですけど、それと別個に今の考え方というのは、選挙管理委員会の考え方によって、このことを変えて、同一にできるという、その余地があるようにも少し感じたんですけど、その辺はどうでしょうか。","respondent":"野田口選挙管理委員会事務局長","answer":"選挙は任期満了の３０日前に地方選挙についてはやるべきだということで定まっております。ただ、その特例法として、４年に１回の統一地方選挙については、２月から５月までの満了については、統一するよと、これも法律で定まっております。","voiceIndex":71,"id":"exchange-028"},{"speaker":"大西委員","kind":"質問・要望","question":"それとともに、全国の自治体で同じようなケースも存在すると思うんですけども、そういう点からすると、選挙管理委員会と品川区、同じだと思いますが、同一歩調をとっていって、国に対して法制度の変換を迫っていく、法の変更というんですかね、時代に則した形で変えていく形で、品川区にとっては当事者であろうと思うので、そのような形を要望していって、それを実現すれば。","respondent":"野田口選挙管理委員会事務局長、蓼沼高齢福祉課長","answer":"法律で改正すれば、それは可能です。ただ、先ほども言いましたように、議員の資格、任期が４年なのが３年になるとか、あるいは５年にするとかしなければ、なかなか法改正ができないわけですね。今のところ、地域バランスを考慮しながら、例えば都南病院跡地であるとか、原小学校跡のようにケアホームを整備し、あわせてグループホームも整備していこうというふうに考えて。","voiceIndex":73,"id":"exchange-029"},{"speaker":"大西委員","kind":"質問","question":"今グループホームのことにつきましては、現在品川区で認知症ということにおいて、入所したいというニーズをとらえてのグループホームをどれぐらいつくっていかなきゃいけないのかという認識をされているのかどうか、ちょっと薄かったように感じるんですが、そのところをもう少し詳しく教えていただけますか。","respondent":"蓼沼高齢福祉課長","answer":"今現在そういった認知症高齢者の増加の状況を踏まえ、あるいは特養等施設を申し込まれている方の状態などを勘案しますと、これからやはり計画的に一定程度地域バランスを考慮して、計画を進めていくということで、今現在、まだ整備を進め始めたような段階ですので。","voiceIndex":76,"id":"exchange-030"},{"speaker":"大西委員","kind":"質問・要望","question":"要するに品川区内６カ所しかないわけですから。耐震をやっていく中で、子どもを預かる場合のですね、そのスペースの確保ということと、この耐震ということを一緒の形で考えていく余地はあるのかどうかをちょっと教えてください。","respondent":"蓼沼高齢福祉課長、小林保育課長","answer":"ニーズにつきましては、例えば小山のグループホームが今月オープンの予定ですけれども、１ユニット９人のところに申し込みをされた方が約３０人というような状況です。保育園は児童センターと併設しているため、一緒に耐震改修、大規模改修をやることもあります。こうした場合には、児童センターの関係等も含めまして、全体の施設計画として考えてまいりたいと思います。","voiceIndex":78,"id":"exchange-031"},{"speaker":"藤原委員","kind":"質問","question":"５９ページの生活安全推進事業更正減額の防犯拠点整備事業についてお伺いしますが、まず、ここで３６５万２,０００円の減額をしておりますが、その内容と減額した理由をお尋ねします。","respondent":"金子生活安全担当課長","answer":"内容と理由ですが、荏原町駅前の跡地に建設予定の荏原町安心安全ステーションのことです。東急電鉄と警察との協議に時間を要しております。年度内の着工が難しいと、このために補正予算を打ち切りまして、来年度予算に再計上いたしております。","voiceIndex":83,"id":"exchange-032"},{"speaker":"藤原委員","kind":"質問","question":"それで、今課長のご答弁の中に東急と警視庁といいますか、荏原署でまだ話し合いがついていないということですけれども、何で区民の安全を守るという最重要的な施策なのに時間がかかっているんでしょうか。その辺の協議の内容についてもう少し具体的な答弁をいただけますか。","respondent":"金子生活安全担当課長","answer":"これは安心安全ステーションの敷地等の調整のためのものです。双方言い分を持っての調整ですので、交渉のようなものです。したがいまして、交渉の経過というものにつきましては、相手にも言い分がありますので、先ほどの答えでご理解いただきたいと思います。","voiceIndex":85,"id":"exchange-033"},{"speaker":"藤原委員","kind":"質問・要望","question":"課長にそれでご理解してくださいと言われちゃうと、これから質問ができなくなっちゃうかもしれないんですけれども、相手の言い分というのは東急側の言い分だと思うんですけれども、私たちとしては、大前提である区民の安心安全という形でいろんな意味で推進しているわけですけれども、そろそろ交渉の解決を見ないといけないという思いがあるんですけれども、その中で、まず見通しについて。","respondent":"早津区民生活事業部次長","answer":"この安心安全ステーションですが、ちょっと説明が足りない部分がありまして、新しいステーションができるためには、ちょっと敷地の問題等があるので、今まだ協議中だということなんですが、４月１日からは、当初予定どおり安心安全ステーションは立ち上げます。","voiceIndex":87,"id":"exchange-034"},{"speaker":"藤原委員","kind":"質問","question":"今私が初めに質問した形になるのは、具体的にはいつごろになるんでしょうか。","respondent":"早津区民生活事業部次長","answer":"相手のあることではありますが、なるべく早目にやりたいと考えていますので、年度が明けましたら、速やかに着工できるようにこれから進めてまいりたいというふうに考えてあります。","voiceIndex":89,"id":"exchange-035"},{"speaker":"藤原委員","kind":"質問","question":"それで、金子生活安全担当課長が、警視庁から品川区に派遣といいますか、来てくださって、いわゆる現場という形でお仕事をしてくださって２年たちますが、警視庁だと都民の安全なんですけれども、もうちょっと細かく区民の安全ということで現場に接していただいたと思うんですけれども、その辺で警視庁にいて仕事をなさっていたときと、本当の身近な自治体に来てくださって、そこで仕事をしたときの違いとか。","respondent":"金子生活安全担当課長","answer":"これにつきましては、私の能力も不足していたと反省しておるんですけれども、もう少々時間をかけないとこの問題は解決できないなという点もあります。もし、警視庁のほうへ帰りましたら、警察側には、区に対する柔軟性、こういったものを持ちなさいよと言っていきたいと思います。","voiceIndex":91,"id":"exchange-036"},{"speaker":"山内委員","kind":"質問・要望","question":"よろしくお願いします。確認なんですが、観光アクションプラン推進事業追加分、これが３３３万５,０００円ついておりますが、すみません、４８ページに都の補助金で産業経済費の補助金の２番で、観光案内標識設置事業補助金が３３３万５,０００円、これは収入という形でありますけれども、これと同じものなのかということをまず最初に確認させていただきたいんですが。","respondent":"金子産業振興課長","answer":"観光アクションプラン推進事業のお尋ねですが、委員ご指摘のとおり、歳入のほうの分とこの分がイコール、つまり、東京都の１０分の１０の補助でこの歩行者用案内標識を設置したものです。","voiceIndex":94,"id":"exchange-037"},{"speaker":"山内委員","kind":"質問・要望","question":"先ほど企画財政課長のほうから観光案内標識設置事業補助金で天王洲の水辺に標識をつけるというご説明があったんですが、これはまずどういうものなのかというのをちょっと具体的に教えていただきたいんですけど。","respondent":"金子産業振興課長","answer":"東京都としては、天王洲地域で案内標識を設置したいということで、私どもに照会がありました。私どもとしましても、天王洲地域で少し距離を延ばせば、旧東海道まで含めた形で可能かということで、これについて検討を進めてまいりました。","voiceIndex":96,"id":"exchange-038"},{"speaker":"山内委員","kind":"質問・要望","question":"多くなってきたというか、品川区のほうでもアピールをして、観光客を呼び込もうではないかという形でいろいろとしていただいておりますけれども、例えば街角サインというものはどうかなというのがありまして、例えばほとんど観光に来ていただく方というのは、品川にゆかりのない方が結構多いかとは思うんですけれども、その人たちが、例えば五反田に来ました。","respondent":"中川原広報広聴課長、金子産業振興課長","answer":"観光客の方にまちの案内を、サインをというお話ですが、品川区の場合、戸籍住民課でつくっている住所案内と、それから都市計画のほうでまちを案内する駅ごとにつくるサインにそういった観点を取り込みまして、ご案内をしています。案内板につきましては、来年度平成１９年度の事業でこの観光客の皆様にどういうふうに案内したらいいか、それは例えば駅におりたときの広域な案内図から、街角の小さな案内図まで。","voiceIndex":98,"id":"exchange-039"},{"speaker":"山内委員","kind":"質問・要望","question":"時間もなくなってきてしまいましたので、続きまして、商業地リフレッシュ推進事業の更正減額について、ちょっとお尋ねをさせていただきたいんですが、約１,４００万円が減額になっているということなんですけれども、これはどういう、もともと事業がありまして、それで結局事業が行えなかったという考え方でよろしいのか。","respondent":"金子産業振興課長","answer":"このうち、今ご指摘の小規模保育ルームについては、昨年の１１月にオープンしたわけですけれども、もう一店舗の予定については、計画を実施できなかったということで、主としてこういうような要因から減額したものです。","voiceIndex":101,"id":"exchange-040"},{"speaker":"山内委員","kind":"質問・要望","question":"北品川だけではなく、ほかにも空き店舗対策ということで、商店で空き店舗のところをうまく活用していただいた形でこのような事業をどんどんやっていただきたいと思っているんですけれども、今後何店舗ぐらいの予定というか、そういう計画があるのかというのを最後に教えてください。","respondent":"金子産業振興課長","answer":"各商店街に対しては、空き店舗のあるところについて、さらににぎわいが損なわれないような形でさまざま考えて計画していただいて、それについては、私どもとしましては、積極的に支援していく考えです。","voiceIndex":103,"id":"exchange-041"},{"speaker":"井上委員","kind":"質問・要望","question":"私のほうからは、８２ページの学校施設建設費と７６ページの都市開発費、それから６８ページの保健衛生を伺いたいと思います。最初に、先ほど来、ほかの委員の方の質問でちょっと確認をさせていただきたいのがあるんですが、４８ページの都支出金の都補助金の教育費補助金があるんですが、この補正額については、これはどこの歳出のほうに回っているのかということを教えていただきたいと思います。","respondent":"日下部企画財政課長","answer":"東京都の補助金のうち、教育費補助金、先ほどちょっとご答弁申し上げました小中学校の改築事業の特別交付金でありますけれども、こちらは８２ページのほうの学校改築の経費、こちらの財源として充てているものです。","voiceIndex":106,"id":"exchange-042"},{"speaker":"井上委員","kind":"質問","question":"８２ページの学校施設、今のところになるんですけれども、まず大井第一地区小中一貫校のこの補正なんですけれども、どういう理由で、このような補正に至ったのかということを詳しく教えてください。","respondent":"市川庶務課長","answer":"本体工事につきましては、平成１７年７月から昨年１２月までの１７カ月で本体工事を予定してございました。ところが、この本体工事、幾つかの事情があります。","voiceIndex":108,"id":"exchange-043"},{"speaker":"井上委員","kind":"意見","question":"解体事業の状況でということですが、解体に対してどうしてそれが本工事に至らなかったのかということをご説明ください。","respondent":"市川庶務課長","answer":"解体工事の実施時に、特に近隣の方からさまざまな苦情、陳情をいただきまして、それの調整に大変時間を要しました。解体工事は済んだものの、いわばその余波が残っておりまして、本体工事の着工時にその辺の、近隣との特に調整を改めてせざるを得なかった、こういう事情です。","voiceIndex":110,"id":"exchange-044"},{"speaker":"井上委員","kind":"質問","question":"余波というのがちょっとよくわからないんですけど、その解体工事をするに当たって、解体物が校庭に埋められてしまっていたというようなうわさとか、本当に設計どおりに基礎部分を解体していなかったとか、何かよくわからないうわさがあって、その辺のところで、この保護者の方たちの説明にも工事と調査がおくれているというような説明で。","respondent":"宍戸施設担当課長","answer":"それらの１カ月ぐらいの着工早々のおくれの部分がその後取り戻せなかった、そのような事情で本体工事の完成がおくれたというものです。","voiceIndex":112,"id":"exchange-045"},{"speaker":"井上委員","kind":"質問","question":"近隣住民との関係で言いますと、解体業者から建築業者まで一貫して行われることが、非常にそういった意味では長丁場、近隣の住民の方との関係をつくっていかなければいけないということで必要だと思うんですけれども、この工事の場合には、解体業者と建築業者などは一体だったのか、それとも別の業者がされていたんでしょうか。","respondent":"宍戸施設担当課長","answer":"今回の場合、本体工事の契約議案等がございまして、着工の時期がどうしても８月になってしまうということがございまして、やむなく解体工事は別の発注にしたというものです。したがって、別の業者です。","voiceIndex":114,"id":"exchange-046"},{"speaker":"井上委員","kind":"質問","question":"こういった問題で一番不利益を受けるのは子どもたち、本来であれば１２月、新学期から引っ越しができるという状況だったはずなのに、１月末に引っ越しをせざるを得なかったというところで、子どもたちに影響が出てきているわけですが、そのことについて、今後はどのような対応を、契約よりも、子どもたちとか教育現場の環境を優先するのか、契約のほうを優先せざるを得ないのかというところでは。","respondent":"市川庶務課長","answer":"今後、いろいろ工事の規模等によってまだまだ検討すべきことはあろうかと思いますけれども、基本的な考え方としては、そのように臨んでいきたいというふうに思ってあります。","voiceIndex":116,"id":"exchange-047"},{"speaker":"井上委員","kind":"質問・要望","question":"それから次は、先ほど来出ていたんですが、大間窪小学校の学校用地取得についての更正減額ですが、大変大きい金額だなというふうに思いますけれども、当初予算の２３億円というものの裏打ちというか、先ほど庶務課長が路線価と係数を掛けてということでしたけれども、この計算に至っては、一般財源であるのかどうなのかということと。","respondent":"日下部企画財政課長","answer":"大間窪小学校につきましては、先ほど庶務課長のほうからご説明させていただいたとおりですけれども、財源としましては、これは基本的には学校の国有地の買収につきましては、起債が適用されますので、かなりの部分について起債の活用を図ってあります。","voiceIndex":118,"id":"exchange-048"},{"speaker":"井上委員","kind":"質問","question":"かなりの部分というのは、具体的にはどのぐらいというふうに理解したらよろしいんでしょうか。","respondent":"日下部企画財政課長","answer":"失礼いたしました。実際には９割、取得価格の９割です。","voiceIndex":120,"id":"exchange-049"},{"speaker":"井上委員","kind":"質問","question":"それで、結果的には９億円ぐらいで取得ができたということは、予算立てとして結果的に先がわからないという状況はあるにしても、この後、更正減額の１３億円というのは、公共施設の基金に入っているのか、どこに繰り入れられているのかということをちょっとお伺いしたいんですが、そこら辺は。","respondent":"日下部企画財政課長","answer":"いずれにしろ、そういったトータルの中で今回の約１３億円の減というのがあるわけでありますけれども、一応基本的には先ほども出てまいりましたけれども、基金への積み立ても含めて、そういう形で活用したということでご理解をいただきたいと思います。","voiceIndex":122,"id":"exchange-050"},{"speaker":"井上委員","kind":"質問","question":"すみません、ちょっと質問が違ったかな。１３億円というのは、使わなかったわけですから、どこかに収入として組み込まれていると思うんですけど、どこに入るんでしょうか。","respondent":"日下部企画財政課長","answer":"先ほど全体の９割が起債でということでありましたけれども、当初の段階でも、要するに９割ほど見込んでおりました。","voiceIndex":124,"id":"exchange-051"},{"speaker":"井上委員","kind":"質問","question":"ちょっと先ほどの基金のところで疑問があったので伺わせていただきました。次は、７６ページの都市再生総合整備事業更正減額についてですけれども、それぞれ理由を、小関橋はいいですから、大崎駅東口歩行者デッキから３項目の更正減額について説明してください。","respondent":"青木都市開発課長","answer":"西口デッキにつきましては、現在施工中ですけれども、これは駐輪場とあわせまして、出来高を年度ごとにチェックしている中で予定どおりの出来高が上がっていないということで減額更正したものです。","voiceIndex":126,"id":"exchange-052"},{"speaker":"井上委員","kind":"質問","question":"夕張市のことも含めて、そういう意味では、こういう資料提供の中で既にわかっているようなものの変更、都市開発の部分だけではないですけれども、結構都市開発の部分で言うとわかりやすく提示できるのかなというふうに思うんですけれども、そういった資料提供などはどんなふうにお考えなのかお伺いします。","respondent":"日下部企画財政課長","answer":"冒頭で、私のほうから全体の概括的なご説明をするということで審議をお願いしているところでありますので、その辺はご理解いただきたいと思います。それから、予算特別委員会の資料ということで今回も出しています。","voiceIndex":128,"id":"exchange-053"},{"speaker":"井上委員","kind":"質問・要望","question":"６８ページの保健衛生なんですけれども、先ほども質問で出ていました不妊治療相談・助成事業の更正減額で、更正とした理由が２５０組を当てにしたところが、１６件であったとか、そういったところは理解をしていますけれども、相談人数のほうでは、これは決算になってしまうかもしれませんが、補正で出ていますので、ちょっと伺いたいんですが、相談人数がどれくらいあったのかということと。","respondent":"谷田部健康課長、倉橋品川区保健所保健サービス課長","answer":"２点目のほうのご質問にお答えいたします。先ほど人工受精、それからその他検査治療、それぞれ分けて制度を設定いたしました。相談の人数ですが、１６名ということで、６回程度の回数で１６名、予約がそれ以上何例かございましたけれども、実質１６名ということで実施しております。","voiceIndex":130,"id":"exchange-054"},{"speaker":"原（雅）委員","kind":"質問・要望","question":"８３ページの大井地区小中一貫校の解体につきまして、先ほど質問が出ていましたので、関連をします。どういう形にしろ、解体あるいは新築工事がちゃんといっているか、いっていないかということは、周りの住民が見ていながら、よく知っていないというのが現状であったと思うんです。ですから、今後の中でも、それは十分気をつけていただきたいのと、更正減額の中の解体なんですが、今既に始まっています。","respondent":"宍戸施設担当課長、市川庶務課長","answer":"今委員ご指摘のとおり、工事工程の変更については、住民説明会等行っておりません。そういう意味では、周辺住民の方々へのご説明は不足していたと反省しております。３点目のただいま行ってあります第２期の解体工事と外構・校庭の整備ですけれども、特に４月の伊藤学園の開設当初と時期的に合致するということがありますので、学期初めの、特に新入生の対策を含めまして。","voiceIndex":134,"id":"exchange-055"},{"speaker":"原（雅）委員","kind":"質問・要望","question":"この工事そのものが今見ていますと、相当やっぱりある程度大がかりな形で解体が進められていますよね。それが前回のような形にならないように、やっぱり工程どおりに進むような、前のところと違ったところと契約されているんだろうと思うんですが、その辺の状況だけもう一度教えていただきたいと思います。","respondent":"市川庶務課長","answer":"本体工事の遅延から一連の経過を十分に承知しておる事業者ですので、そのことも含め、また特に今回の４月のぎりぎりの工期の設定というのがどういう意味を持っているか、先ほど私が申し上げた学校側の負担を極力軽減し、近隣への負担も軽減する方向で調整に努めてまいります。","voiceIndex":137,"id":"exchange-056"},{"speaker":"飯沼委員","kind":"確認","question":"耐震補強等の交付金については、午前中も質問がありましたので、ちょっと確認の意味で、この国庫補助金のところでは、３分の１ずつで、工事費は毎年これからも確保されるのかどうか、その点と、小中、あと幼稚園も含めて耐震診断は平成１８年度ですべて済んでいるのかどうか。補強工事、残っているところが、先ほど２０校かなと思うんですが、平成２０年度までに補強工事を行う。","respondent":"市川庶務課長、宍戸施設担当課長","answer":"今後の工事の耐震補強が必要となる学校の校数ですけれども、これについては、来年度、新年度の予算に関係する分が出てまいりますが、現状来年度の補強工事、小学校で６校、中学校で２校予定しています。耐震診断、児童施設ですが、平成１８年度ですべて耐震診断を終わっておりまして、平成１９年度、２０年度で工事はすべて終わる予定です。","voiceIndex":140,"id":"exchange-057"},{"speaker":"飯沼委員","kind":"質問・要望","question":"助成率がなかなか思わしくなくて、力を入れて何とか早く耐震工事を進めたいという国の思いがあるということがわかりましたけれども、昨年、文部科学省のところで公立学校施設の耐震改修状況調査結果というのを区町村レベルのところで発表して、そのときに品川区の耐震状況がすごくレベルが低いというのが載って、あと、品川区のホームページを見たらば。","respondent":"市川庶務課長","answer":"第２期、平成１５年度から耐震診断を実施した部分につきましては、これは文部科学省の基準としています０.７という基準値を用いて耐震補強を行って現在に至ってあります。","voiceIndex":143,"id":"exchange-058"},{"speaker":"飯沼委員","kind":"質問・要望","question":"だから、きっとどこかに予算が入ってはいると思うんですが、私は具体的にこれがどう行われたのかなというのをちょっと今日お伺いしたいなと思っていたので、例えばいつの時期に何年ぐらいかけて、だれがここを担当して調査をしたのかということと、耐震診断の１校の額とか、耐震工事の額とかが、今現在やられているのと比較して、どのぐらいの金額で行われていたのかというのが。","respondent":"市川庶務課長","answer":"第１期のときの耐震診断、これは平成８年度、９年度、２カ年にわたって実施をしています。このときの診断を担当いたしましたのは、区の技術系職員が診断を担当しています。","voiceIndex":145,"id":"exchange-059"},{"speaker":"飯沼委員","kind":"質問・要望","question":"学校は子どもたちの１日の結構長い時間を過ごす大切な場でもあるし、地域の防災拠点という面では、より本当に安全性が求められていくと思うわけなんですけれども、今、区の職員が図面を見て診断をしたということなんですけれども、この辺の調査をするに当たっての基準の設定というのは、品川独自のものだったんでしょうか。","respondent":"市川庶務課長","answer":"したがって、当時実施いたしました耐震補強工事については、一切国庫補助は受けてございませんし、それがわずか数年の違いとはいえども、平成１５年度から私どもが第２期として対応しているところの事情としては、大きく違っている。","voiceIndex":147,"id":"exchange-060"},{"speaker":"飯沼委員","kind":"質問・要望","question":"４９ページの改築事業特例交付金のところに移るんですが、冒頭に伺った、今までなかなか耐震補強が進まないというところにおいて、全面改修から建て替え方式に、国のところが改修方式に転換をしていったという話も聞いたことがあるんですけれども、この辺で、品川区はかなりここのところ、学校改築も進んでいるわけですけれども、耐震補強との関係で、改修にするのか改築にするのかという。","respondent":"市川庶務課長","answer":"一切その点では問題はないという認識を持ってあります。それと、２点目の耐震補強に当たって、補強なのか、建て替えなのかですけれども、これは補強工事のできる施設については、原則補強工事で対応する、こういう考え方を持ってあります。","voiceIndex":149,"id":"exchange-061"},{"speaker":"飯沼委員","kind":"質問・要望","question":"それが一つと、あと最後になったんですが、認証保育園の運営助成のところなんですけれども、利用者増による助成増というところなんですけれども、助成の基準のところなんですけれども、品川区内に住んでいらっしゃる方と区外に住んでいらっしゃる方の違いがあって、保育園が足りなくて、よそから来たり、よそに出たりという方が助成を受けられなくて運営が大変だという声を聞いているんですが。","respondent":"市川庶務課長、小林保育課長","answer":"今後の学校の改築、それから改修、これにつきましては、現在進めております耐震補強、これに喫緊の課題として取り組んですので、その次の段階で検討すべきもの、そういう認識です。そういった意味では、他区の方に対しては、補助金の交付外となっております。ただ、この認証保育所の制度の基本が、東京都で制度設計されたものですので、２３区ほぼ同様の対応、基本は同様になっております。","voiceIndex":151,"id":"exchange-062"},{"speaker":"飯沼委員","kind":"質問・要望","question":"品川区内の認証に入れなくて、お隣の区に出っ張ってしまった方がいらっしゃるので、そういう方にも助成を受けられるようにしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":154,"id":"exchange-063"},{"speaker":"原（浩）委員","kind":"質問・要望","question":"午前中にお二方、午後またお二方、非常に耐震のことについて、この委員会、中心的に話が集中しておりますけど、実は私も耐震経費のことについてお伺いしたいと思います。それはページ数が４７および８１です。それからもう一点、目黒川右岸低地部の排水設備整備の関連についてお伺いしたいと思います。これが耐震の経費についてのご質問です。","respondent":"宍戸施設担当課長、原田下水道河川課長","answer":"横浜方式です。民間対象の方式かと思いますけれども、区有の施設の場合は、適切に民間に委託化しながら効率よく進めているということで、ちょっと横浜方式とは違うやり方でやっているかと思います。平成２１年度完成予定ですけど、これは完全に区のスケジュールで区が検討した結果、平成２１年度末完成予定ということにしております。","voiceIndex":156,"id":"exchange-064"},{"speaker":"若林委員","kind":"質問","question":"小関橋の架け替え工事の債務負担行為です。総務委員会に出されました案件の中でご説明がございまして、平成１７年９月に起きた都内の集中豪雨、これはたしか中野区、杉並区方面だったと思いますけども、これに関連をして要請があったです。そこで、もう少し詳しく、平成１７年９月の事例がどういうものか、また、なぜこれが目黒川においても適用されてしまうのかというところをお聞きしたいと思います。","respondent":"青木都市開発課長","answer":"平成１７年に契約されて以降、準備工等あるいは現場、仮設の橋をかけるという工事等進めてきたんでありますけれども、このたび、平成２０年、当初予定しておりました工期までには、どのみち完了できないということが明らかになりましたので。","voiceIndex":160,"id":"exchange-065"},{"speaker":"若林委員","kind":"質問・要望","question":"そうしますと、ここまでやってきた品川区の努力というものが、東京都に対しては、関係機関というのは東京都というふうにお聞きしましたけども、どのように理解をされて、その強い要望に対しては品川区として、区の立場からの事情説明、これは１カ年延びるわけですので、そこら辺のお話し合いの様子というのをお聞きしたいと思います。","respondent":"青木都市開発課長","answer":"私どもも強く当初の計画どおりにやりたいという協議は進めてまいりましたけれども、中野区や杉並区の被害状況を見ますと、やはり川に突起物があったような橋の部分などでの決壊等という報告がありましたので、そういったことを勘案しますと。","voiceIndex":162,"id":"exchange-066"},{"speaker":"若林委員","kind":"質問・要望","question":"はい、わかりました。債務負担行為によって１カ年延びるです。それで、今後は目黒川、さまざまな水とみどりのネットワーク構想等、公園等がまた整備をされていくわけですけれども、今回の東京都の指導が、今くいを打つというような表現もありましたけれども、今後の目黒川の再生について、どのような影響があるか、想像できるものがありましたらお教えいただきたい。","respondent":"青木都市開発課長","answer":"東京都の指導というのは、施工においての安全性確保というところに主眼が置かれておりますので、私ども今進めております目黒川周辺での整備、環境整備等については、何ら今後も支障があることはないと考えています。","voiceIndex":164,"id":"exchange-067"},{"speaker":"若林委員","kind":"質問","question":"船のことにまで言及していただいて、ありがとうあります。それから次に、財政全般の問題、昨年夕張市の財政破綻のニュースが飛び込んでまいりまして、自治体がまさか破綻をするということは想像もしていませんでしたので、大変に大きな、各自治体にとってはニュースだったわけだと思いますけれども、自治体が財政破綻をするということは、どういうふうに受けとめればよろしいんでしょうか。","respondent":"日下部企画財政課長","answer":"人口もたしか１２万人が１割ぐらいにまで激減してしまった。しかも、離職率が非常に高くなりましたから、生活保護の割合も高くなった、高齢化の割合も高くなった。そういう中で、税収が減って、行政需要が大幅に増えましたので、そこで借金に頼ろうとした。","voiceIndex":166,"id":"exchange-068"},{"speaker":"若林委員","kind":"質問","question":"大変ご丁寧な答弁、ありがとうあります。最終的には今ご説明があったようないわゆる予算の中であらわれてこない一時借入金というんでしょうか、そういうもの、これは議会もいわゆるチェックしようがなかったという記事も読ませていただきました。もう一重、品川区の今後の健全財政についてのご努力、取り組み、また議会への説明等ご説明いただければと思います。","respondent":"日下部企画財政課長","answer":"三位一体改革で、トータルでいけば２０億円ぐらいの減収という問題も出てきますし、今後少子高齢化に伴う財政需要の問題とか、いろいろ要因的にはそう楽観できない状況ではありますので、さらに一層今後とも行財政改革を徹底していく必要があると、このように考えております。","voiceIndex":168,"id":"exchange-069"},{"speaker":"木下委員","kind":"質問・要望","question":"こちらの差のある部分といいますと、現場の部分、民間企業で技術の継承ということで、定年後もそのまま継続して働いてもらって、若い方々の後進指導に当たってもらうという形で、その２００７年問題と言われている部分を乗り切ったりですとか、いろいろな採用状況だとか、いろいろな形でご努力されていると思いますけれども、区としてはその問題に対してどのような対策等。","respondent":"榎本人事課長","answer":"１点目の給与費のほうの関係ですけれども、冒頭に企画財政課長のほうから説明がありましたように、平成１８年度の当初予算の経費につきましては、平成１７年１０月１日の現員現給をもとに見積もりを立てているところです。","voiceIndex":171,"id":"exchange-070"},{"speaker":"木下委員","kind":"質問","question":"かしこまりました。続きまして、６６ページ、生活保護費の部分について、ちょっとお尋ねしたいと思います。そういう意味では、減の中身ですかと、原因ですとかをお教えいただければと考えています。それから、今後の生活保護の将来的な状況というか、品川区で、将来的にはどういう形で推移していくと見ていらっしゃるのか、そこら辺を、ちょっとお聞かせ願えますでしょうか。","respondent":"志村生活福祉課長","answer":"こうした関連で、今回、大きくこうした扶助費の減ということになってきております。これにつきましては、平成１８年度当初予算の策定に当たりまして、これからの増加が見込まれておりましたので、平成１７年度予算から扶助費を３％ほど伸ばしたものです。","voiceIndex":173,"id":"exchange-071"},{"speaker":"木下委員","kind":"質問・要望","question":"急に元気になるというのも、ちょっと考えられないんですけれども、そこら辺の原因というか、その中身、どのように考えていらっしゃるのか教えていただきたい。それから、先ほど、就業支援ということで、効果が上がったんじゃないかというお話をお伺いしましたけれども、どのような効果が上がっているのか、もうちょっと詳しく説明していただければありがたいと思います。","respondent":"志村生活福祉課長、青山品川区保健所長","answer":"１件１件個々に当たってはございませんけれども、私どもからしますと、かかっているお医者さんから退院ということになりますと、この後は居宅で受け入れということで、ケースワーカー等で対応しているものです。これは、精神障害者の方たちの社会的な自立支援という意味をも含めてなんですけれども、一方において、精神科病床を維持していくことが、病院にとっても難しくなっている現状もあります。","voiceIndex":175,"id":"exchange-072"},{"speaker":"木下委員","kind":"質問","question":"今、ちょっとご説明をお伺いして、要するに、経営が成り立たないので、そういう病床を閉鎖しているというようなことなのかなと。閉鎖というか、だんだん少なくされていらっしゃる。だから、入院されている方が減っている。逆に言ったら、悪いですけれども、追い出されているというふうな感じでも聞き取れたんです。時間がなくなっちゃったので、これで終了します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":178,"id":"exchange-073"},{"speaker":"伊藤委員","kind":"確認","question":"私は、８３ページの第一日野小学校基本設計更正減額について。それから、ページは全体にわたる話ですけれども、品川区事業の外部委託、指定管理等々、広い意味で、そのあり方について質問しようと思います。改めて、なぜ計画を見直ししたのかという背景を、確認してお伺いしたい。それから、今後の計画のスケジュールについてお聞かせください。お願いいたします。","respondent":"市川庶務課長、日下部企画財政課長","answer":"平成１８年度に、第一日野小学校の校舎改築の基本設計への着手を予定してございましたが、並行して、小学校の改築敷地となる。そうした中で、当初は、平成１８年度の段階で基本設計、それから実施設計ということで手順を踏んでまいりましたけれども、今。今後のスケジュールですけれども、来年度、平成１９年度に第一日野小学校の校舎改築、文化センターの改築、教育総合会館の改修。","voiceIndex":180,"id":"exchange-074"},{"speaker":"伊藤委員","kind":"確認","question":"品川区本体の行財政改革を進めるということは、もちろん結構なんですが、ただ結果として、こういう方々が品川区の仕事を一部負担しているわけですから、具体的に個々の事例を挙げると大変膨大になると思われますので、ざっくりとした部分で確認したいのが、そういう事務事業を外に出す場合には、関係する団体とどういう協議を行い、あわせて財政の手当。","respondent":"日下部企画財政課長","answer":"その辺については、個々のケースもありますけれども、今後、一つの大きな流れとして、地域との連携を進めていく上でいかにあるべきかと、その辺についても、今後の検討課題として受けとめていく必要があるのではないかと、このように考えております。","voiceIndex":184,"id":"exchange-075"},{"speaker":"伊藤委員","kind":"質問・要望","question":"ですから、これからの品川区の仕事を進めていくに当たっては、もし地域との連携を進めていくんであれば、いろいろな関係する団体に対しては、さらにその財源の調整、それから権限の移譲は難しいかもしれませんけれども、でも、大きく言えば、品川区の仕事の一端を担ってくださっているわけですから、責任は公務員と同時にどんどん重くなっていく可能性があるわけですから、やっぱりそういうことに対して。","respondent":"日下部企画財政課長","answer":"実は、これにつきましては、明日以降の平成１９年度予算の中でも、またご提案をする予定でございましたが、例えば、今ご指摘にありましたように、地域の団体に、いろいろ地域の環境整備ということでご協力をいただいております。","voiceIndex":186,"id":"exchange-076"},{"speaker":"伊藤委員","kind":"質問・要望","question":"これからは、ほかの考え方かもしれませんけれども、要望ですけれども、２００７年問題、団塊の世代の方々が入ってくる。当然、こういう方々のパワーも地域につなげていくことが大きな課題となっていくわけですから、入り口は非常に小さい話かもしれませんけれども、これは相当根が深い問題だと、私は思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":188,"id":"exchange-077"},{"speaker":"安藤委員","kind":"質問・要望","question":"私からは、８７ページの生涯学習施設費の図書館経費更正減額、職員給与費のところで、お尋ねしたいと思います。２,９９６万円余の減ということなんですけれども、まず、この中身を教えていただきたい。","respondent":"工藤品川図書館長","answer":"図書館経費更正減額の中身です。こちらのほうは、私ども、平成１７年度から平成１８年度にかけて定数減がございました。内容としましては、正規職員のマイナス２名、そして、再任用職員のマイナス２名、嘱託員のマイナス１名のトータルのいわゆる人件費分の減です。","voiceIndex":190,"id":"exchange-078"},{"speaker":"安藤委員","kind":"質問","question":"そういった定数減になった部分というのは、いわゆるその業務は、かわりに違うところに依頼になると思うんですけれども、それは区長の所信表明演説にもございましたけれども、図書館窓口の民間委託ということでよろしいんでしょうか。","respondent":"工藤品川図書館長","answer":"民間委託による減か、どうかというお尋ねです。私ども、民間業務委託は平成１６年４月からやっております。平成１６、１７年度という形で、業務委託による、いわゆる人員減というのをやっております。","voiceIndex":192,"id":"exchange-079"},{"speaker":"安藤委員","kind":"質問","question":"委託先の職員数というのは把握してございませんという答弁がよく返ってくるんですが、あわせまして、一般的な区内の図書館が開館して閉館まで何時間かあると思うんですが、その１日の業務内での職員の配置の数といいますか、一般的な区内の図書館で、正規の職員は何人で、非常勤は何人で、委託会社の窓口を担っている派遣社員は何人ぐらいで、平均的に一日の業務を回しているかというか。","respondent":"工藤品川図書館長","answer":"それぞれ、いわゆる現状に応じた配置をしているということで、１館当たり幾らという部分は持ってございませんけれども、品川図書館の正規職員数で言いますと、今、１０館あるわけですから、正規職員が７１名ということですから、１館当たりそれに応じた数を配置しているです。","voiceIndex":194,"id":"exchange-080"},{"speaker":"安藤委員","kind":"質問","question":"平成１６年度から窓口の受付業務を民間に委託を始めて、平成１７年度に全館に広げたということで、今年度、さらに広げるということなんですが、窓口業務をどうして民間委託させるのかという、その基本的な考え方をお伺いしたい。","respondent":"工藤品川図書館長","answer":"委託導入の目的ですけれども、さまざまな施策を推進するに当たりまして、効率的、効果的な執行体制を目指すということは、従来から区の方針だと考えております。","voiceIndex":196,"id":"exchange-081"},{"speaker":"安藤委員","kind":"質問","question":"そういったことであれば、やはり私は、ふさわしい均等待遇というんですか、そういう高度なサービスを提供している皆さんにも、きちとした待遇というのを保障してあげるべきだと思うんです。そういう方が、いわゆるワーキングプアの状態に置かれているということに対して、やはり区はきちんとした待遇を保障するべきだと思うんですけれども、この点に関しての認識はいかがでしょうか。","respondent":"榎本人事課長","answer":"これは、本会議でも答弁いたしましたように、民間企業が雇用条件等を決めるのは、契約によって決まっているものですから、区が実際に働いている人の賃金等を云々すべき問題ではないと、考えております。","voiceIndex":198,"id":"exchange-082"},{"speaker":"須貝委員","kind":"質問","question":"私は、５９ページ、公共施設整備基金積立金追加分と、８１ページの学校管理費についてお聞きしたいと思います。そのために、経常収支のほうが、今回、２５億円前後プラスになっていますが、９２億円は残ったわけですから、それをどうして一般会計のほうに、いわば経常収支がさらにプラスになりましたよと報告しないのか、その処理についてお聞かせください。","respondent":"日下部企画財政課長","answer":"９２億円の対応の仕方ということでありますけれども、私どもは、基本的にこういうふうに考えています。","voiceIndex":201,"id":"exchange-083"},{"speaker":"須貝委員","kind":"意見","question":"それをちょっと第１点。本来は、国とか都のほうでお金を出して、学校というのは改築を進めるべきものだと思います。私たち品川区のほうでは、本当に皆さんの財産を大切に使っていますよというような、目で見えるような意思表示を子どもたちにも、区民にも、そういうことを訴えるような態度、行動も必要じゃないかと思うんですが、その辺、ちょっとご見解をお聞かせください。","respondent":"日下部企画財政課長、市川庶務課長","answer":"先ほどの９２億円の話でありますけれども、ちょっと繰り返しになるかもしれませんけれども、逆に積立金として、つまり公共施設の整備基金という明確な目的がはっきりしているわけですから、そこに積み立てをすることによって。ただし、実際に、これまで改築の対象としてまいりました学校について見ますと、建築年次なり、あるいは棟の続き方なり、立地環境といったものを総合的に見て。","voiceIndex":205,"id":"exchange-084"},{"speaker":"須貝委員","kind":"質問・要望","question":"今、原則のほうはわかりました。ちょっと周りの自治体を見たら、どうでしょうかね。その辺を考えたときに、やっぱり、今、大変な自治体もあるわけですから、品川区としても、その辺はちょっと考えることが必要じゃないかなと思います。その中で、じゃあ、そのお金がどういうふうに流れたとか、そういうことまでは、果たして読み取れるものでしょうか。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":208,"id":"exchange-085"},{"speaker":"本多委員","kind":"質問","question":"５９ページの退職手当追加分を聞いていきます。その後で、７１ページの職員給与費追加分。いろいろなページに載っているんですけれども、主に７１ページの環境清掃事業部あたりを中心に聞いていきます。初めに、５９ページの退職手当追加分。当初予算では１８億円に対して、補正額６億９,０００万円ということで、まず理由ですとか、人数ですとか、状況を教えてください。","respondent":"榎本人事課長","answer":"ということで、その追加分６億９,０００万円ということで、補正で組まさせていただいたものです。","voiceIndex":211,"id":"exchange-086"},{"speaker":"本多委員","kind":"質問・要望","question":"予定よりも５０人の追加ということなんですけれども、退職される方には、当然さまざまな理由があると思います。当然あいてしまったところを補うという部分で、組織力を挙げて努力されている点について、ちょっと教えていただきたいと思います。","respondent":"榎本人事課長","answer":"その対応としては、係長、係内主査等の異動の年次が重ならないようにするとか、所属課長との異動の年次が重ならないようにするとか、そういう人事異動での対応の中での適材の中でも、組織力を維持していこうという考え方に基づいております。","voiceIndex":213,"id":"exchange-087"},{"speaker":"本多委員","kind":"確認","question":"いろいろなケースがあって、本当にご苦労されたり、努力をされたりして、組織を挙げていろいろご苦労されているんだろうなと考えています。前倒しをすることによって、そういう手当ですとか、なければいいなと思っています。そういう視点から、以前は、５７歳までの勧奨退職がありましたけれども、今、もろもろの手当等、そういうものがないか、確認をさせてください。","respondent":"榎本人事課長","answer":"そういった意味でも、きちんと定年まで勤めていただくという前提のもとに、区の職員の活動を図っていくという考え方です。","voiceIndex":215,"id":"exchange-088"},{"speaker":"本多委員","kind":"質問・要望","question":"これからも、先ほども出ていましたけれども、行革での視点で、定数削減等をされていくんだと思います。２００７年問題等も出ておりましたけれども、これから新しい人材を採用していくに当たりまして、これからの人事考課の制度がどう変わるかはわかりませんけれども、基本的には、一般論としては、定年まで勤めるというか、その辺の考え方について教えていただきたいと思います。","respondent":"榎本人事課長","answer":"特に新規採用につきましては、今後、１００名を超える定年退職者がここ１０年間続きますので、同じ数ではありませんけれども、それに見合う、今までのレベルとは違うかなりの新規採用を考えなければならないときにきております。","voiceIndex":217,"id":"exchange-089"},{"speaker":"本多委員","kind":"質問","question":"その人事考課の制度は、これから時代とともに変わりつつあると思いますが、やはり住民本位ということで、勤め上げるといいますか、そういう方針といいますか、よろしくお願いしたいと思います。その中で一番目立ったのが、７１ページの環境清掃事業部の６,５９９万３,０００円の増と、７３ページのまちづくり事業部の２億６,６２３万９,０００円の減ということで、まずこの内容について教えてください。","respondent":"榎本人事課長","answer":"職員給与費が減した部分を、先ほどの退職手当の部分が補っていますので、昔で言う職員給与費の全体でいきますと、７,８００万円ほどの減という形になってあります。","voiceIndex":219,"id":"exchange-090"},{"speaker":"本多委員","kind":"質問","question":"一つだけ、ちょっと聞きますが、６１ページの地域センターの職員費が、ここでも減になっているんですけれども、この辺の理由といいますか、教えてください。","respondent":"田村地域活動課長","answer":"もう１点は、武蔵小山のサービスコーナー設置に当たりまして、研修という形で地域センターに配属しておりました。","voiceIndex":221,"id":"exchange-091"},{"speaker":"本多委員","kind":"確認","question":"当初予算のときに、先ほどの図書館ですとか、地域センターですとか、見積もりというか、もう少し読めなかったのかなと思って、ちょっと確認で聞かせていただきました。結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":223,"id":"exchange-092"},{"speaker":"山路委員","kind":"質問","question":"精神障害者施設の「たいむ」ですが、平成１７年度に区独自の事業としてスタートされ、昨年、三位一体改革の補助金がなくなる中で交付金として交付金化され、福祉施策の包括補助金としての、区の独自事業にこっちの補助金が入るようになって、地域にも受けいれていただきまして、非常に全国の先陣を切ったといいますか、地域と障害者の家族の方がうまくいって、スタートして約１年半ぐらい経ちますが。","respondent":"西島障害者福祉課長","answer":"当初は、区の独自の施設として開設をしたわけですけれども、東京都との交渉の中で、都が半分を補助金としての独自に拠出するということで、平成１８年度で言いますと、まだ確定はしてございませんが、生活支援センターの事業費が約２,１８０万円余ですが。","voiceIndex":225,"id":"exchange-093"},{"speaker":"山路委員","kind":"質問・要望","question":"まだ具体的には財政の見通しはついてないのでしょうか。そのまま都の包括補助金が充てられる可能性は高いんでしょうか。その辺を、もう少し掘り下げて聞かせていただきたいと思います。","respondent":"西島障害者福祉課長","answer":"本来ですと、自立支援法ということで、３障害、身体、知的、精神ということで、同一の枠組みになります。同一の枠組みになりますと、いわゆる精神障害者の生活支援センターは、地域生活支援事業の枠組みに入ってまいります。","voiceIndex":227,"id":"exchange-094"},{"speaker":"山路委員","kind":"質問・要望","question":"款別がちょっと違うところで聞きまして、申しわけございません。いわゆる地域における障害者の就労支援と、精神障害者の「たいむ」の拡充と、自立支援法によりまして、非常にいろいろな区民の方のご意見、ご要望聞いておりますと、まだまだ悩みは深いところがあるようですので、さらなるご努力で、充実と拡大をお願いして終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":231,"id":"exchange-095"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１５４ページの介護保険会計についてお聞きしたいと思います。基金の繰入金が減額になっていますけれども、介護保険の第３期の計画では、基金を取り崩して保険料を安く設定するという計画になっていたかと思うんです。その計画に対して現状がどうなっているかということに対しても、お聞かせいただきたいと思います。","respondent":"蓼沼高齢福祉課長","answer":"現実に、平成１８年度につきましては、この補正予算にありますように、補正をして約４,４００万円の取崩し、平成１９年度については、これからご審議いただく予定ですけれども、１,１００万円ほど取崩しを予定しているという状況です。","voiceIndex":233,"id":"exchange-096"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"４,４００万円の、２年目が１,１００万円というと、５,５００万円ということですけれども、５億３,０００万円取り崩す中で、１年目と２年目で５,５００万円ということですと、３年目で残りの４億七、八千万円になるんでしょうか、それぐらいの額を取り崩すということになるのか。そのことを一つお聞かせいただきたい。この給付ができなくなったことによって、どれぐらい給付費が減額になったのか。","respondent":"蓼沼高齢福祉課長","answer":"軽度者への福祉用具の見直しの関係です。平成１８年度の当初予算と、平成１８年度末の実績の見込みから申し上げますと、約１億８,０００万円ぐらい、福祉用具に関しては給付が減しているという状況です。","voiceIndex":235,"id":"exchange-097"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１％ですか、本当にわずかな額だと思うんですね。スリーモーターはこの方に必要ないというご答弁だったんですけれども、それであればワンモーターとか、ツーモーターとか、これだけの９５.５％の方がベッドを使わざるを得ないという状況の中で、改めて介護ベッドについて、このベッドが使えなくなった方の中に、必要な方がいると思われないか、どうか、その認識についてお聞かせいただきたいと思います。","respondent":"蓼沼高齢福祉課長","answer":"９５％の方の中にも必要な人がいるのではないかというご指摘ですけれども、それについては、はっきり何とも申し上げられないところですけれども、国のほうで示した基準が、実際に、昨年、各自治体のほうで調査をして、なかなか判断が難しくて。","voiceIndex":237,"id":"exchange-098"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"だって、やっぱり９５.５％の方がベッドを使わざるを得ないというこういう現実の中で、やっぱり必要な人がいるんだとは認識されないでしょうか。改めて、ご答弁いただけないでしょうか。","respondent":"蓼沼高齢福祉課長","answer":"必要ありや、なしやの判断は、なかなか難しいものがあると思います。ただ、これは介護保険の制度上、調査項目でその給付を認める。そういう取り扱いになっておりますで、それに従って、区としては、利用者にご理解をいただいてきたと考えております。","voiceIndex":239,"id":"exchange-099"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"実際は、もうどうにもならなくて、取り上げられたというのが利用者の思いで、その中には大きな不満になっている。国がこういうふうに出して初めて、国の言うとおりにするというのではなくて、やっぱり国に改善策を求めていく、実際に介護が必要な方のところの実態を一番よく把握している品川区が、その改善策を国に求めていくという姿勢こそ必要なんじゃないかと思うんですけれども、いかがでしょうか。","respondent":"蓼沼高齢福祉課長","answer":"利用者と接する身近な自治体として、というご指摘ですけれども、これにつきましては、２３区の場でもいろいろ論議もしました。都を通じて働きかけということも、課長会の中でも論議がありましたけれども、実際問題、なかなかその場では、国の基準を変えるような形での……。","voiceIndex":241,"id":"exchange-100"},{"speaker":"松澤委員","kind":"質問・要望","question":"短く３点聞きたいと思います。５２ページの不動産売払収入、７,４００万円のところ、補正が１億２,３７２万２,０００円、これの内容をお知らせいただきたいと思います。橋さえ完成すれば散歩はできるのかなと思うんですが、どの部分の工事が終わらないのか、あるいは、いつごろすべて完成するのかについて、お聞かせいただきたいと思います。","respondent":"中島経理課長、市川庶務課長、松代管理工事課長","answer":"１点目の不動産売払収入につきまして、ご説明申し上げます。補正前の７,４００万円から１億２,３７２万２,０００円の補正をしたものです。結果的には、国との交渉の中で５６万円の単価が、路線価の約１.３倍相当の４６万円に落ち着きまして。そういった関係から、今、工事が少し延びているところでございまして、一応、完成目標は平成１９年８月ぐらいを予定しています。","voiceIndex":244,"id":"exchange-101"},{"speaker":"松澤委員","kind":"質問・要望","question":"これが、１０年工事があるんだったら、まだ工事が始まらないかもしれないということはあるけれども、残り３年なんですから、もうせっぱ詰まっているところで、何でこれを本予算に載せられなかったのか、ここをお答えいただきたいと思います。１.６倍の計算が１.３倍だった。ところが、２分の１に減免になった、これはもともとわかるんじゃないですか、国有財産２分の１減免は。","respondent":"中島経理課長、市川庶務課長、松代管理工事課長、日下部企画財政課長","answer":"一方で、タコ公園の機能を少しでも生かしたいということで、道路の反対側に東京都の所有の用地があるんですけれども、そことの関係で。大間窪小学校の国有地購入の予算の立て方ですけれども、確かに、これまで、校舎改築に関連いたしまして、第二延山小学校、小山小学校。戸越公園の公園利用者の皆様へのお知らせですけれども、工事区域をフェンスで囲っていますところに、３カ所ほど。今、所管課長からもるるご説明させていただきました。","voiceIndex":248,"id":"exchange-102"},{"speaker":"西本委員","kind":"質問・要望","question":"７ページの歳入について、それから６５ページの子どもすこやか医療費、それから認証保育所運営助成、それから、保育園運営費、児童センター運営費の中のそれぞれの職員費について、８１ページの学校環境整備事業の中の、校舎等の整備について、質問いたします。入る前に、今の松澤委員の質問の中にタコ公園のお話があったんですが、これはちょっと要望にもなりますけれども、今、工事が始まっているんですね。","respondent":"松代管理工事課長","answer":"それのお知らせについての周知ですけれども、まさにこれから移設する予定になっておりますので、そういったことを、ちょっと東京都第二建設事務所と調整しまして、少しでもそこを通る方、利用される方にわかりやすくお知らせをしたいと考えております。","voiceIndex":254,"id":"exchange-103"},{"speaker":"西本委員","kind":"質問","question":"ぜひ、看板等々でわかりやすくお知らせをしていただくように、よろしくお願いいたします。その件については、さまざま委員のほうからも質問がありましたけれども、都は財調の関係もありますので、予算当初は不明瞭なところもあったので、増えるという最低限のところで予算化をしたとおっしゃったと思うんですけれども、その予算の立て方、それから、補正の考え方、今後、どういうような形でつくっていくのか。","respondent":"日下部企画財政課長","answer":"ただ、今後とも、できる限り当初予算の編成段階で、１年間をしっかり見通す形で、歳入、歳出ともに計上できるような努力は、引き続きしてまいりたいと考えております。","voiceIndex":256,"id":"exchange-104"},{"speaker":"西本委員","kind":"質問・要望","question":"そのずれの考え方、それから、病院側、薬局との支払いはどうなっているのか。それから、保険の種類によって、その場での精算という形ではなくて、後で品川区のほうに申請を出して助成を受けるという形の方も何人かいらっしゃいますけれども、その方たちが、自分の意思なんでしょうけれども、どれだけきちんと助成されているか、そこら辺の状況把握はどのように考えられているでしょうか。","respondent":"諸岡児童課長","answer":"子どもすこやか医療費助成制度についてですけれども、この請求、支払い関係ですが、受診をされますと、医療機関のほうで、レセプトを国保連合会のほうに送られてまいりまして、国保連合会のほうが審査、支払い機関ということで、医療機関のほうに料金を払う。","voiceIndex":258,"id":"exchange-105"},{"speaker":"西本委員","kind":"確認","question":"その内容はよくわかっているんですが、病院側とか、薬局の回収はきちんとできているのか。品川区の助成が現場の病院とか、薬局のほうに行っているのかどうかの確認は、区としては把握をしているのか。それは、自己責任下においてやっていただくというような考え方なのかを、お聞きしたいと思います。","respondent":"諸岡児童課長","answer":"東京都外でかかられた場合は、患者が医療証をお持ちになっていらっしゃいますので、それにその場合の手続方法が書かれていますし、そのほかのさまざまな区のお知らせ等によって、そういった場合には、区の児童課の窓口のほうで現金を払い戻しといいますか。","voiceIndex":260,"id":"exchange-106"},{"speaker":"西本委員","kind":"質問・要望","question":"医療費のほう、私たち区民側としては非常にありがたい制度でありますけれども、それを負担というか、やり取りをしているところも、きちんと流れの中で入っているかどうかというのは、医師会等々を通して、現場サイドで確認をしていただけないかなと思います。それから、都外の保険の関係は後での精算の形なんですけれども、これは自己管理になりますので、大体周知徹底はしているはずなんですね。","respondent":"小林保育課長","answer":"新規に開設いたしますときに、その内装も含めた設備費、開設準備経費につきましても、都と区と２分の１ずつ、最高２,０００万円までの補助というふうになっています。","voiceIndex":262,"id":"exchange-107"},{"speaker":"西本委員","kind":"質問","question":"区のほうも２分の１、運営費として助成しているということですが、非常に入りにくい状況なんですね。認証保育所も定員がいっぱいになってしまう。区外の方も入って来られるというところでは、優先順位というのは、いいのかどうかというところがありますが、なるべく区内の希望されている親御さんの利用を促すような形ではできないのかなと思っているんですが、いかがでしょうか。","respondent":"小林保育課長","answer":"認証保育所は、都市型の保育需要に対応するということで、特に駅周辺に立地することが多うあります。","voiceIndex":264,"id":"exchange-108"},{"speaker":"西本委員","kind":"質問","question":"認証保育所は、これからもますます建設されるんじゃないかと思っています。なかなか認可保育園に入りにくいという方がいらっしゃいますので、有効的に、いい関係で利用できるようになればいいかなと思っています。今後、どういうふうになっていって、この減額というのは、今後どういう形になるのか。ますます減額という形になっていくのか、動向を、どういうふうに考えていらっしゃいますでしょうか。","respondent":"小林保育課長、諸岡児童課長","answer":"ただ、職員構成上は、基本的に、例えば平成１７年度と比べて、平成１８年度は人員が減って、それを非常勤に置きかえたとかといったことではなくて、給与財源の構成上の差が生じたものと考えております。児童センター運営費の更正減額ですが、これは平成１７年１０月１日の現員で、９７名という予算を計上しておりましたが、実質的に、その後、普通退職者、あるいは人事異動ですまいるスクールのほうへ異動したりという者が６名おりまして。","voiceIndex":266,"id":"exchange-109"},{"speaker":"西本委員","kind":"質問","question":"保育園のほうとしては、いろいろ制度上の関係だということで、今後、同様の考え方でやっていくということだったと思います。児童センターについてですが、今、民間のほう、委託という形で入っていられると思うんですが、これが今後やはり増えていくということになると、職員費ということについては下がっていくと考えてよろいしんでしょうか。","respondent":"諸岡児童課長","answer":"今後、児童センター、新たに再編をいたしまして、５地区、１３ブロック、地域にシフトした体制で、児童問題を中心に、子ども家庭あんしんネット協議会の事務局を担ったり、虐待防止機能も果たしていくということがありますので、今後につきましては、職員の配置等。","voiceIndex":269,"id":"exchange-110"},{"speaker":"西本委員","kind":"質問","question":"いろいろな人材を考えていくということですが、今日は質問いたしませんけれども、質の担保というところもありますので、これはまた款別のところで質問していきたいと思っています。次に、学級環境整備事業、この中の校舎等整備の中には、例えば体育館とか、校舎とかの設備も関係しているという形でよろしいですか。どういう内容のものが入っているんでしょうか。","respondent":"市川庶務課長","answer":"あるいは、プールの塗装、防火区画の整備、こういったものも含んでおります。それらも一連を含めて校舎等整備ということで対応しております。","voiceIndex":271,"id":"exchange-111"},{"speaker":"西本委員","kind":"質問","question":"これは、最近経験したことなんですが、体育館の設備がちょっと壊れている。それを改修してほしいので、１月ぐらいに聞きましたら、年度内では予算がもうないと。来年度に早急に直しますという返事をいただいたんです。しかも、やはり体育館等々について、校舎内もそうですが、安全性を考えると、すぐに改修するべきではないのかというふうに思うんですが、その考え方はいかがなものなんでしょうか。","respondent":"市川庶務課長","answer":"その一方、施設はやはり生き物ですから、随時対応しなくちゃいけないというケースもあるということは承知しております。こういった一連の工事ニーズに対しまして、１年間の予算額の中でどう対応していくか、これが一つあります。","voiceIndex":273,"id":"exchange-112"},{"speaker":"土井委員","kind":"質問・要望","question":"５７ページのりんかい線にかかわること、さらに５９ページの公共施設整備基金積立金追加分等に関すること、それから、６５ページの在宅介護支援センター運営費の予算財源構成に関すること、とりあえずこれを中心にお伺いして、さらに加えて、一定の補正とは何ぞやというところを、ちょっと聞かせていただきたいと思っています。そこら辺をどう考えたらいいのかということなんです。","respondent":"日下部企画財政課長、蓼沼高齢福祉課長","answer":"公共施設整備基金の積立でありますけれども、これの執行の時期は、これからいろいろな財源の問題が、最終補正でご議決をいただいた後、整理をしてまいりまして、５月末の出納整理期間中に、これを執行するというものです。ということで、当初予算を計上する時点では、この交付金の見込みがはっきりしなかったために補正で組んだものでございまして、これは、今回限りの措置です。","voiceIndex":276,"id":"exchange-113"},{"speaker":"土井委員","kind":"質問","question":"大変よくわかりました。そもそも論というのは、先ほどお話をしたんですけれども、きょう、伺っておりましても、補正予算はなるべくないほうがいいんだと、できればやらないほうがいいというお話ですよね。１１月の第３回定例会とか、第２回定例会ですと、そこから新しい事業が始まるかもしれないということなので、ちょっとその辺のそもそもの考え方と、そもそもについてお伺いをしたいと思います。","respondent":"日下部企画財政課長","answer":"最終補正でいろいろ組み立て直しをしたものが、翌年度の予算にも、明日以降は平成１９年度の新年度予算でご審議をいただきますけれども、そういう一つの年度間のつなぎの役割も担っていると考えておりますので、そういう意味では、できる限り最大限、歳入。","voiceIndex":279,"id":"exchange-114"},{"speaker":"土井委員","kind":"確認","question":"大変ありがとうあります。だから、その審議をこの場で、予算特別委員会でやれば、別に同じことじゃないかなという感じがするので、ちょっと聞いてみたんですけれども、もう一度、その意味では、先ほど言った国庫支出金だとか、都の支出金だとか、そういう歳入面は、少なくともここで確認しなきゃならないことなんですね。","respondent":"日下部企画財政課長","answer":"基本的には、歳出については、執行額の限度を決めるというものでありますけれども、いずれにしましても、それの一つの財源的な裏付けをはっきりしないことには、事業の性格自体もなかなかご理解いただけない面もあろうかと思いますし、そういうことも含めまして、それはそれで。","voiceIndex":281,"id":"exchange-115"},{"speaker":"土井委員","kind":"質問","question":"でも締めだけは、平成１８年度の３月１、２、３、４ぐらいまであるという形で締めていくわけですよね。まあ、いいです。というのは、真剣に、まさしく１円も間違いのないようにこういうものをつくらなきゃいけないわけですから、大変だなと思うので、できるだけ簡素にならないのかなと思って聞かせていただきました。すぐにどうなるというものでもなさそうなので、これをもって終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":283,"id":"exchange-116"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"これは大井ふ頭の青空野球場の交換をする分、６,０００m2と、新規購入１,５００m2だと思ったんですが、その分が、現区長が東京都と折衝の結果で、これが品川区が使えるようになったと思うんですが、この整備の中で、前にも出ていたと思うんですが、一応、確認として、どのぐらいのグラウンドができ上がってくるのか。その辺から、教えていただきたいと思います。","respondent":"松代管理工事課長","answer":"ここをご利用いただく際には、基本的に公共交通機関、一番近いところは天王洲アイル駅、歩いて五、六分ですけれども、そちらをご利用いただければと思うんですが、そうはいいましても、道具等をお運びになりますので、駐車場として、１９台から２０台、何とか設置できればなと。","voiceIndex":285,"id":"exchange-117"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"あそこは、現状、緑も多い公園になっていると思うんですね。駐車場、１９台、２０台という台数があれば、一番混んだときでも、あそこは１面でしょうから間に合うと思うんですが、やはりあの周りの道路に置かれてしまうと、あそこもかなり危ない。それとも、まだ全然検討してないのか。ですから、利用者の要望をまだ調べていないのか、それとも、現状どうなっているのか、先に。","respondent":"松代管理工事課長","answer":"それ以外は残念ながら伐採という形をとっております。八潮北野球場ですが、こちらは、現在、土系の野球場としてご利用いただいております。人工芝等の計画は、現在のところは考えてございません。","voiceIndex":287,"id":"exchange-118"},{"speaker":"鈴木（真）委員","kind":"確認","question":"私も、今言ったように、人工芝系にしてほしくないと思うんですけれども、これからの利用状況とか、グラウンドが、青空３面のところが１面になってしまうということを考えると、今後、検討の材料になってしまうのかなとも思いますが、その際は、よく現在の利用者の状況も確認していただいた上で、区のほうで考えていってもらいたいと思います。それから、キャンプ場もまだ使っていると思うんです。","respondent":"藤田道路公園課長","answer":"青空野球場ですが、２月１日から、入口が変更になってあります。現在、従来の入口がトレーラー等の入口がなっておりますので、その辺の安全性を高めるために、別な入口を設け、そこからご利用いただくという形になっております。","voiceIndex":289,"id":"exchange-119"},{"speaker":"鈴木（真）委員","kind":"意見","question":"それからもう１点のほうに移ります。防災対策費の中で、地域防災アドバイザー育成事業に対する都支出金交付に伴い、同額一般財源を更正減額ということで、これが、先ほど、都補助金の中で、民生費補助金の福祉施策包括補助金２４７万８,０００円、これでいいんですよね、財源が変わったということで。","respondent":"久保田防災課長","answer":"今回、地域防災アドバイザーの育成事業費に関する財源更正なんですけれども、東京都のほうの東京都福祉改革推進事業の中に、先駆的事業として、新たな課題に取り組む試行的事業ということで採択されまして、先ほど出ました４９ページにある２４７万８,０００円、全額なんですが。","voiceIndex":291,"id":"exchange-120"},{"speaker":"鈴木（真）委員","kind":"質問","question":"財源が都の補助金に移ったということで、それは新しい施策でいいなと思うんですが、何で福祉施策なのかなというのが、まず一つ引っかかったんです。その中で、高齢者の支援ということからこれに入っているのかなという思いもあったんです。この補助が、また来年以降も同じように続いてきて、新たにまたこれからもアドバイザーの育成を進めていくのかどうか、そこら辺の考え方を教えてください。","respondent":"久保田防災課長","answer":"防災アドバイザーなんですけれども、現在、災害事業援護者対策として、区内全域で、避難誘導のワークショップ等をやっておりますけれども、大きく言うと、やはり要援護者対策として取り上げているということについて。","voiceIndex":293,"id":"exchange-121"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"先駆的事業で、いい事業でしたら、補助金がなくても、区の一般財源でもやっていくべき話だと思いますので、ぜひ活用していっていただきたいと思います。最近、ちょっとお聞きしたんですが、ある警察署の中で、ビデオまでつくって、シミュレーションを実施したということを聞いたんです。それは、地域の町会長たちが警察に呼ばれて、見せてもらったという話を聞いています。","respondent":"久保田防災課長","answer":"そういう点でいけば、新しく変わったということについても、大きな混乱はないんじゃないかなと認識しております。","voiceIndex":295,"id":"exchange-122","title":"町会・自治会支援"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"最後に、警察のシミュレーションと区の指示が全然別になってしまうようなことがないように、一環した体制。だれかこれから防災のリーダーになっていくべき人が、違う形になってしまうと困るなと思いますので、その辺もよく検討していっていただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":297,"id":"exchange-123"},{"speaker":"堺委員","kind":"質問・要望","question":"今回、補正予算で９２億８,８０４万４,０００円計上されているわけですけれども、これの中身、内容というんでしょうか、これについて確認をしておきたいと思います。これが１点目です。この改良に当たっては、一度、地元でも説明会がされているわけですが、そのときにおそらく出た要望だろうと思うんですが、その辺の具体的な要望の内容について、確認の意味で教えていただけましょうか。","respondent":"日下部企画財政課長、浜脇街路事業担当課長、松代管理工事課長","answer":"ほぼこの半額は、これも先ほど来ご答弁申し上げておりますように、国文学研究資料館跡地の取得、来年予定しておりますので。補助１６３号線の補正の理由ですけれども、当初予算は１７億８,０００万円ということでしたが、これには。戸越公園避難通路整備に関する要望の内容というご質問です。昨年８月に説明会等をしまして、その際、また地域の町会等からの要望ということでございました。","voiceIndex":299,"id":"exchange-124"},{"speaker":"堺委員","kind":"質問・要望","question":"もう１点は、移転をするに当たっては、区は用地を取得するということも、当時から意思表示は明確にしておりましたから、場合によっては、取得する時期が来たら買えるようにという意味で、今回、補正予算で積み立てるのではなくて、例えば５年計画で積み立てていくとかという形もあったのではないかなと、こういう気がしましたけれども、この辺の考え方だけを、ちょっと確認しておきたいなと思いまして。","respondent":"堀越行財政改革担当課長、浜脇街路事業担当課長、松代管理工事課長","answer":"建物については、今後、どういった形で利用するのが一番有利な形になるのか等を含めまして、整備方針を定める中で検討をしていくという予定です。１６３号線の関係ですけれども、あと残り約２年ですので、その工期内に、事業期間内に終わるように、今後とも努力してまいります。内容の具体的なものですけれども、バリアフリーということで、車いすもゆっくりと入れる勾配５％以下ぐらいになるように、今回、整備を変更いたしました。","voiceIndex":303,"id":"exchange-125"},{"speaker":"菊地委員","kind":"質問","question":"７９ページの大井町周辺の地区再開発事業、それとあわせまして、７２ページの中小企業対策に関連して、お聞きをしてまいりたいと思います。更正減額されているところ、西地区かと思いますけれども、その内容について、ちょっとお聞かせを願いたいということ。それから、これからの展望なんかについても、ちょっとお聞かせ願いたいと思います。","respondent":"青木都市開発課長","answer":"７９ページ、ご質問の大井町駅周辺地区再開発事業の更正減額ですけれども、今現在、私どものほうで、平成１８年度歳出で予定しておりました大井町西地区というところで再開発準備組合が結成されておりまして、そこが本年度中に組合設立して、法的な団体になった後に。","voiceIndex":308,"id":"exchange-126"},{"speaker":"菊地委員","kind":"意見","question":"今、最後に言われたにぎわいというところで、実際に今のこういう商店街の状況なんかを見ないで形成をしていけるのか、そういう展望があるのかというところを、ちょっとお聞かせを願います。","respondent":"青木都市開発課長","answer":"ですので、今後進めていく開発の中では、地元の商店街のにぎわいを阻害しないような、むしろ共存できるような、お客様を呼べるような施設の導入というようなことを検討しながら、まちづくりを進めていきたいと、区としては考えております。","voiceIndex":310,"id":"exchange-127"},{"speaker":"菊地委員","kind":"意見","question":"ここに、２０年も前に区の区民部商工課というところが、当時の名前みたいですが、行った近隣の商店街の調査表があるんです。この項目の中で、「再開発や地区計画を進めて、核となる大型店を誘致して、そのよさと、近隣商店街のよさをあわせ持つまちなみが、来訪者に支持をされる。この辺では、いかがでしょうね。開発というよりも、商業という目線で見たときに、どうなのかを、ちょっとお知らせください。","respondent":"金子産業振興課長","answer":"特に、私どもも商店街連合会とも意見交換をしておりますが、大型店との対決等々というようなことについては考えていなくて、大型店とどう連携していくかということが、今後の商店街の一つのあり方だろうということで、私どもも、今年度、あるいは来年度においても。","voiceIndex":312,"id":"exchange-128"},{"speaker":"菊地委員","kind":"質問","question":"大きく発展と言いますけれども、それは非常に異論のあるところですよね。要は、開発を進めて、大型店を誘致をしてくる、そういう形式そのものが、こういう都心部でも崩れつつあるんだということなんじゃないですか。地区計画、開発を進めるということでまちづくりが進む、こういう考え方が、そもそも崩れてきているんだということが言えるんじゃないでしょうか。その辺をお願いします。","respondent":"岩田まちづくり事業部次長","answer":"駅前整備については、ある一定程度成果が出ております。ただ、大井町全体におきましては、Ｅ地区、Ｂ地区、それから問題のＣ地区といったところがまだ手つかずの状態で残っておりますので、いわゆるまだ発展途上の地域であるというに認識です。","voiceIndex":314,"id":"exchange-129"},{"speaker":"菊地委員","kind":"質問・要望","question":"そこをもう少し明確にしてほしいんですよ。さっき言った、どこの商店街を見たって、やっぱり厳しい状況にあって、後継者をつくっても、それでは後継者にきちんとした営業をさせられないということで、皆さん廃業されるという実態があるわけですから、ここをもう少しきっちりと見たご答弁をいただきたいんです。","respondent":"金子産業振興課長","answer":"であるからして、平成元年のころのそういう判断、ないし出店というものが間違いだったかどうかというのは、私は、それについて評価できる立場にはないので、私どもとしましては、丸井が営業を終了するという話をお聞きしていますので、なおかつ、その後。","voiceIndex":316,"id":"exchange-130"},{"speaker":"菊地委員","kind":"意見","question":"今の話というのは、丸井の撤退は自分たちの責任ではないと、全く関係ないんだと、それは好き勝手という形ですよね。再開発ビルの中で営業をしてきた、いわゆる核店舗なわけでしょ。そこに対する責任というのを、もっと明確にしてくださいよ。最後。","respondent":"山田区民生活事業部長","answer":"これは全国展開の中で、ご自分の経営的な判断ということで、私どもは認識をしております。その後も責任を持って、今の条件のまま新たな企業と話し合いをしているです。","voiceIndex":318,"id":"exchange-131","title":"町会・自治会支援"},{"speaker":"石田委員","kind":"確認","question":"品川区というか、特別区側は、東京都がそういうふうに思っていると思っているのか、どうか、それを確認したいと思います。そうなってくると、今度、都との協議の中で、必ず特別区が水平調整を行うので、特別区の決定に文句を言うなと、その協議の中で、都はそれをすべて黙って承認しろということの話し合いというのはできるのか、できないのか、そこら辺の確認をお願いします。","respondent":"日下部企画財政課長","answer":"もともとこれは８月の当初算定の時点と、ここへきての最終実績との見込みの違いではありますけれども、いずれにしろ、この間、２３区が以前からずっと東京都に対して、これはもともと区にとって非常に貴重な財源でもありますので。","voiceIndex":321,"id":"exchange-132"},{"speaker":"石田委員","kind":"質問","question":"そういうふうにおっしゃるだろうなと思ったんですけれども、質問になかなかお答えしてくれてないと思うんですけれども、でも、企画財政課長の答弁では、それ以上言えないんだろうなと思うんですけれども、先ほど、今話があって、区長からも、本会議で強くお話があったと思いますが、改めて伺います。じゃあ、地方分権を進める意味からも、基礎的自治体として、今後、都区の財政調整の問題も残っている。","respondent":"濱野区長","answer":"どれだけ特別区が自主的な水平調整をできるかというのは、正直申し上げて、かなり難しい問題だろうと考えています。ただ、難しいだろうから、水平調整の試みもしないでそのままにしておくというわけにはいかないと思っています。","voiceIndex":323,"id":"exchange-133"},{"speaker":"石田委員","kind":"提案","question":"それで、がんがん品川区から提案をしてやっていく。この問題は、区長と行政側と議会も一体となって取り組まなくちゃならないと思うから、それをもし品川区から提案してやっていったとしたら、区長としては、これはちょっと目立ちすぎて、区長会でも立場がなくなるからありがた迷惑と思うのか、ぜひ提案をしてがんがんやってほしいと思うのか、これもあわせて教えてください。","respondent":"濱野区長","answer":"そしてまた、議会についても、２３の議会がこぞって動き出すことが一番望ましいわけで、品川区だけが動いていると、ちょっと逆に何かやりづらいこともあろうかと思います。といいますのは、５２％から５５％にすることについては、２３区だれも異論はありません。","voiceIndex":325,"id":"exchange-134"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=874#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":122160,"voices":329}},{"id":"h19-20070306-3","meetingId":"h19-c-budget","date":"2007年3月6日","dateIso":"2007-03-06","committee":"予算特別委員会","time":"午前１０時０３分～午後５時４９分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を173件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"○午前１０時０３分開会 ただいまより予算特別委員会を開会いたします。 それでは、第５号議案、平成１９年度品川区一般会計予算","agenda":"○午前１０時０３分開会 ただいまより予算特別委員会を開会いたします。 それでは、第５号議案、平成１９年度品川区一般会計予算","exchanges":[{"speaker":"大沢委員","kind":"質問","question":"１１６ページ、介護福祉専門学校修学資金貸付金元利収入のことで伺います。本年度７２０万円、前年度が７９２万円ということで、本年度は７２万円ばかり少なくなった予算立てはなぜか。利用者減によるものか、それとも償還を免除された方が多くなって、裏返せば３年以上、本区の介護施設の中に定着する介護士たちが多くなったのか、理由を伺いたいと思いますので、お答えください。","respondent":"蓼沼高齢福祉課長","answer":"修学資金貸付金の減ですけれども、手元に詳細な資料がございませんけれども、回収についての返還の状況が、一定程度働きかけ等もあって、スムーズにきているということで、平成１８年度の実績の見込みから今年度、こういうような予算立てをしたものです。","voiceIndex":4,"id":"exchange-001"},{"speaker":"大沢委員","kind":"質問","question":"これは回収不能というので、私は今、受け取ったんですけれども、このような受け止め方でいいんでしょうか。","respondent":"蓼沼高齢福祉課長","answer":"例えば貸付の新規貸付の件数が平成１８年度は従前と比べて減ってきております。それから、あとは区内の福祉施設に就労して、償還の免除になった方等が増えてきているということの入り繰りの関係で、今年度はその実績を踏まえて予算を計上したものです。","voiceIndex":6,"id":"exchange-002"},{"speaker":"大沢委員","kind":"確認","question":"私、最初にそれを伺ったんです。定着率が上がったのかということと、何らかの形で減少されたのかということで、そこが先ほどのご答弁であった回収不能ということでおっしゃっていたので、そうではないですかということで、もう１回確認させてください。","respondent":"蓼沼高齢福祉課長","answer":"回収不能ということではございません。","voiceIndex":8,"id":"exchange-003"},{"speaker":"大沢委員","kind":"意見","question":"回収不能ではないということで、非常にうまくといいますか、学校自体、この介護福祉専門学校、学費が安い。しかしながら、この介護福祉の専門学校、近年、生徒数、定員は４０人ですけれども、卒業生が減少しております。平成１２年と平成１５年がピークで４３人と４１人ということで、あと３０人の半ばということですけれども、それについての減少をどのようにとられていらっしゃいますか。","respondent":"蓼沼高齢福祉課長","answer":"それからもう１つは景気の動向等も影響して、こういった介護職を目指す方が、これは品川区のこの学校だけではなくて、他の学校もそういうような傾向にあると聞いてあります。","voiceIndex":10,"id":"exchange-004"},{"speaker":"大沢委員","kind":"意見","question":"他の学校もそうであるということなんですが、今、日本の介護福祉専門学校は７割が定員割れということです。そのうちの８割が半分以下の生徒数ということなんですが、本区だけ社会福祉法人が主体になって、区が４７％強の補助金を投入して事業を行っているわけですけれども、本区においては、そのような事態があってはいけないことだと思います。","respondent":"蓼沼高齢福祉課長","answer":"そういう状況ですけれども、平成１９年度に向けましても、品川区のこの介護福祉専門学校の持っています特徴といいますか、そういったものを十分にＰＲしながら、今も引き続き入学者の確保に努めているところですけれども、しばらく。","voiceIndex":12,"id":"exchange-005"},{"speaker":"大沢委員","kind":"質問・要望","question":"これは区としては非常に損害が大きいことだと思うんですが、そこのところの区外転出者の介護士の卵をどのようにつなぎとめて、そこには職業選択の自由がありますけれども、そのような何か工夫はされているところはあるんでしょうか。","respondent":"蓼沼高齢福祉課長","answer":"今年度卒業される方については、３６人中３３人の方が就職を予定されていまして、区内の法人立に就職される方の割合というのは約８５％という状況でございまして、まずまず区内の施設のほうに就職されている傾向が強くなっていると考えております。","voiceIndex":14,"id":"exchange-006"},{"speaker":"大沢委員","kind":"質問・要望","question":"今、区でも団塊の世代ということで、１０年先、１５年先、非常に大変な状況になりますので、先を見据えて政策を打っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":16,"id":"exchange-007"},{"speaker":"菊地委員","kind":"質問・要望","question":"先ほどの説明の中で、手数料については建築基準法の改正で増になっているというお話がありましたけれども、この間の民間への建築確認ができるようになって以来、姉歯事件なんかも経て、建築課のほうでは大変苦労されてきた部分であろうと思うんですけれども、平成１７年末の予算で、４００件余りが出されていまして、平成１８年、今年度が２５０件、平成１９年が３４５件となっていますけれども、この間。","respondent":"片田建築課長","answer":"それと２点目の改正についての考えですけれども、建設委員会でもご説明しましたように、新たに構造計算の適合性判定機関という立ち上げの中で、今回の予算書のほうにも前年度比で件数を３４５件と。","voiceIndex":18,"id":"exchange-008"},{"speaker":"菊地委員","kind":"確認","question":"適正に進むんじゃないかと話でしたけれども、この品川区が受けた申請をまた新しいチェック機関に依頼して、新しいコストというんでしょうか、建築主に課すという考え方になっちゃうんだと思うんですけれども、これはもとになったのが、９８年の建築基準法の改正で、民間でも建築確認ができるようになったというのがもとだと思うんですけれども、申請者に新しい負担を負わせるという。","respondent":"片田建築課長","answer":"ただ現実問題、専門的な構造計算の仕様なり計算の手法がかなり詳細化されてきました中で、やはり生命・財産に大きな影響を及ぼす構造問題については、複数の目で見て、あるいはプログラムを適用したものについては再計算を行うといったような検証の中で、適正に。","voiceIndex":20,"id":"exchange-009"},{"speaker":"菊地委員","kind":"確認","question":"区でやる場合には、これまで民間機関の２分の１ぐらいの料金だったというお話でしたね。民間の検査機関がかなり台頭してきたときに、区としても１日も早く受けた申請を、確認を出そうという流れがあったと私は思っているんですけれども、この辺の体制というのは今、変わってきているのかどうか、その辺をちょっとお知らせ願いたいと思います。","respondent":"片田建築課長","answer":"区のほうとしても、たしか平成１６年の１月ぐらいだと思いますけれども、できるだけ早く建築確認を民間と競うわけではございませんけれども、処理していきたいという考え方の中で、法に定められた申請期間が２１日間といった中で、サービスアップの観点から。","voiceIndex":22,"id":"exchange-010"},{"speaker":"菊地委員","kind":"質問・要望","question":"建築行政が安全より効率優先というふうに、結局はなってしまったわけですから、民間の検査機関を非営利の法人にして、検査は自治体の委託で行っていくというような形というのが、どうしても求められるのではないかと思うんですね。","respondent":"片田建築課長","answer":"それと現在の体制については、やはり技術の継承が大事だと思っていますので、その辺を十分対応していきたいと思っています。","voiceIndex":24,"id":"exchange-011"},{"speaker":"武内委員","kind":"質問・要望","question":"初めに５ページのほうですけれども、すごく勉強不足なので単純な質問なんですが、今回の予算の総額が約１,３４５億円になっておりまして、昨年の当初予算より０.３％増ということでお聞きしたんですけれども、昨日補正予算をやりまして、最終的には昨年度は１,４００億円ということになったかと思うんですが、この１,４００億円に対して、この１,３４５億円と見ていくのか。","respondent":"日下部企画財政課長","answer":"ただ、最終段階でいろいろな事情の変更等もありますので、これはこれで最終の決算の比較ということで、年度の比較をまたしていただくということで考えてあります。","voiceIndex":27,"id":"exchange-012"},{"speaker":"武内委員","kind":"質問","question":"そうすると、いろいろな考え方があると思うんですけれども、平成１８年度は１,４００億円実際には予算がかかったという中で、ことしは少しそこから比較すると当初予算の組み方は減ってしまったというふうに考えると、変な考え方になるんでしょうか。","respondent":"日下部企画財政課長","answer":"そういう、いろいろ１年間を通して、状況の変化というのは当然のことながら出てきますので、それはまた例えば今回平成１９年度の当初予算についてお諮りをするわけですが、恐らくこれがまた１年経過すれば、さまざまな状況の変化も出てくるわけでありまして。","voiceIndex":29,"id":"exchange-013"},{"speaker":"武内委員","kind":"質問・要望","question":"続きまして、６０ページの区民保養所使用料というところで、先般、品川荘についてお願いしまして、非常に早い対応でやっていただいた件がありますが、障害者の方で左半身が不随で、家族風呂、障害者用のお風呂に右側しか手すりがついていなくて、入るときはいいんですけれども、出るときに出られないというお声で、もう一つ反対側のほうにも手すりをつけてくださいというお声をいただいて、すぐお願いしたら。","respondent":"鷹倉区民課長","answer":"現在、品川荘、そして箱根荘という形です。区民の声をできるだけ反映するような形で委託業者が仕事をしていく。あるいは区が仕事をしていくという形で、そのような体制をとらせていただいているところです。","voiceIndex":31,"id":"exchange-014"},{"speaker":"武内委員","kind":"質問","question":"そうすると、アンケートが置いてあるということで理解いたしますけど、なかなかそういった中で、そのアンケートでどこまでそれを当事者の受託されている方がチェックをされているのか、また区のほうまで場合によっては、こういったお声があるよとか、そういった体制というか、連携というのはどのようにとらえているんでしょうか。","respondent":"鷹倉区民課長","answer":"そういうものを踏まえながら、できるだけ利用率を伸ばしていきたいという私どもの気持ちですので、予算の範囲内でこたえられるものについては即対応していきたいと考えているところです。","voiceIndex":33,"id":"exchange-015"},{"speaker":"武内委員","kind":"質問・要望","question":"そうした面で言えば、例えば今回、今までうちのほうでも、幹事長が、いろいろごみの問題なんかもシルバーセンター、確かにごみは有料になってきますので、難しい部分もあると思うんですけど、例えばちょっとしたごみを、そこでごみ箱がなくても、ちょっと帰るときに見ていただいて、そういうのを捨ててあげるとか、いろいろな意味で心遣いというか、そういった面をぜひ。","respondent":"蓼沼高齢福祉課長","answer":"それから今のごみの部分も、原則はお持ち帰りをいただいておりますけれども、と申してもいろいろな状況があって、どうしても持っていけないような状況がある場合には柔軟に対応するようにということで指示をしていますので、今後ともご利用等につきましては。","voiceIndex":35,"id":"exchange-016"},{"speaker":"武内委員","kind":"質問・要望","question":"それから続きまして、健康センター使用料のところですけれども、先ほど使用料が増加しているということなんですけど、この辺の細かい利用状況じゃなくて、区民の方々の健康を維持するために、高齢の方はさまざまな場があるんですけれども、比較的若い方の健康に対する意欲というか、運動意欲といったものについて、区のほうはどのように考えていらっしゃいますでしょうか。","respondent":"谷田部健康課長","answer":"そういうことが健康センターの利用のほうにも結びついていると考えているところです。","voiceIndex":37,"id":"exchange-017"},{"speaker":"武内委員","kind":"質問・要望","question":"品川健康センターとか荏原だと、大井のあたりから行くにはちょっと時間がかかってしまうということで、できれば中間の大井の近辺にもそういったような施設が欲しいというお声もあるんですけれども、今後の区の計画で、そういった計画というか、方向というか、そういうのもお考えなのかどうか、教えていただきたいと思います。","respondent":"谷田部健康課長","answer":"私ども健康センターを２カ所設けてあります。それと、健康づくりではさまざまなところで、いわゆる民間が先行して行ってあります。","voiceIndex":39,"id":"exchange-018"},{"speaker":"武内委員","kind":"質問・要望","question":"最後に６８ページの自転車駐車場使用料ということで、これでバイクのところ、バイクの定期利用が今回、６,０００台、それから一時利用３万９,２００台見込んでいるわけですけれども、昨年の予算書と比較しますと、昨年は定期利用が５,４００台、それから一時利用が２万２,０００台ということでなっていたので、単純にこの１年間で定期利用が６００台。","respondent":"松嶋交通安全担当課長","answer":"それとあわせまして、バイクを増やしたというのは、やはり現在、バイクの駐車場が極めて少ない状況にあるといった中で、現在の区営の駐輪場を自転車の部分をバイクに変更するとか、そういったものも考えておりまして、そういったものの数です。","voiceIndex":41,"id":"exchange-019"},{"speaker":"武内委員","kind":"質問・要望","question":"そうすると、この１年間のこれから増設も含めて、新設も含めて、一時利用で言えば１万７,０００台、倍ぐらいにしていくということですね。そうすると大井町駅のほうは、新設で何台ぐらいバイクの駐車場ができるのか。ほかの場所についてもある程度具体的なものがわかれば教えていただきたいと思います。","respondent":"松嶋交通安全担当課長","answer":"大井町駅西口につきましては、現在のところ今、交通管理者と協議をやっているところでございまして、バイク置き場となりますと、路上の駐車場ですから、いろいろな制約があります。そういった中で、現在は年間９,０００台を西口だけでも予定をしています。","voiceIndex":43,"id":"exchange-020"},{"speaker":"大西委員","kind":"質問・要望","question":"１日の分です。それともう１点、お年寄りの方が心配されていたのが、循環型できれいな形であれが使われていないんじゃないのというふうに、よく温泉なんかに行くと、かけ流しだ、循環型だといろいろな形がありますけれども、ひょっとしてたまりっぱなしの状況じゃないかなということを言っている方がいたので、その部分、確認をさせていただきたいということと、事故があったやにも少し聞く部分があります。","respondent":"松嶋交通安全担当課長、冨岡高齢事業課長、金子産業振興課長、田村地域活動課長、藤田道路公園課長","answer":"それと、そこはバイクの駐車スペースを現在のところは３０台ということで考えておりますけれども、これはまた今後、需要が多いですから。私からシルバーセンターの浴室についてご説明申し上げます。今後の商店街の支援の方向性というお尋ねかと思いますが、ご案内のとおり昨年度から今までの商店街全体への支援というところから。地域食事サービスの実績ですが、平成１７年度受給者で申し上げますと２３２人、平成１８年度、まだ途中ですが。","voiceIndex":46,"id":"exchange-021"},{"speaker":"大西委員","kind":"質問","question":"それで先ほどのバイクの駐輪場の問題で、私はおよそ大井町駅西口のねこ公園のほうで何らかの解消ができると思うんですが、私が１つ気になるのが、きゅりあんのところにバイクを置くところが２台しかないという状況で、私は昨年、区民課長が変わられて、５月ぐらいでしたか、要請をしてやって、課長も一生懸命やられたと思うんですが、あそこは品川文化振興事業団で、区の職員が派遣されているようで。","respondent":"鷹倉区民課長","answer":"実はいろいろ課題があります。ここで細かなことは言いませんが、課題があります。しかし、その課題を何とかクリアできないかということで、検討しています。もう少し時間の猶予をいただきたいと考えています。","voiceIndex":52,"id":"exchange-022"},{"speaker":"大西委員","kind":"提案","question":"そこに行ったときにパンフレットか何かを差し上げて、こういう記念植樹はいかがですかという、区からの企画というんですか、提案をされるのではどうかなと。そういう形で区民の方々に呼びかけていけば、これはその親御さんの気持ちによっては、資金的なゆとりによっては、そういうこともできていくんじゃないかなと思うんですが、そういう形での考え方というのはいかがでしょうか。","respondent":"藤田道路公園課長","answer":"委員ご指摘のご趣旨も十分に踏まえながら、今後の検討課題にさせていただきたいと考えています。","voiceIndex":54,"id":"exchange-023"},{"speaker":"藤原委員","kind":"質問","question":"１２４ページの特別区職員互助組合保有財産返還金と、３７８ページの特別区債の平成１７年度末における現在高ならびに平成１８年度末および平成１９年度末における現在高の見込みに関する調書についてお伺いしますが、まず初めに１２４ページのほうからお伺いしますが、企画財政課長の朝の説明で、この事業の内容が変わったのでというお話だったんですけれども、まずこの内容と。","respondent":"榎本人事課長","answer":"特別区互助組合の保有財産の返還についてですけれども、もともと職員の福利厚生をどういう役割分担で特別区の互助組合と各区互助会がやるかというところがありまして、たしか平成１７年だと思いますけれども、大阪市の福利厚生の問題が出たときに。","voiceIndex":57,"id":"exchange-024"},{"speaker":"藤原委員","kind":"質問","question":"１億９,６００万円という高額なお金が戻ってきたんですけれども、具体的にこのお金はどのような形で処理されていくんでしょうか。","respondent":"榎本人事課長","answer":"これにつきましては、区の職員の福利厚生に当てるかどうかについては、各区で判断していいということなので、品川区の場合については、ちょっと明後日の歳出になってしまいますけれども、職員待機寮の建て替えの経費の一部に当てたいということで考えております。","voiceIndex":59,"id":"exchange-025"},{"speaker":"藤原委員","kind":"質問","question":"１億９,６００万円と、金額ばっかり何回も繰り返してしまいますが、やはり区民の皆さんにとっては、これは本当に高額だと思いますし、やっぱり互助会制度ということを考えますと、職員の方たちの積み立て部分というのもあると思うんですが、それでも、いろいろな助成というか補助がありますので、やっぱり区民の皆さんに理解をされるような使い方をしていかないといけないと思うんですけれども。","respondent":"榎本人事課長","answer":"それについては品川区のほうに戻ってきた分については、今まで品川区のほうで福利厚生のためにずっと出してきたものですので、職員の福利厚生のほうに戻していこうという考えです。","voiceIndex":61,"id":"exchange-026"},{"speaker":"藤原委員","kind":"質問","question":"次に３７８ページの公債費についてお伺いしますが、よく区長、企画財政課長がいわゆる品川区は４００億円、５００億円の基金がありますという形でお話をなされるんですけれども、見ていましても、この３７８ページで、１８年度末の公債が４１０億円あるということは、言葉が合っていないかもしれませんけれども、これでツーペイになるんじゃないかと、私は思うんですけれども。","respondent":"日下部企画財政課長","answer":"ただ一方で、この起債の４１０億円にしましても、品川区におきましては借金をするにしても、しっかりとそれなりの返済の財源の裏打ちをしつつ、これまで必要な借入等を行ってきたという経過もありますので、そういった意味で考えますと、差し引きの問題もありますけれども。","voiceIndex":63,"id":"exchange-027"},{"speaker":"藤原委員","kind":"質問","question":"私も公債、区債発行を決してしないほうがいいという考えもないんですけれども、その中で今回、区債ゼロという形で、２３区でもまさに抜本的なといいますか、決断をなさったと思うんですけれども、その辺のバランスというのは、どのように考えているんでしょうか。","respondent":"日下部企画財政課長","answer":"ただ、１つ例えば国文学研究資料館の取得とか、そういう実際の適債事業といいますか、これがないわけではないんですが、ただ今後の、将来の例えば利払いの負担とか、いろいろ考えますと、これは借金をしないで対応できたほうが、それにこしたことはないわけです。","voiceIndex":65,"id":"exchange-028"},{"speaker":"藤原委員","kind":"質問","question":"最後になりますが、ここの合計額の４１０億円が、品川区としてする仕事はちゃんとして、そしてこの額が減ってくるということが、やはり区長の手腕だと思うんですけれども、その辺についてはいかがでしょうか。","respondent":"日下部企画財政課長","answer":"そういう考え方も含めて、起債そのものは非常に重要な役割を担っているわけではありますが、先ほど申し上げましたように、一方でやるべきことはしっかりやりつつ、借金についてはできるだけ少ないほうが将来の財政の安定性等を考えたときに。","voiceIndex":67,"id":"exchange-029"},{"speaker":"三村委員","kind":"質問・要望","question":"こちらの６５ページの内容のほうを見しますと、トリムスクールでありますとか、プレイコート、ホール、会議室、あと区民体力測定など、区民の健康の維持・増進に対して十分活用されているということが伺えるんですけれども、ただ１点、気になる点がございまして、厚生委員会で以前、北品川にあります健康センターのほうに見学に行かせていただいたことがありますけれども、その際。","respondent":"谷田部健康課長、高橋品川区保健センター衛生課長","answer":"保健センターの中にあります調理室は保健センターの事業で使う調理室ですから、健康センターの施設ではないです。この調理室につきましては、栄養の具体的な事業を進めさせていただいている部分でございまして、例えば乳幼児の離乳食の調理の問題とか、あと糖尿病の教室の調理の問題ということで使わせていただいておるところです。","voiceIndex":70,"id":"exchange-030"},{"speaker":"三村委員","kind":"質問・要望","question":"平成１９年度予算を見ますと、家族いっしょに朝ごはん運動など、子育て家庭の食生活ということについて、力を入れていこうということが伺えるんですけれども、健康センターの施設ではないということだったんですけれども、ここの健康センターの中にあるということで、小さなお子さん連れの方にとっては、健診や予防接種なんかのたびに、大変利用する場所でもありますので。","respondent":"富田生涯学習課長、川口品川区保健センター保健サービス課長、谷田部健康課長","answer":"ただいまこうした調理室がどこにあるのかというお尋ねにつきましては、文化センターは荏原文化センターと五反田文化センター。先ほども健康課長がお答えしていますけれども、保健センターの調理室は保健センターの各種事業ということで利用しています。今、保健センターの調理室の利用状況というお話がありますけれども、いろいろ事業がございまして、パパママクッキング。","voiceIndex":73,"id":"exchange-031"},{"speaker":"三村委員","kind":"質問・要望","question":"ここ数日首長の交際費についての記事がいろいろ新聞などに掲載されておりますけれども、品川区は他の自治体に比べて、公開度が低いというような内容なども掲載されておりましたけれども、実際には区長交際費に比べると、議長交際費のほうがさらに公開度が低いというふうに認識しておりますけれども、区長交際費、また議長交際費は区民へどのように情報提供されているのか。","respondent":"市岡区議会事務局長","answer":"全般に区長交際費に比べると、ほかの自治体も含めて、議長交際費の公開度が低いという記事かなと考えています。それから議長交際費については、当然これは情報公開によって公開しておりますが、いわゆる公表という形では今現在行ってございません。","voiceIndex":77,"id":"exchange-032"},{"speaker":"三村委員","kind":"提案","question":"先日各会派に対して、政務調査費の見直しの依頼がありましたときに、私ども生活者ネットワークとしては、この議長交際費に対してもホームページなどで公開をしていってはどうかということで提案をさせていただいたんですけれども、その後議長のほうで、その投げかけに対して、どういった検討が行われたのか、もし把握をされていればお伺いしたいと思います。","respondent":"市岡区議会事務局長","answer":"それから議長へのご意見がどうなったかですが、これは私がお答えすべき内容ではございませんので、しかるべき場所でご協議が行われた内容ですので、当然、会派にはその結果というのはご存じだろうと考えています。","voiceIndex":79,"id":"exchange-033"},{"speaker":"三村委員","kind":"提案","question":"投げかけはさせていただいたんですけれども、この議論の内容については、私たちの提案についての議論はされていなかったというふうに私のほうは認識をしているんですけれども。こちらの１２９ページの議会費のところには、そういった記載がないんですけれども、そこの記載されていないということは、どうしてなのか、その点についてお伺いしたいと思います。","respondent":"市岡区議会事務局長","answer":"議員のお尋ねは大体そのとおりなんですが、少し基本的なところが違いまして、これは議長の完全な専用車ということではなくて、庁有車全体を一体的に管理しているという関係で、２番目のご質問にも関連するんですが、これは議会費ではなくて、総務費の自動車運行管理費。","voiceIndex":81,"id":"exchange-034"},{"speaker":"三村委員","kind":"質問","question":"共有ということで、実際の運用のところでは、特に議長ですとか、区長の場合、多忙ということで、ほぼ１台丸々占有されているような状況にあるというふうに認識しているんですけれども、もちろん公用車ということでのくくりで管理をされているということはわかるんですけれども、緊急の場合への対応も備えて、それぞれ車１台と人１人が専用で張りついていると聞いているんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":83,"id":"exchange-035"},{"speaker":"三村委員","kind":"質問・要望","question":"もしお答えがいただけるようだったら、どのぐらいの経費がかかっているのか、お答えをいただきたいと思います。交通費としての意味合いもある、この費用弁償をそういう公用車を利用している議長が受け取ることというのは、交通費の二重支給に当たるんじゃないかと考えるんですけれども、その点についてはいかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":86,"id":"exchange-036"},{"speaker":"三村委員","kind":"質問","question":"費用弁償については、いろいろご意見があるということで、さまざまな費用というふうにおっしゃっていらっしゃったんですけれども、このさまざまな費用を具体的にいろいろな項目があると思うんですけれども、どういった項目になってくるのか、ちょっとその点について詳しくお伺いしたいと思います。","respondent":"市岡区議会事務局長","answer":"今申し上げたとおり、いわゆる出会手当の費用弁償は積み上げ方式ではありませんので、１件幾らという額で規定をされているです。","voiceIndex":89,"id":"exchange-037"},{"speaker":"三村委員","kind":"質問","question":"質問の仕方が悪かったです。この中に交通費としての費用というのも含まれているというところでは、交通費分も含んでいるということで、さまざまな費用ということで、認識をさせていただいているんですけれども、その点についてはいかがでしょうか。","respondent":"市岡区議会事務局長","answer":"私の説明が悪いのかもしれませんが、そういうご意見もあると、そういう見解もありますが、いろいろな見解がある中で、現在は１件定額で支給されているです。","voiceIndex":91,"id":"exchange-038"},{"speaker":"三村委員","kind":"質問","question":"永年在職議員表彰についてお伺いをしたいんですけれども、これは２５年在職で１０万円、３０年在職で２０万円、４０年在職で３０万円の記念品を支給するという規定に平成１４年の１１月８日の議会運営委員会で決まったというふうに認識をしているんですけれども、この中でどういう議論によって決定がされているのか。条例ではどういうような規定になっているのか、お伺いをしたいと思います。","respondent":"市岡区議会事務局長","answer":"議会運営委員会でどういう議論があったかは、委員も十二分にご案内のとおり、非公開ですので、私がお答えすべきことではございません。","voiceIndex":93,"id":"exchange-039"},{"speaker":"三村委員","kind":"質問","question":"金額についてもその議会運営委員会の中の内規でしか表示をされていないということになりますと、区民の方からはどういったお金がどういうふうに使われていて、どういった金額が支払われているのかということが全く見えないということになると思うんですけれども、こういった条例にも記載されていないということになりますと、区民の方から、この永年在職議員表彰について。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":95,"id":"exchange-040"},{"speaker":"三村委員","kind":"質問","question":"議会だよりの中でということで、その中でもあるということだったんですけれども、そういうつくられていく議論の過程は見えないというふうな認識でよろしいのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":98,"id":"exchange-041"},{"speaker":"三村委員","kind":"質問","question":"こうせい、ああせいではなくて、どういうふうに区民の方から見えるのか、議論の内容についてどういうふうに外から見たときに、見られる手段があるのかについてお伺いをしたいんですけれども、その点についてはいかがでしょうか。","respondent":"市岡区議会事務局長","answer":"お答えになるかどうかわかりませんが、区議会全体の予算としてどういう要望をするかということについて、各会派のご意見を議長が集約をされました。","voiceIndex":100,"id":"exchange-042"},{"speaker":"三村委員","kind":"質問","question":"公表がどうなっているのかについて伺ったんですけれども、こういった議論の内容についても外に向けてもきちんと公表していくべきではないかと考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":102,"id":"exchange-043"},{"speaker":"鈴木（真）委員","kind":"確認","question":"特別区債の皆減の件が１点。それから歳出の中で、都支出金の財政調整拠出金、それから３２６ページ、８款公債費、大体関連するんですが、もう１点、先ほどの質問にもあった中で、１２４ページの１９款雑収入、特別区職員互助組合保有財産返還金ということの中で、先にこれをちょっと確認したい。そこに分配して、まだお金が残っているということになるのかどうか、そこの確認をしたいと思います。","respondent":"榎本人事課長、日下部企画財政課長","answer":"１７年度末で１０９億円、特別区互助組合が持っているということで、２３区のほうに配分されるのが７４億円、特別区互助組合が今後の互助組合事業として使う原資として、３５億円を残すという形です。２点のご質問です。１点目のどの程度が１つの目安として考えられるのかということでありますけれども、私どもはこの起債の関係でいきますと、金額がトータルで幾らというよりも、１つの判断の目安は要するに借入をする。","voiceIndex":104,"id":"exchange-044"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"特別区互助組合の件に関してはわかりましたので、起債のほうで逆にそれと同時に今度、財政調整積立金ということで、今期平成１９年、２０億円の積み立てをしていく。それと同時に財政調整積立基金のほうは６億１,０００万円、逆に基金の残高を見ていくと、こっちもどの辺まで積んでいくのかなというが、基準的なものはあるのか。どういう判断をしていくのかというのもちょっと教えていただきたい。","respondent":"日下部企画財政課長","answer":"品川区の場合は、今まで非常にそういう意味ではちゃんと返済の裏づけをとりながら借り入れをしてまいりましたけれども、それでもなおかつ、若干足りない部分がありますので、その辺を今回、平成１９年度で少し大目に積み増しをするという考え方です。","voiceIndex":107,"id":"exchange-045"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"今後の財政ということを考えると、その積み増しということもよく検討しておいていただきたいと思いますし、それから変動という点では、三位一体改革の中で３年間、これから本格的にスタートしていく中、３年分、今年の予算で言えば所得譲与税が皆減している。昨日、区長からもその辺の話があったと思いますが、総括して、どういうふうに考えるかを教えてください。","respondent":"日下部企画財政課長","answer":"一言で申し上げれば、今回、三位一体改革、地方への権限、それから財源の移譲ということが前提でなされたはずでありますけれども、２３区、品川区だけではありませんが、半数ぐらいの区がそれにかかりましたけれども、結果からすれば、品川区の場合はトータルで約２０億円。","voiceIndex":109,"id":"exchange-046"},{"speaker":"鈴木（真）委員","kind":"質問","question":"２０億円という大変大きな金額が税源移譲、これは区としては基準財政の枠の中で、財調で最終的には補てんということで考えていいんですか。その辺だけ聞いて終わりにいたします。","respondent":"日下部企画財政課長","answer":"それが今回、平成１９年度の財調協議の三位一体改革への影響の対応ということで、２３区は主張したという、１つの背景です。","voiceIndex":111,"id":"exchange-047"},{"speaker":"飯沼委員","kind":"提案","question":"私からは７８ページの情報公開手数料についてお伺いをします。区民こそ主人公の区政を求めて、共産党は本定例会でも情報公開、そして個人情報保護条例の改正の提案をさせていただきました。今回の条例提案の改正点、３点なんですが、これに絡めて、ご質問をします。この３点を求めました。１点目ですが、なぜ手数料を有料化としているのか、このことについて、区のお考えをお聞きします。","respondent":"中川原広報広聴課長","answer":"なぜ情報公開の手数料を有料にしているかですが、地方自治法の第２２７条に基づきまして、特定の方のためにする事務につきましては手数料を徴収するということがありますので、それに基づきまして、品川区としても手数料条例を設けているところです。","voiceIndex":115,"id":"exchange-048"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私はこの情報公開を求める方々は、これは特定の者に値をしないと思っています。なぜなら全国の市民オンブズマンの連絡協議会の中では、こういった見解を示しています。なぜ知る権利が入っていないのかという点と、あと意思形成過程における行政情報の公開、このことも入れていくべきであると考えますが、この点について区のご見解をお伺いいたします。","respondent":"中川原広報広聴課長","answer":"意思形成過程の問題ですが、これは一律に公開しないと言っているわけでございませんで、先般の条例改正で原則は公開としつつ、公開することによって、その審議・検討または協議に支障が生じる場合については。","voiceIndex":117,"id":"exchange-049"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私はこれをしっかり理事者の皆さんにもお読みいただきたいし、本旨をくみ取っていただきたいと思います。これも情報を隠す方向の中で、後手後手になって、それで被害者を増やしたという、当時その辺の情報開示が非常に大事だと言われていたわけですけれども、こういった内容を受けても、なおかつ地方自治法の本旨といった機械的なご答弁で済まされるのか、その辺をお伺いしたいと思います。","respondent":"中川原広報広聴課長","answer":"情報公開制度の運営も適切になされるということで、先ほど委員が話されましたことは十分担保できていると考えています。","voiceIndex":119,"id":"exchange-050"},{"speaker":"飯沼委員","kind":"質問・要望","question":"非公開のところの問題ですね。そういった中身で、とにかく意見は聞き置くだけといった状況になっているんですが、私はこんなとんでもないことが起きていいのかなという、本当に腹立たしく思っているわけですが、特にこういった面でも意思形成過程、区政を進めるに当たって、住民の声を最も聞いていかなければいけないと思っていますが、この点についてはいかがでしょうか。","respondent":"中川原広報広聴課長","answer":"今の事例に当てはまるかどうかわかりませんが、意思形成過程というのは、行政情報が持っている会議録のことを情報公開条例の対象としているものでありまして、この間、こういった会議、この件に関しましての会議についての意思形成過程の情報公開請求は出ておりません。","voiceIndex":121,"id":"exchange-051"},{"speaker":"飯沼委員","kind":"質問・要望","question":"事例としては、ちょっとこちらに聞く中身ではなかったと思うんですが、区長は今第１回の定例会の中で、区民の声を聞く、ここに出発点を置いて、より開かれた区政運営の道筋をつけてまいりますといった施政方針演説をされましたけれども、私は情報公開の透明性を高めていくことがより住民参加、活性化をさせていく道であると思うんですが。","respondent":"中川原広報広聴課長","answer":"議員のご質問は情報公開制度と情報を公開してほしいということが何か一緒になっているように受けとめられるんですけれども、情報公開制度の運用としては、対象になる文書は公開できる段階で公開をしていますし、それにつきまして請求が出る場合にはお出ししているところです。","voiceIndex":123,"id":"exchange-052"},{"speaker":"若林委員","kind":"質問・要望","question":"７９ページの住民基本台帳カード交付、それから７０ページの借上型区民住宅につきまして２点お願いいたします。最初に住基カードです。これは単純に昨年、平成１８年度の当初予算の中では８００件という表示がございまして、今回、平成１９年度の予算では１,５００件です。およそ倍に増えているわけですけれども、内容についてお知らせをいただきたいと思います。","respondent":"上川内戸籍住民課長","answer":"前年の実績に合わせてやってあります。平成１６年度が８３４件、平成１７年度が１,３００件になってありますので、１,５００件で予算計上したものです。","voiceIndex":126,"id":"exchange-053"},{"speaker":"若林委員","kind":"質問・要望","question":"年々上がってきているということで、いわゆる今後の住基カードの利用についてなんですが、多目的な利用について、今後の取り組み、区民の利便性が高まるという意味での交付の数の増大とともに、その内容についてもお知らせいただきたいと思います。","respondent":"上川内戸籍住民課長","answer":"多目的活用なのですが、国のほうも一生懸命活用に努めているところなのですが、やはりなかなか制約がございまして、国が思ったとおりには進んでいないという現状があります。","voiceIndex":128,"id":"exchange-054"},{"speaker":"若林委員","kind":"意見","question":"具体的に現状のサービス、基本となる住基カードのサービスと、それから多目的なサービスが現状、どうなっているのか。それからただいまのご発言でありましたけれども、他自治体等の様子を見ながらですけれども、さらにどういうサービスを視野に入れているのか。","respondent":"上川内戸籍住民課長","answer":"住基カードを単体で、なかなか自治体が独自でサービスを拡充していくというのは国も悩んでいるとおり、難しいものがあります。","voiceIndex":132,"id":"exchange-055"},{"speaker":"若林委員","kind":"質問・要望","question":"続きまして、借上型区民住宅の使用料につきまして、これは昨年の決算特別委員会でもさせていただきました。引き続きまして、より安価で、よい区民住宅の充実に向けてご質問をさせていただきたいんですが、まず予算書の見方です。７０ページに使用料、それから９０ページに国庫の補助金、それから１０２ページに都の補助金、また１２５ページに共益費と、このように収入があります。","respondent":"齋藤住宅課長","answer":"国からの補助金が９１ページで、都からの補助金が９６ページです。その４分の１、３分の１と申しますのは、住宅の家賃によって、３分の１補助をいただける住宅と、４分の１補助金をいただける住宅があります。３分の１、４分の１というのはそういう意味です。","voiceIndex":134,"id":"exchange-056"},{"speaker":"若林委員","kind":"確認","question":"今、３分の１、４分の１とありましたけれども、今、９０ページの国庫のほうを言っておりますので、２分の１と３分の１で、それぞれ家賃の違いによってという理解で、もう１回確認します。","respondent":"齋藤住宅課長","answer":"委員のご指摘のとおりです。","voiceIndex":136,"id":"exchange-057"},{"speaker":"若林委員","kind":"意見","question":"じゃ、同じ意味で、同じ家賃に対して都の補助金も上下、そのまま４分の１、６分の１になっていると理解をします。そこで以上、７０ページから１２５ページの共益費の合計が単純に足し上げまして、５億７,０００万円余、それから先ほど申しました、歳出のほうで６億６,０００万円余と、差し引きの額がありますけれども、これは予算の立て方においては、どのような意味があるのか、お願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":138,"id":"exchange-058"},{"speaker":"若林委員","kind":"質問","question":"その差額が単純に１億１,０００万円ぐらいですね。昨年の決算のときに伺いましたのは、約３,０００万円強の区の持ち出しがありますですけれども、今のご答弁ですと、１億１,０００万円以上に広がっておりますけれども、この考え方はどういうふうにとらえたらよろしいでしょうか。","respondent":"齋藤住宅課長","answer":"一方で、使用者の方から１６億円ほどの使用料が入ってありますので、何が言いたいかと申しますと、単純に差し引きした部分が区の空き家の部分の持ち出し部分です。","voiceIndex":143,"id":"exchange-059"},{"speaker":"若林委員","kind":"確認","question":"そうしますと確認ですが、昨年の決算でいただきました３,０００万円強の区の持ち出しというのは、そのままこの平成１９年度の予算についてもそのぐらいを見込んでいると理解をしてよろしいんですね。","respondent":"齋藤住宅課長","answer":"今、委員がおっしゃった３,０００万円というのは空き室部分に対する区の負担分ですので、空き室部分については、使用料は入ってきませんから、もちろん国・都からの補助金も参りませんので、その部分は区の持ち出しになります。","voiceIndex":145,"id":"exchange-060"},{"speaker":"若林委員","kind":"意見","question":"そうすると、３,０００万円でそのまま今年も、それは１年通してみないとわかりませんけれども、多分、去年のご答弁ではそういうことだと理解をいたします。昨年の予算よりも今年の予算のほうが使用料、収入が多くなってありますけれども、これは家賃が上がるということを前提にこのような算出をしているのかどうか。","respondent":"齋藤住宅課長","answer":"委員の今ご指摘の４億５,５８０万円余は入居者が全員入って、使用料もお支払いいただくということを前提にしております。使用料が増えてありますのは、年３％ずつ傾斜型家賃の部分は使用料が上がってありますので、その分が上がってあります。","voiceIndex":147,"id":"exchange-061"},{"speaker":"若林委員","kind":"意見","question":"ちょっと角度を変えまして、もう１回、昨年の平成１８年度の予算の中では、同じく使用料の中に連絡員手当という項目が載っておりまして、平成１９年度、来年度の予算では、この連絡員手当というのがありませんですけれども、このご説明をお願いいたします。","respondent":"齋藤住宅課長","answer":"区営住宅には入居者の方の区との連絡をお願いすることで、連絡員という方を１棟にお一人ずつお願いしてございましたが、これを指定管理者に仕事を委託するということにしましたので、連絡員制度というものを基本的に廃止しております。","voiceIndex":149,"id":"exchange-062"},{"speaker":"若林委員","kind":"質問・要望","question":"これはお住まいになっている区民の方からの声ですけれども、いわゆるこの指定管理者になったがゆえにというふうに言っていいのかどうかわかりませんが、こういう共同住宅というのはご存じのように、例えば生活騒音とか、また振動とかという、さまざまな共同住宅独特のいろいろな住まわれている間での問題がありますけれども、こういったいわゆる苦情に対して、オーナー、住宅課。","respondent":"齋藤住宅課長","answer":"第１点目の利用関係についてですけれども、基本的には指定管理者が水回りですとか、修繕の関係については対応しています。その他、それを超えたものにつきましては、私ども住宅課に連絡が来ますので対応しております。","voiceIndex":151,"id":"exchange-063"},{"speaker":"若林委員","kind":"質問","question":"この窓口について、指定管理者であるということは、十分に周知をされるよう、また努力をお願いしたいと思います。それから共益費については、オーナーから提示をされるんですね。ちょっとご答弁をお願いしてよろしいでしょうか。なぜ指定管理者じゃなくて、オーナーのほうから共益費の開示をされるのか。","respondent":"齋藤住宅課長","answer":"大きな修繕、小さな修繕含めて、オーナーの方がなさっております。したがって、共益費を集めたものを使うことについてはオーナーの方がやっていらっしゃいますので、その収支・明細を明らかにするのはオーナーの方の責任であります。","voiceIndex":153,"id":"exchange-064"},{"speaker":"若林委員","kind":"意見","question":"昨年からまた今年度にかけてのご努力、また今後の見通しについても一言お願いをいたします。","respondent":"齋藤住宅課長","answer":"これを１つ強調させてください。引き続き、次に今後、現在の検討状況ですが、オーナー会の皆さんともこの委員会が終わった後、お話し合いをする場も持ってあります。率直に区の考え方もお伝えします。","voiceIndex":155,"id":"exchange-065"},{"speaker":"若林委員","kind":"質問","question":"いわゆるオーナーの損益分岐点、こういう言い方があるのかどうかわかりませんけれども、建設時に国の補助、それから低利の融資を受けて、建築されて２０年間の契約ということですけれども、オーナーとしての損益の分岐点というのはどのように考えたらよろしいんですか。","respondent":"齋藤住宅課長","answer":"それは私ども家賃保証をしている関係で、安定して計算できるわけでございまして、それに従いまして、オーナーの考え方によって損益分岐点というのは変わってきてあります。","voiceIndex":157,"id":"exchange-066"},{"speaker":"本多委員","kind":"質問","question":"６１ページの区民保養所使用料について質問いたします。最初に品川荘、箱根荘、平成１８年度と平成１９年度の予算書を比べて、その見込みという、人数や部屋数はわかるんですけれども、１５人以上の団体について、推移というか、見込みをどのように考えているのか、品川荘、箱根荘についてお聞かせください。","respondent":"鷹倉区民課長","answer":"今、１５人以上の団体に限っての推移というお尋ねかと思いますが、ちょっと申し訳ございません。手元に団体だけのものを集約した資料は手持ちのほうでは持ってございません。","voiceIndex":160,"id":"exchange-067"},{"speaker":"本多委員","kind":"質問","question":"予算書を見ると、この部屋数、人数ですから、比べるとわかるんですけれども、団体はどうなのかなと思って、ちょっと聞かせていただきましたが、送迎バスについて、今度教えていただけたいんですけれども、品川荘、箱根荘の台数ですとか、稼働状況について教えてください。","respondent":"鷹倉区民課長","answer":"区の所有のバスが１台あります。ただ、これは少し年式が古うございまして、委託業者のほうで用意している車がもう１台あります。箱根荘については２台を使ってありますが、１台はちょっと古うありますので、その２台を効率的に使っているというような状況です。","voiceIndex":162,"id":"exchange-068"},{"speaker":"本多委員","kind":"質問・要望","question":"よく区民の方と話をしていまして、品川荘ですとか、箱根荘に行く道のりで、品川荘ですと、伊東駅でおりて、歩いていくと、大体３０分も歩くと、品川荘に着くと思うんですけれども、伊東の駅から駅前の商店街を抜けて、川沿いを歩いていったら３０分ぐらいで、非常にいいですよなんて、私は結構勧めているんですけれども、ただ、歩いていける方ばっかりではないので。","respondent":"鷹倉区民課長","answer":"もう１台、業者が提供している車については、平成１４年式の車ですので、今お話の件は恐らくたまたま２台のところで、区の部分に乗られたのかなと。平成１４年ですと、それほど古くはないのかなと思っているところです。","voiceIndex":164,"id":"exchange-069"},{"speaker":"本多委員","kind":"質問・要望","question":"公有財産を有効的に使っていると理解して、少しでもそういう区民の要望を聞いて、できるところは取り入れていただきたいと思います。区民保養所の条例ですとか、要綱ですとか、品川荘と箱根荘は当然続けていくんですけれども、今までのものとか、新しく取り入れるものですとか、そういった部分の条例とか要綱について、定めについてちょっと教えていただきたいと思います。","respondent":"鷹倉区民課長","answer":"今回、３月３１日で廃止になる暖景苑、これは利用料という形で歳入に入れさせていただいておりました関係で、これは要綱という形で定めさせていただいていました。これについては、今回、３月３１日に暖景苑が終わりますと、要綱の廃止という形になっていくかと思います。","voiceIndex":166,"id":"exchange-070"},{"speaker":"本多委員","kind":"質問・要望","question":"この保養所の新しく取り入れる３つの施設なんですけれども、予算書で行くと、歳出ということなんですけれども、歳入のほうには載っていないんですけれども、その入口の部分だけちょっと質問させていただきたい。関連性があるものですから、聞かせていただきたいと思います。その平成１９年度から保養所として新しく民間施設を借り上げるというなんですけれども、そうすると、今度要綱になるわけですかね。","respondent":"鷹倉区民課長","answer":"区民の方には利用料ということで、直接現地で支払っていただくということもございまして、委託契約でやっていく。特に要綱等については定めない形で実施していきたいと考えているところです。","voiceIndex":168,"id":"exchange-071"},{"speaker":"本多委員","kind":"確認","question":"委託契約で現地に支払うということですから、これから先も予算の歳入では出てこないんだろうと。それをちょっと確認をします。その辺の特定日がばらつきがあるのは、この辺は統一というのは難しいですよね。ちょっと確認だけお願いします。","respondent":"鷹倉区民課長","answer":"ご指摘のとおり、それぞれの旅館の運営のままをそのまま借り上げていくということですので、ばらつきがたまたま出てしまうです。できるだけわかりやすい形で統一したいわけですけれども、その部分については統一できないということでご理解いただきたいと思います。","voiceIndex":170,"id":"exchange-072"},{"speaker":"本多委員","kind":"質問・要望","question":"今までの４７人という暖景苑の規模に対して４５人ということで、おおむね人数的には同じような方が、そういう健康増進のために利用できると思うんですが、当然、品川荘と箱根荘がありますけれども、さらに団体というところも引き続き見ていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":172,"id":"exchange-073"},{"speaker":"木下委員","kind":"質問","question":"６６ページの産業振興施設使用料のベンチャー創業支援施設の件についてお尋ねしたいと思います。ですから、現状ですとか、それから応募の倍率、数年の推移、増えているのか、減っているのですかとか、そこのところをお聞かせ願えますでしょうか。","respondent":"金子産業振興課長","answer":"応募の状況については、先ほどと同じように、２件から４件ほど来ているです。","voiceIndex":174,"id":"exchange-074"},{"speaker":"木下委員","kind":"質問","question":"女性の方が大体起業するんだったら、サービスのほうになっちゃうから難しいんじゃないでしょうか、何とか入れませんでしょうかという話を聞いたことがあるんですが、私としてはそんな差はないはずですよという話をしていたんですけれども、そこら辺の件でどのように考えていらっしゃるのか、ちょっとお聞きしたいのと、それから武蔵小山駅に総合支援施設ということで。","respondent":"金子産業振興課長","answer":"それから平成１９年度予算のほうで武蔵小山の創業支援施設の検討経費を計上していますが、こちらは商業系の施設を中心にというふうには考えておりますが、これから検討をしてまいります。","voiceIndex":176,"id":"exchange-075"},{"speaker":"木下委員","kind":"質問","question":"ですから、広町のほうはものづくりのほう主体なんだけれども、広く解釈してということですので、そういうサービス関係の方々も、これから考えていただけるものじゃないかなと考えていますし、武蔵小山の創業支援施設のほうでは女性起業家の方を優先するというか、そういう枠なんかもつくっていただけると理解してよろしいんでしょうか。","respondent":"金子産業振興課長","answer":"武蔵小山の施設の検討なんですけれども、これから始まりますので、ただターゲットとして考えているのは、先ほど申しましたとおり、１つは商業系中心である、あるいはもう１つは女性起業家の支援ができないかということ。","voiceIndex":178,"id":"exchange-076"},{"speaker":"木下委員","kind":"質問","question":"ボランティア活動をした際にポイント制でもいいから、何か割引だとかそういうのをやっていただければ、ボランティア活動をやるにしたって、やりがいが出るんじゃないかみたいなお話をお伺いして、私なんかはスーパーだとかそういう買い物に行く際でも、ポイントなんかあまり利用しないんですけれども、意外とそういうポイントをためて、楽しみに利用していらっしゃる方々なんか、かなりいらっしゃいますので。","respondent":"堀越行財政改革担当課長","answer":"今、委員ご提案のお話もありましたけれども、今、区民、それからＮＰＯボランティア等と連携の仕組みづくりを行っておりますので、その中でいろいろよその自治体なんかでもそういったポイントとかいろいろなお話も聞いておりますので。","voiceIndex":182,"id":"exchange-077"},{"speaker":"木下委員","kind":"質問","question":"検討していただけるということで、実施していただけるんじゃないかなと理解いたしましたので、よろしくお願いいたします。続きまして７８ページ、総務手数料。そこら辺の枚数的な問題といいますか、そんなに減るのかなとちょっと思ったものですから、そこら辺はどのようにご理解されていらっしゃるのか、ちょっと何か理由があるかどうかもお教え願えますでしょうか。","respondent":"上川内戸籍住民課長","answer":"住民基本台帳の証明手数料のほうですが、住基カードの交付の件については増えてありますが、住民票の写しは減ってあります。それは住基ネットの第一次活用が大幅に、着々と増えているということで、住民票が減っているということで、約６００万円減です。","voiceIndex":184,"id":"exchange-078"},{"speaker":"木下委員","kind":"質問","question":"ちょっと時間も迫ってまいりましたので、あと１２０ページ、介護報酬の件について、ケアプラン作成報酬の増ということで、９４.３％増というご説明がありましたけれども、単純に作成報酬は倍になったということなんでしょうか。ここ数年の人数的な面ですとか、今後どのような推移をするのかですとか、お考えになっていらっしゃる部分をちょっとお教え願えればと考えています。","respondent":"蓼沼高齢福祉課長","answer":"平成１８年度につきましては、区の在宅支援センターが地域包括の機能を一部担っているということで、直接在宅支援センターのほうに報酬を支払うようにしておりましたけれども、これは国保連のほうから基本的には区が地域包括なので、区のほうで受けるべきではないかということで。","voiceIndex":186,"id":"exchange-079"},{"speaker":"木下委員","kind":"質問","question":"私がこの質問をしたのは、利用者の負担が増えるのではないかというので、心配して質問させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":188,"id":"exchange-080"},{"speaker":"原（浩）委員","kind":"質問・要望","question":"私のほうからは９０ページ、９２ページ、９３ページおよび都の補助で１０４ページ、その辺のところの耐震診断および改修関係の歳入からお伺いしていきたいと思います。それから歳入についてなんですけれども、今の一般木造関係の家屋、それから学校の耐震改修工事等についての数字等の推移について、所管のほうで所見等があれば、お教えいただきたいということです。","respondent":"片田建築課長、市川庶務課長","answer":"私どものほう、促進計画を含めてということで考えてありますけれども、これまで平成１６年の４月から木造等の民間建築物の耐震診断等々の支援を行ってきてあります。この実施校につきましては、平成１５年度から平成１７年度にかけまして、３カ年に分けて、区内の小中学校およそ半数を対象にして、耐震診断を行い、その結果、必要と思われる学校につきましては、翌年に実施設計を行って。","voiceIndex":190,"id":"exchange-081"},{"speaker":"原（浩）委員","kind":"意見","question":"校舎のほうから行きますと、学校のほうの耐震関係、改修工事、これは多分国土交通省の告示の１８４および１８５を指針としてやっていらっしゃると思いますけれども、１点、イエスかノーかだけ。","respondent":"宍戸施設担当課長","answer":"今、委員ご指摘の告示に基づいて行ってあります。","voiceIndex":193,"id":"exchange-082"},{"speaker":"原（浩）委員","kind":"確認","question":"そうしますと、前者のほうの一般の木造関係について、これは質問ということになるかどうか、歳入面からですので、１点。これは今現在、私どもインターネットのほうを確認させていただきましたけれども、専門機関に委託されているということ。","respondent":"片田建築課長","answer":"その中で一律、現況行っている木造住宅については１２万円と、４月から今予定しています、アパート等も想定していますけれども、そういうものについては２４万円を今想定して考えてありますけれども、一律の金額の中で行っていきたいと。","voiceIndex":195,"id":"exchange-083"},{"speaker":"原（浩）委員","kind":"質問・要望","question":"歳入面を主ということなものですから、一応数字的なことを申し上げてしまいますと、これは診断の専門家という職員の中だけということではなくて、もう少し逆に国からも都からも受け皿、２１０万円と約４００万円ということなので、ちょっと私のほうにいろいろなところの区民の方からのお声ですと、対象建築物、それから対象者、この辺の条件づけというんですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":197,"id":"exchange-084"},{"speaker":"南委員","kind":"質問","question":"６８ページの区営住宅の使用料、そして同じページの自転車駐車場の使用料の２つを質問したいと思います。区営住宅のほうですが、この使用料収入１億３,１７４万３,０００円という数字が計上されておりますが、品川区内の公営住宅の整備率はどういう状況になっているのか、ちょっと全体的な住宅総数との関係で、実態をお知らせください。","respondent":"齋藤住宅課長","answer":"委員に今お話しいただいた、公営住宅の整備状況ですが、区営住宅が４３９戸あります。都営住宅は３,５７８戸あります。東京都の公社の住宅が区内で５４４戸、都民住宅は４０７戸、旧住都公団、ＵＲ都市機構の住宅が３,９６７戸、区の区民住宅が１,０５６戸となっております。","voiceIndex":199,"id":"exchange-085"},{"speaker":"南委員","kind":"確認","question":"私がここでちょっと問題にしたいというか、質問したいのは、いわゆる低所得者用の住宅の関係です。ちょっと違うみたいな感じ。でも総数的に４,６５０とそんなに大きな差はないと思うわけですが、区営住宅の４３７戸は、ちょっと計算してみますと、全住宅戸数が１６万５４０戸、これと比較すると、区営住宅の割合は０.３％という数字じゃないかなと考えていますが、この数字について確認をしたいと思います。","respondent":"齋藤住宅課長","answer":"委員おっしゃいました、区の住宅の戸数はその比率で間違いございません。委員のご指摘の相差の部分は、恐らく高齢者住宅や借上住宅、障害者住宅を含むと、４,６５０になると思います。","voiceIndex":201,"id":"exchange-086"},{"speaker":"南委員","kind":"質問","question":"ついでに応募状況、この区営住宅、都営住宅も含めて、かなり厳しい倍率だと聞いておりますけれども、ちょっと応募状況についてお尋ねしたいと思うんです。そしてその内訳として、高い３けたの倍率になっているところを見ると、東品川は２０８倍、東品川の第二都営というところは３８６倍という数字になっているんですが、合わせて品川区の区営住宅の応募実態についてもちょっと教えてください。","respondent":"齋藤住宅課長","answer":"大体１０戸から１２戸ぐらいあきます。実質そういう倍率で言いますと、５０倍前後の倍率になります。ただ西大井六丁目第三に単身向けの３４戸がございまして、そこの応募が大変多くて、これが２００戸ありますので、家族向けの応募は４００人前後です。","voiceIndex":203,"id":"exchange-087"},{"speaker":"南委員","kind":"質問","question":"３０戸に対して２,０００人が応募されたと。私はこれは絶対にみんなが入れるような状況ではないということは明らかだと思うし、どのくらいの年数がたてば、こういう希望されている方々が入れるようになるのかという見通しも持てないほどの状況だと私は思うんですけど、そういう見解についてはいかがでしょうか。１年か２年なのか。あるいは５年、１０年なのか、ちょっとその辺の傾向を教えてください。","respondent":"齋藤住宅課長","answer":"これを平成２０年度までに改正することになっておりますので、この収入基準の見直しが図られれば、申し込みされる方は減ってくるんだろうと考えています。","voiceIndex":205,"id":"exchange-088"},{"speaker":"南委員","kind":"質問","question":"今の収入基準の見直しというところがよくわからないんですけど、いわゆる収入分位の低いほうに基準を下げるというふうに理解していいんですか。もしそうであれば、私は所得の低い方々がやっぱり絶対的に決して裕福じゃないという方々が入りたいという、そこのところをさらに阻む、狭めるものになるんじゃないかなと思うんですけれども、その点についての見解もお願いします。","respondent":"齋藤住宅課長","answer":"国の収入分位で申しますと、今のところ、１００人いらっしゃると収入の低いほうから４０番目までが申し込みができると。入れるということになっておりまして、国も１０年ぶりに収入基準の見直しをして、一般的なモデルである収入分位２５％までの方に収入基準を改めるです。","voiceIndex":207,"id":"exchange-089"},{"speaker":"南委員","kind":"質問・要望","question":"そういう実態をどう解消するかというビジョンをやっぱり示すべきだと思うんですね。西大井六丁目の区営住宅の建設費は１戸当たり７００万円だと聞いておりますけれども、この数字でいいのかどうかもちょっと確認したいんですが、この数字でよしとしたならば、私ども日本共産党がこの間とったアンケートで、公営住宅、区営住宅の建設を求める方は、２４.８％いらっしゃるんですね。","respondent":"福田まちづくり事業部長","answer":"したがいまして、私どもといたしましては、住宅に困窮する方についての住宅供給について、十分に施策を展開しているという認識です。","voiceIndex":209,"id":"exchange-090"},{"speaker":"南委員","kind":"質問・要望","question":"先ほどご紹介したように、少なくとも２４％の方、４人に１人の方が区営住宅の建設を求めておられるんです。この数字はどういうふうに見るのかという、そこのところが行政としての姿勢じゃないんでしょうか。隣の区と平均して、それを上回っているから、もういいんだという考え方でとっていいんでしょうか。ちょっとその辺を伺いたいと思います。自転車駐車場のほうは残念ですけど、ちょっと今日はできません。","respondent":"齋藤住宅課長","answer":"こういった民間のあきを低所得者のために誘導できないか。今、国のほうでもさまざまな取り組みを進めておりますので、こういった国の動きを見ながら、そういった低所得者の方のための住宅というのも一定程度確保できないか。これは検討する時期だと考えております。","voiceIndex":211,"id":"exchange-091"},{"speaker":"南委員","kind":"質問・要望","question":"品川区に住み続けたい。しかし、住宅費が高くて出ていかざるを得ないという区民を支えるような姿勢を、さまざまな手法を講じて、とっていただきたいということを求めて終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":213,"id":"exchange-092"},{"speaker":"須貝委員","kind":"質問","question":"今回、平成１９年度品川区の一般会計予算、１,３４５億円。実際困っているというのも児童課にしろ、福祉高齢事業部にしろ、そういうところでそういう苦情なりいろいろ質問を受けていると思いますが、こういうふうに箱物ではなく、実際生活している人に対して、より大きな人的あるいはソフトの面でのサービス事業を展開するのが本来は品川区として、私は行政の仕事ではないんでしょうかと思います。","respondent":"日下部企画財政課長","answer":"大きくは２点のご質問があったかと思います。","voiceIndex":215,"id":"exchange-093"},{"speaker":"須貝委員","kind":"意見","question":"話はよくわかりました。３割減額されて、もし私の記憶違いなら申し訳ありませんが、残り３割ぐらいはお手伝い、地域清掃等をした場合にはまたその分を補てんするような仕組みに変わったということで、皆さん大変お困りになっておりますが、その辺、また前に戻していただいて、お手伝いする人には付加して、もうちょっと補助してやるような仕組みにならないのかどうか、お答えをお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":217,"id":"exchange-094"},{"speaker":"須貝委員","kind":"質問・要望","question":"すみません、要望だけで。質問というか、そういう補助金をせっかく都のほうからもいただいていると思いますが、高齢者は今、大変な方が多いので、その辺、もっと温かい補助金を品川区のほうも今後展開していただければありがたいなということで質問を終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":219,"id":"exchange-095"},{"speaker":"山内委員","kind":"質問・要望","question":"私からは１２２ページの雑収入の水族館運営費収入についてお尋ねいたします。その約２割ほどの売上が上がるということなんですが、その要因と、それから今年度の来場者数というんですか、前年度に比べて、どれぐらい増えたのかというのをまず１つ教えていただきたい。","respondent":"藤田道路公園課長","answer":"昨年はちょうど４月に品川駅の駅前のほうに水族館ができまして、それとの相乗効果で大分増えたということで考えてあります。","voiceIndex":221,"id":"exchange-096"},{"speaker":"山内委員","kind":"質問","question":"その内容というものがやはりマンネリ化してしまうのではないかというようなところで、運営を委託しているサンシャインと、品川区との間でどのような話をして、今後マンネリ化をしないような形にしないと、どうしてもこういうところというのはリピーターが大事だと思うんですけれども、その辺についての民間とのお話し合いというか、今後の運営とかというのは常にお話をされているような状況なんでしょうか。","respondent":"藤田道路公園課長","answer":"そういう中で、これからはやはり施設をつくるだけではなく、物の見せ方といったものにも工夫しながら、これから水族館と、これまでも十分話し合いはしてきておりますけれども、とにかく何でもいいから、何か考えがあれば言ってくれということをスタートに。","voiceIndex":223,"id":"exchange-097"},{"speaker":"山内委員","kind":"質問","question":"後から聞いて、そんな制度があったんだなんていうことを知る方がいるという話を聞きまして、せっかくサービスをするのであれば、例えばチケット販売のところに例えば掲示を出して、区民の方は割引制度がありますよというような案内をする必要性があるとは思うんですけれども、私もわからなくて、従業員の方にどこに表示されているんですかと聞いたら、すみません、ちょっとわからないですと。","respondent":"藤田道路公園課長","answer":"平成１７年度につきましては約１,０００人ということで、今回平成１８年度７月から区民割引をスタートして、すみません、手元の資料が１月末の資料ですけれども、６,６００人ということで、平成１６年度の２,０００人に比べましても。","voiceIndex":225,"id":"exchange-098"},{"speaker":"山内委員","kind":"質問","question":"私は先週の金曜日に行ってきたので、まだ改善されていないみたいなので、お願いします。それから、これはちょっと難しい話なのかもしれませんが、先ほども課長からお話が出ました、品川駅前のプリンスホテルの中の水族館はエプソンという名前がついておりますよね。さらなる施設の充実、そのようなことをお考えかどうかというのを最後に教えてください。","respondent":"藤田道路公園課長","answer":"その辺とあわせながら、考えて進めていきたいと思ってあります。","voiceIndex":227,"id":"exchange-099"},{"speaker":"山路委員","kind":"質問","question":"ちょうどシルバーセンターの前にバス停がありまして、歩道が狭いところなんですが、シルバーセンターを利用する方がそのバスをおりられる前後が満員になりまして、地域住民の方が歩道を通れない、自転車も通行できない状況になりますので、真ん中辺で線を引いて、それで地域住民の皆さんも通れて、シルバーセンター利用者もきちっと１列に並んでいただいて。","respondent":"冨岡高齢事業課長、松嶋交通安全担当課長","answer":"私はマッサージのほうで、改修が終わりまして、本来のもとの姿でご利用いただけるような形にしているはずですけれども、そういう形でご不便をかけているとすると、まことに申し訳なく思っておりますので、それにつきましては。したがいまして、ただ現在、そういった事情があるのであれば、これは今後バス事業者ならびに警察、それと区のほうで現場を確認させていただきまして、何かいい施策があればそれをとっていきたいと考えております。","voiceIndex":230,"id":"exchange-100"},{"speaker":"山路委員","kind":"質問","question":"次に行きます。健康センター使用料のコース型教室、人気のあるコースとか、いろいろ６,２００万円計上してありまして、８万３,１６０回、教室が開かれたと思いますけれども、子どものバレエ教室というのがあるということを伺っておりますが、どういう内容でやられているのか、ちょっとお伺いいたします。","respondent":"谷田部健康課長","answer":"子どもの講座というのはたくさんございまして、３歳から４歳の体操に始まりまして、年代ごとの体操の教室、それからバレエがヒップホップ系のそういうダンス系もありますし、エアロビクス部もございまして、あと３歳６カ月から４歳のバレエ、これはプチバレエと申しますけれども。","voiceIndex":233,"id":"exchange-101"},{"speaker":"山路委員","kind":"質問","question":"実は小学校５年生の女のお子さんが、昨年はバレエ教室のメンバーであったのですが、新しく小学校に入ってくる方がたくさん今年は教室に入られるので、抽選に漏れてできなくなったということを非常に残念がられていたんですね。もう少しキャパを広げて、そういう一生懸命になっている方が参加できるような体制は考えられないものでしょうか。","respondent":"谷田部健康課長","answer":"ただ、その時々に、ある程度人気が落ちてきて、ほかの講座に組み替えるということもございまして、そういうような組み替えはしていますけれども、非常に残念なことですが、なるべく需要に応じたコースはとりたいと思うんですが、一方でまた違うニーズもございまして。","voiceIndex":235,"id":"exchange-102"},{"speaker":"山路委員","kind":"質問・要望","question":"自転車駐車場使用料。私もよく駐輪場に自転車をとめるんですけど、東大井にあります、大井陸橋下の駐輪場、あるいは富士ガーデン横の駐輪場。２時間超えますと１００円とか１５０円入れますね。後は定期的に契約した人とか、いろいろいらっしゃいますけど、その駐輪場、１００円とか１５０円入れたお金の回収というのはどのような体制でやられているのか、お伺いいたします。","respondent":"松嶋交通安全担当課長","answer":"これは現在、業務委託をいたしております、日本コンピュータ・ダイナミクス、それと昭和建物の２社ですけれども、これは毎日精算をして、銀行に入れて、翌日になりますけれども、区のほうにその部分をすべて報告になっております。","voiceIndex":237,"id":"exchange-103"},{"speaker":"山路委員","kind":"質問・要望","question":"実は地域住民の方からご相談いただきまして、実際にシルバーセンターの方が回収している。非常に不安定なところがありますが、区はチェックしているんですか。もう少しセキュリティをしっかりしてくださいというご意見がございましたので、実際に回収はどこでやって、どのようにやっているかということをもう１回チェックをしていただきたいと思います。この辺について、どのようにお考えでしょうか。","respondent":"松嶋交通安全担当課長","answer":"そこでも確認をいたします。その後に区にきまして、区でも毎日確認をしますので、そこら辺は間違いなくやられていると思っています。","voiceIndex":239,"id":"exchange-104"},{"speaker":"山路委員","kind":"質問","question":"天王洲野球場のサッカー部門です。サッカー利用者の方から、今年の冬は昨年からサッカーが利用できて、非常に喜んで、サッカーをたくさんの人がやっていた。ところが、夏はここは使わせてもらえないんでしょうかという話をちょっと伺ったんですがということで、芝の関係かなといろいろ考えたんですけど、そういう相談を受けましたので、どういう形で使えるか、ご説明をお願いいたします。","respondent":"富田生涯学習課長","answer":"したがいまして、予算書をごらんいただければと思いますけれども、実際の利用は野球が６割、サッカーが４割という利用状況になっております。","voiceIndex":241,"id":"exchange-105"},{"speaker":"山路委員","kind":"質問","question":"予算書でも野球に比べて、サッカーのほうは約半分の使用率ですよね。夏も使えるということでよろしいんでしょうか。","respondent":"富田生涯学習課長","answer":"３カ月前の抽選、優先の枠というのは野球でございまして、野球団体対象に抽選を行いまして、その後、あいた時間帯につきましてサッカーの方もご利用いただけるということになっております。","voiceIndex":243,"id":"exchange-106"},{"speaker":"山路委員","kind":"質問・要望","question":"続きまして、マイガーデン運営費負担金についてお伺いいたします。マイガーデンは豊町を本年度中に終了して、南大井のほうに新設されることだと思うんですが、この辺の経緯について説明をしていただきたいと思います。","respondent":"藤田道路公園課長","answer":"そういった関係もございまして、新たな区民農園、マイガーデンの用地の確保ということで、南大井のほうにこの後、平成１９年度ご承認いただければ、整備をし、開放していきたいと考えているものです。","voiceIndex":245,"id":"exchange-107"},{"speaker":"山路委員","kind":"質問","question":"ところで北品川、南品川、東品川の方面の方がマイガーデンがこちらの方面に欲しいという希望を持った方が何人かいらっしゃいまして、どの辺の場所にできるんでしょうか。それと車いすの方でも農作業ができるような設備も可能でしょうかというご相談を受けているんですが、この辺についてはどのように考えていらっしゃるんでしょうか。","respondent":"藤田道路公園課長","answer":"マイガーデンの南大井、これからつくるものにつきましては、現在の計画地についてはこれから地元調整等もありますので、国道沿いの南大井のほうの公園の一部を使うです。それと、施設のあり方については、これから中身についてよく検討してまいります。","voiceIndex":247,"id":"exchange-108"},{"speaker":"伊藤委員","kind":"質問・要望","question":"私は６３ページ、シルバーセンターに関連してなんですが、そのことと、それからあと８０ページの建築確認手数料に関連して質問いたします。内容は、耐震診断の結果、この複合施設を改修する話を聞きました。簡単にそのスケジュールを教えていただきたいのと、それから、その改修の内容はどうでしょうかということをお聞かせください。","respondent":"冨岡高齢事業課長、宍戸施設担当課長","answer":"今の南大井の複合施設ですので、私どものシルバーセンターにつきまして、ご説明申し上げます。工事の期間ですが、今年７月中旬から、来年の平成２０年２月下旬を予定しております。全体的なお話で申し上げますと、そのほかの図書館、それから児童センター、保育園につきましても、設備等も含めて、大規模改修を耐震改修にあわせて行うという予定でおります。","voiceIndex":250,"id":"exchange-109"},{"speaker":"伊藤委員","kind":"質問・要望","question":"話はそんなに難しくありませんので、これの複合施設の改築には随分いろいろな意見が届いていると思います。それから建築確認手数料のほうでありますが、これは先ほど菊地委員から質問がありました。このピアチェック機関の能力を絶対に確保していきませんと、品川区もそうですけれども、どの自治体でも責任を問われる形になっていきますので、まずそのことについての確認をお願いいたします。","respondent":"片田建築課長","answer":"どのような基準でですけれども、やはりこれまでのいろいろな構造問題等々の課題から申し上げまして、やはり専門家というものがかなり少のうございまして、その中で。","voiceIndex":253,"id":"exchange-110"},{"speaker":"伊藤委員","kind":"質問","question":"その責任を最終的に品川区がとっていかざるを得ない体制になってしまったわけですから、やっぱりこのピアチェック機関の指定することは確かに都知事であり、国土交通大臣だということは勉強しましたけれども、もっと具体的にはその先にあるピアチェック機関の能力なり、判定すべき基準なり資格なりといいましょうか、技術力と言いたいんでしょうか、そういうことをもっと品川区なり。","respondent":"片田建築課長","answer":"そんな状況の中で適正に進められていくことを私どものほうも望むところですし、これはまだ運用してございませんので、今後の経過あるいは指導監督等については、東京都のほうに対しても、十分要請していきたいと考えています。","voiceIndex":255,"id":"exchange-111"},{"speaker":"伊藤委員","kind":"質問・要望","question":"大臣認定のプログラムのことだと思われますけれども、これも私たちも勉強していきますと、最新の建築技術がどんどん進んでいるわけじゃないですか。ですから、プログラムというのは当然更新しないといけないわけですよ。ですから、こういうときだからこそ、はっきりと品川区が国に対して、あるいは東京都に対して物を言っていくべきだと思うんですが、いかがでしょうか。","respondent":"片田建築課長","answer":"確かにセキュリティの問題、プログラムについても１年ぐらいかけて、国のほうで検証していくという中で、そういう偽装等々、あるいは改ざんができないようなセキュリティを考えていくということを期待しておきたいと思いますし、それについては区のほうも。","voiceIndex":257,"id":"exchange-112"},{"speaker":"伊藤委員","kind":"質問・要望","question":"だって、責任を負わされるのは品川区なんですよ。ですから、それをきちんとこの場でお話をしていただきたいんですが、また場合によっては、品川区を通して、東京都に物事を申していくとか、それから国土交通省に対して法改正のモーションをしていくとか、そこまで具体的に話を詰めていきませんと、皆様方のお立場は守れないと思って、質問していますので、改めて答弁をお願いいたします。","respondent":"福田まちづくり事業部長","answer":"そういう背景もありますので、私ども、この問題のそもそものところに立ち返りながら、必要なところに必要な申し入れ、あるいは要請、これらについて対応してまいりたいと考えております。","voiceIndex":259,"id":"exchange-113"},{"speaker":"伊藤委員","kind":"質問・要望","question":"問題の認識が随分最終的には一緒になってきたと思われますし、恐らくは委員会ですから、言葉の端々の中で、本当はもっといろいろなことを言いたいことがあるかもしれないと、私たちは理解しています。でも問題は大きな問題だと思っていますので、ぜひ部長のお話しされたようなことも含めて、確かな形で進めていっていただきますように、要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":261,"id":"exchange-114"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"４４ページの特別区民税についてお伺いをしたいと思います。住民税のフラット化の問題なんですが、５％、１０％、１３％、これが一律１０％になっていくわけですが、今現在、５％、１０％、１３％が、それぞれ区民が何％ずつになっているのか、このことを１つ、まずお聞かせいただきたいと思います。できれば、住民税が増税になる方の割合とかもわかったら教えていただきたいと思います。","respondent":"太田税務課長","answer":"私のほうから３点についてのご質問にお答えをいたします。初めに現在の税率区分の中での納税義務者の割合ですけれども、５％の区分の方が約５２％。それから１０％の区分が４１％。それからそれを超える１３％が７％という割合になってあります。","voiceIndex":264,"id":"exchange-115"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ちなみに、この住民税が変わりますというところで、見て、私も改めて驚いたんですけど、所得税と個人住民税で、プラスマイナスで、単身者の方の場合、３００万円で１万７,３００円がプラス、５００万円の方で３万８,１００円がプラス、７００万円で６万７,４００円が、これは税金の部分だけでこれだけプラスになっているということなので、これは本当に大変な負担増になると思いますので。","respondent":"太田税務課長","answer":"ただ電話の対応について、内容については私のほうに上がってくることにはなってありますので、どういう内容かについては、今後もつかんでいきたいと思ってあります。","voiceIndex":266,"id":"exchange-116"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は先ほども定率減税の廃止でということで申し上げました。もう１つ、私は今ある制度の活用で、払わなくてもいい税金を払っているという方がいらっしゃると思うんですね。このことについて１点。こういう中でぜひ介護を受けている方に対しても、申請があった場合は認定書を出していただきたいと思うんですが、この２点についてお聞かせいただきたいと思います。","respondent":"太田税務課長、蓼沼高齢福祉課長","answer":"私のほうで１点目のほうをお答え申し上げます。広報の件については、私どもはできるだけわかりやすくという趣旨で受けとめてありますので、改善できるところには改善していきたいと。基本的には専門の機関で手帳の判定を受けていただくということが原則と考えておりますが、ただ区といたしましては要介護４、５の方について、その状態が６カ月以上経過している方については、これまでも認定書を発行してきましたので。","voiceIndex":268,"id":"exchange-117"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それで、なぜ２３区の中で、１７区もがこういう形で手帳をとらない方もやっているにもかかわらず、なぜ品川区ができないのか、ちょっと教えていただけないでしょうか。","respondent":"木下福祉高齢事業部長","answer":"したがいまして、今後のご指摘の点については、問題意識としては私も持っておりますけれども、それがやはり納税者の公平感という点から、どういう点でご理解いただけるかという部分については、やはり慎重に検討していくべき課題だろうと考えています。","voiceIndex":271,"id":"exchange-118"},{"speaker":"西本委員","kind":"質問","question":"私からは８４ページの１３款、それから１４款にもかかわってきますが、国庫支出金、都支出金の中の特に民生費に関することでお聞きしたいと思います。それから６８ページの公園占用料というんでしょうか、それから６０ページの使用料について、お尋ねします。その見通しのもとで、今回の予算が立てられていると思いますけれども、それについてのお考えをお聞きしたいと思います。","respondent":"小林保育課長","answer":"なお歳入につきまして、若干この補助金制度に影響するところで大きくかかわりますのは、保育に関しましては、認証保育所や延長夜間保育等の経費補助金分について、財調へ参入が予定されている件と考えております。","voiceIndex":275,"id":"exchange-119"},{"speaker":"西本委員","kind":"質問","question":"そうすると、品川区の考え方によっては、財源の使い方というのが変わってくるかと思いますけれども、今後、品川区の政策の中で、その補助金等々の絡みの中で、どういうふうにそれを使っていこうと、用いていこうというふうに考えているんでしょうか。","respondent":"日下部企画財政課長","answer":"今、ご質問にもございました、冒頭の都の補助金の関係でご説明させていただきました。","voiceIndex":277,"id":"exchange-120"},{"speaker":"西本委員","kind":"確認","question":"そうすると、平成１８年度とあまり品川区としての使い方は変わらないというところですが、今年始まる中で、２つほど確認したいんですけれども、中学校３年生までの医療費無料化ということですが、これはほとんどのところが始めたということもあって、補助的なところ、補助金という形ではどれだけ来るものなんだろうかという見通し。","respondent":"諸岡児童課長、日下部企画財政課長、高橋幼保一元担当課長","answer":"区のほうでは一般財源で７,０００万円、合わせて約８,０００万円ということで、今年度につきましては中学生分を予定しています。ちょっと補足しますと、今、先ほどのご質問にご答弁申し上げましたように、当初は東京都の補助金がそのまま生きるという前提で考えておりましたけれども。お尋ねの認定子ども園についてですけれども、今回、認定子ども園、公立保育園での認定子ども園というところで。","voiceIndex":279,"id":"exchange-121"},{"speaker":"西本委員","kind":"質問","question":"それと子どもすこやか医療費の件については、まず一般財源化ですると、これは考え方によっては、所得制限とか、いろいろそういうものに関しては、品川区の持ち出しで今後もやっていくよということの見通しで、それがまた一般財源化で全部補助されるということの見通しはまだついていないということの理解でよろしいでしょうか。","respondent":"日下部企画財政課長","answer":"今までの都の補助の対象自体、就学前で、しかも所得制限がかかっておりました。そういう制限がかかっていたものについて、区としては対象も広げ、なおかつ所得制限もなしということで、平成１７年１月から拡大してやってまいりました。","voiceIndex":283,"id":"exchange-122"},{"speaker":"西本委員","kind":"質問・要望","question":"ですから、品川区の持ち出しがあるということですよね。次、１２２ページの各種保育料ですが、延長保育、一時保育、休日保育、年末保育、預かり保育と、あとオアシスルームの件ですけれども、この利用率がどうなっているのかという動向を教えていただきたいと思います。","respondent":"小林保育課長、高橋幼保一元担当課長","answer":"休日、年末保育につきましては曜日の設定等の影響かと思われますが、１割程度の減少傾向が見られます。公立幼稚園の場合の預かり保育は平成１８年度に始まったばかりで、まだその傾向等は出ていませんけれども、平成１８年度の実績から見ますと、平成１９年度については若干公立の場合は増えてくる。","voiceIndex":285,"id":"exchange-123"},{"speaker":"西本委員","kind":"質問","question":"生活支援型一時保育というのは、オアシスルームの件だと思うんですが、オアシスルームはいかがでしょうか。","respondent":"小林保育課長","answer":"オアシスルームの利用ですけれども、生活支援型一時保育、現在のところ、１２月までで２万８,６１０ということで、対前年に比べますと、１割ほどの減にはなっておりますが、下期の動向によっては、同様の水準に至るかと考えております。","voiceIndex":288,"id":"exchange-124"},{"speaker":"西本委員","kind":"質問","question":"やはりここは働くのか、やはり子どもを見るのは一義的には親、保護者の方というのがありますので、そこの指導というのがかなりきちんとされてきているのかどうか、その影響で横ばい、むしろ若干下がっていると考えていいものなのか、いかがでしょうか。","respondent":"小林保育課長","answer":"延長・夜間の利用動向なんですけれども、継続して必要な場合だけ、できるだけお使いいただいて、あとはご家庭でご両親と一緒に過ごしていただくのが子どもにとって一番いいのではないかということで、就業の実態に応じて。","voiceIndex":290,"id":"exchange-125"},{"speaker":"西本委員","kind":"質問・要望","question":"預けられるから、預けるということではなくて、子育てというものがどういうものであるのかをきちんと押さえた上で、利用していただきたいと思っています。今後とも引き続き、各保育園の先生方によろしくお願いしたいと思います。次に６８ページの公園占用料、この中のロケーション・写真撮影等と書いてあるんですが、これはどういう使い方をすると幾らぐらいと決まっているんでしょうか。","respondent":"松代管理工事課長","answer":"公園占用料のロケーションですけれども、これは１カ所あたりの占用料が決まっておりまして、９,７２０円ほどいただいております。","voiceIndex":292,"id":"exchange-126"},{"speaker":"西本委員","kind":"質問","question":"これは例えば貸してくださいと言ったときに貸してあげるということなのか、それとも品川区が積極的に貸しますよと言っているのか、その辺はいかがですか。","respondent":"松代管理工事課長","answer":"あくまでも占用を目的にしておりませんので、申請があった場合、利用者等の支障がないという範疇で使用を許可しているというものです。","voiceIndex":294,"id":"exchange-127"},{"speaker":"西本委員","kind":"質問","question":"ちょっとずれるかもしれないんですが、品川区のいいところを宣伝するには、こういうのを使えないかなと思っているんですね。ある番組で、商店街の宣伝、テレビ放映をされたときに、非常にお客が来られたということで、その後、イトーヨーカドーのほうで区商連の方が物産展みたいなものをしたんですが、非常にたくさんの方が来られたんですね。答えられるかちょっとわからないんですけど、いかがでしょうか。","respondent":"松代管理工事課長","answer":"民間のそういったいろいろな発案をいろいろなところで活用していくと、多様な手法を入れながらやっていくということも考えております。そういった中に今、委員からおっしゃられた点も十分検討の課題にさせていただきたいと思います。","voiceIndex":296,"id":"exchange-128"},{"speaker":"西本委員","kind":"質問・要望","question":"次に６０ページの使用料の中で、これはこれからの歳出のところも今後始まっていきますので、考え方を教えていただきたいんですが、総合体育館、それからきゅりあん等々の指定管理者制度をとったところですが、歳入のところには、使用料とかが一切入っていないんですね。","respondent":"堀越行財政改革担当課長","answer":"今、指定管理の利用料の歳入のお尋ねですけれども、例えばきゅりあんの場合ですと、指定管理の運営委託ということで、歳出のほうで載せていただいております。利用料金の収入見込みというのも括弧書きで加えします。","voiceIndex":298,"id":"exchange-129"},{"speaker":"西本委員","kind":"質問","question":"では歳出のところで、歳入も含めて議論するという、報告をいただけるという理解でよろしいんでしょうか。というのは歳入がどういう、要は利用料がどれぐらいあって、歳出がどのぐらいあって、それで品川区としてどういう歳出をしているのかという流れになるかと思いますが、その詳しい流れ、トータル的な説明をいただけるものなのかをよろしくお願いします。","respondent":"堀越行財政改革担当課長","answer":"今、すべての歳入のほうの説明ということでしたが、歳出のほうで一応の利用料収入についても括弧書きで載せていただいて、そのほか、その中でまた説明をするという考え方です。","voiceIndex":300,"id":"exchange-130"},{"speaker":"西本委員","kind":"意見","question":"ぜひ、これから歳出のところで幾つか指定管理者制度を使って予算を立てているというところがありますので、できる限り、詳細について、歳入のところも含めて、今後ご説明いただけますよう、お願いをして終わりたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":302,"id":"exchange-131"},{"speaker":"松澤委員","kind":"質問・要望","question":"私からは３点、８０ページの建築確認手数料、９４ページの国庫委託金に関連して１つと、これは新聞記事なんですけれども、東京都が平成２０年から個人都民税を低額所得者に対して、全額免除する方針を決めたということに関してと、３点目は１０３ページの都市計画道路整備費、土木費補助金ですけれども、１６３号線整備に関連してお聞きしたいと思います。","respondent":"福田まちづくり事業部長","answer":"そうすると、あとは法律を変えていただく。このように思っております。それで、ご発言にもありましたが、附帯決議を挙げていただきましたので、この附帯決議を懐に入れて、しっかりと物を申していきたいと考えています。","voiceIndex":304,"id":"exchange-132"},{"speaker":"松澤委員","kind":"質問・要望","question":"私たちもしっかり応援していきたいと思います。ところで、国庫委託金の件なんですけれども、昨年の同じ委員会で、我が党の石田委員が質問しました。国勢調査に関して、人件費がついていないよ。そのときに、これは地方財政法の中ではしっかりと人件費についても当然国が見込んでいると明記されているというお話がありました。この１年間、どのような話し合いをしたのか、お答えいただきたいと思います。","respondent":"日下部企画財政課長","answer":"平成１９年度の要望につきましても、今現在調整中でありますけれども、この超過負担の解消ということも１つの大きな課題として取り上げまして、国に対しまして、補助基準を改善し、超過負担の解消を図ることと、このような形で国勢調査に限らず、ほかにも幾つかありますので。","voiceIndex":306,"id":"exchange-133"},{"speaker":"松澤委員","kind":"質問・要望","question":"この質問はこれにて終わります。これは東京都のことだと言えばそれまでなんですけれども、これが２３区側に事前に話し合いがあったのかということと、こういう個人都民税の減税、これは品川区に影響が出てくるんだろうかどうか、東京都と品川区は違うよ、いや、そうじゃないよ、関連するんだよという意見もあると思うので、その辺、しっかりとお答えいただきたいと思います。","respondent":"太田税務課長","answer":"それから２点目の区への影響ですけれども、基本的には東京都の個人都民税の東京都分を東京都が実施をされるですので、ただ合わせ徴収、徴収については区でしていますので、電算システムとか、そういう部分での影響は出てこようかと思ってあります。","voiceIndex":308,"id":"exchange-134"},{"speaker":"松澤委員","kind":"質問・要望","question":"影響はない。違うんだということでしたけれども、やはりこういう形は突然出てきますと、やはり個人都民税があるならば、区民税も減税できないのかという議論が当然起きてきますので、その辺の対策もしっかりしていただきたいと思います。やはりこういう問題については、いろいろな協議の中で話し合いが事前になければおかしいと思うので、その辺についてちょっと述べていただけますでしょうか。","respondent":"日下部企画財政課長","answer":"財調協議も含めまして、都と区がお互い信頼し合うということを前提にしまして、いろいろ協議を進めていく、必要なものについてしっかりした対応策をともに進めていくということが、まず大都市東京の全体の運営にとっても非常に重要なことだと。","voiceIndex":310,"id":"exchange-135"},{"speaker":"松澤委員","kind":"質問・要望","question":"３点目の補助１６３号線整備の問題ですけれども、土木費補助金で１億５,４８０万円出ておりますけれども、今年度の事業、このお金を使って、どのような事業をなされるのかについてお伺いしたいと思います。","respondent":"浜脇街路事業担当課長","answer":"もう一方、庁舎のほうの部分が一部、こちらの百反坂のほうに行く途中の新しいほうを今後考える際に、庁舎のほうが一部当たりますので、その辺の庁舎の当たる影響について調査をするといったことを考えておりまして、この補助金の中には用地費だけが入っているという状況です。","voiceIndex":312,"id":"exchange-136"},{"speaker":"松澤委員","kind":"質問","question":"正直言って、これはたしか平成１７年度まで４年間で終わる予定になっていたんじゃないですかね。それが平成１８、平成１９年度、恐らくこの１億５,４８０万円で終わらないんでしょう。並行して工事をされるのかどうか、光学通りのほうは信号までずっとあいていますので、私は早急に工事をすべきだと思うんですけれども、その辺のことについてお伺いしたいと思います。","respondent":"浜脇街路事業担当課長","answer":"私どもといたしましては、地中化の工事を始めて、平成１９年、２０年度で何とかすべての工事を終わらせたいと思って、来年度にはこの用地費の中で用地取得したいということで今考えているところです。","voiceIndex":314,"id":"exchange-137"},{"speaker":"松澤委員","kind":"質問","question":"所期の計画では、たしか平成２０年までに完成させるということでしたね。そのおくれというものはないんでしょうか。","respondent":"浜脇街路事業担当課長","answer":"２年ほど延期したことは事実ございまして、その２年の中で、私どもとすれば、与えられた事業期間の中で、あと残ったのは２年間ですけれども、平成１９年、平成２０年の中で完成したいということで、今、努力しています。","voiceIndex":316,"id":"exchange-138"},{"speaker":"松澤委員","kind":"質問・要望","question":"この１６３号線の問題は、当然ながら２６号線と絡んでいるんですね。２６号線は東京都の事業ですから、この本予算の中には入っていませんけれども、あれが３年間で完成する、当然事業年度があと３年しかないので、３年間でやるだろうというように、私どもは思っているんですね。そんな意味からすると、おくれる可能性もあるのかなと、非常に気にしているんです。その決意のほどを聞きたいと思います。","respondent":"浜脇街路事業担当課長","answer":"再三になりますけれども、だとすれば、残りが平成２０年度中ですので、２年間ですので、用地買収、それから工事といたしましても、今お話ししましたように、できるところから話をつけながら、細切れにしてでも工事をやって、何とか平成２０年度に完成したいと考えておりますので。","voiceIndex":318,"id":"exchange-139"},{"speaker":"土井委員","kind":"質問・要望","question":"さらに時間があれば、全体的なことでちょっとお伺いする場合もありますので、金利関係ですから。特別交付金というお話で。そしてそのうちの２％だったものが５％に上がると。これは４情報しか入っていないんだ。そうすると、そういう見通しから言って、本来出すべきものをやっぱり今年出しておかなければいけないのではないかという可能性もあるんですが、その辺はどのようにお考えなんでしょうか。","respondent":"日下部企画財政課長、金子産業振興課長、上川内戸籍住民課長","answer":"つまり、区としては特別交付金は基本的には１件算定で対応といいますか。株式会社につきましては、近隣セキュリティシステムの保守管理をしているところを入居させておりますので、それからＮＰＯにつきましては。それから住基カードの主な目的なんですが、やはり一番今、銀行等、それから行政証明等もどこでも本人確認が厳しくやられておりますので。","voiceIndex":321,"id":"exchange-140"},{"speaker":"土井委員","kind":"質問・要望","question":"特別交付金の場合は、今度のときはたしか三位一体改革で不交付団体である千代田区などに対する対応もこの中でやるんだよということになったから、５％に増えたんだというようなお話は伺っておりまして、大分わかっているつもりなんですけれども、いわゆる特別交付金が本当に一見、予算査定的な査定なものですから、ちょっとそこら辺が私もどう考えたらいいのかなと思って。","respondent":"小野情報システム課長、日下部企画財政課長","answer":"ただ、これを実際今後品川区でどういうふうに活用していくかという問題については、国のほうでは公的個人認証を使った電子申請が非常に伸びるのではないかと考えていたところ、パスポートの問題が端的に示しておりますように。年間で行けば２０年ですから、６,０００万円ということで、非常にばかになりません。ですから、そういう金利の動向は、これから、とりわけ十分注視をしながらその辺の判断というのはしっかりしていかなければいけないと考えています。","voiceIndex":325,"id":"exchange-141"},{"speaker":"石田委員","kind":"提案","question":"私からは国庫補助金と、都の補助金をやらせていただきたいと思います。ページは８８ページと９８ページ、全体のことを最初にお伺いしたいと思っています。先に全体のことを１つ伺います。本予算が出されて、もちろん区民サービスの向上を考えて、政策提案をされてきていると思いますが、以前、高橋前区長は補助金をしっかりと取れる考え方、それから方法を模索していくんだと。","respondent":"日下部企画財政課長","answer":"これにつきましては、平成１９年度予算を編成するに当たりまして、濱野区長が就任されました。その直後に全体部課長会を開催いたしまして、ここで基本的な平成１９年度の予算編成に向けての基本方針についても、依命通達という形で、全体に徹底を図ったと。","voiceIndex":329,"id":"exchange-142"},{"speaker":"石田委員","kind":"提案","question":"９０ページの国庫補助金ですね。木造住宅耐震診断補助金というのがあります。この４点をちょっと聞きたいわけですけれども、これは国・都の補助金のメニューがもともとあって、それを利用してここへ、その事業を行おうとしているのか、逆に品川区から提案をして、この補助金を取りに行って、それでこういうことをやるんだといって事業を行っているものなのか、ここら辺をお聞かせ願いたいと思います。","respondent":"片田建築課長","answer":"端的に言いますと、国および東京都が国については、住宅建築物に関する補助金という制度を立ち上げてまいりました。これらの制度を十分活用しつつ、区としても耐震診断および支援をしていきたいといったような考え方に立つものです。","voiceIndex":331,"id":"exchange-143"},{"speaker":"石田委員","kind":"提案","question":"今言った４点はもともと国が住宅建築物の制度とか、いろいろいいけれども、制度があったものを活用して、利用して、我々がこういう事業をやろうと、今後出てきているものなのか、こちらからその制度があったけれども、もっと変えて、こういうことだと提案をして、こうしたくて、それで提案をして取りに行って、取ってきて、この事業をやっているのかと、この４点をそうだとか違うとか、それだけでいいので。","respondent":"片田建築課長","answer":"大変失礼しました。基本的には国がつくった制度を十分活用するという考え方に立ち、こちらから要望したものではなくて、十分現行の制度を活用していきたいという考え方に立つものです。","voiceIndex":333,"id":"exchange-144"},{"speaker":"石田委員","kind":"提案","question":"それを提案をして、こういうところの補助金がつかないかとか、そういう模索をしていくことも１つの考え方だと思うのね。幾らかかったと。見方によっては百何十兆から、多い方は３００兆ぐらいまである。ここら辺の政策的な考え方、こういうことを一つの検証をして、それからおりていって、こういう考え方をするんだということが、そういう考えをお持ちなのかどうかということをもう１度お聞きしたい。","respondent":"片田建築課長","answer":"ただ、今、この制度、いろいろな角度からの支援策というものは考えられると思いますので、引き続き東京都のほう、２３区も含めて、そんな提案をしてみたいということも考えてあります。","voiceIndex":335,"id":"exchange-145"},{"speaker":"石田委員","kind":"提案","question":"これは非常に大きい話なので、大変かなと思います。制度を活用しているんだと。逆に今、品川区からこれぐらいのレベルでもいい、レベルと言うと大変失礼だけど、こういう形のものを提案して、東京都の補助金を取ってこよう、また国の補助金を取ってこよう。今、この耐震関係でやれそうだと思われているものが、これなら補助金を取ってこれそうだというのは、課長の中で何か思いがあるなら聞かせてほしい。","respondent":"片田建築課長","answer":"そういう意味では来年度、促進計画を区としても策定していく中で、幾つかのメニューを含めて、施策について、あわせて検討していきたいと。なおかつ、それについてはできるだけ早い時期に実施していきたいという考え方です。","voiceIndex":337,"id":"exchange-146"},{"speaker":"石田委員","kind":"提案","question":"お願いだけしておきます。そういう意味では、ぜひ我々もいろいろなことを、私らも勉強会にも行ったりいろいろして、いろいろな意見を提案しますので、ぜひそういう意味で品川区から発信して、そういう耐震関係は取っていかないと、これは多分本当に進まない話だと思うので、ぜひぜひよろしくお願いして、終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":339,"id":"exchange-147"},{"speaker":"堺委員","kind":"質問・要望","question":"最初に、区民住宅使用料１６億円に関連してですが、これは区民住宅に入居されている方、あるいは区民住宅の自治会があろうかと思いますが、そういう方々からの要望といいましょうか、そういったものについては指定管理者制度の導入に伴って、宅建協会のほうに最初には相談に乗っていただくということになるのかなとは思うんですが、その辺の仕組みをまず１つ、確認をしておきたいと思います。","respondent":"齋藤住宅課長","answer":"指定管理者は今、３社ありますが、通常の日常の生活にかかわるものにつきましては指定管理者が請けてあります。その他さまざまな要望がありますので、一定のものについては自治会の方と私が直接お話をすることもあります。","voiceIndex":341,"id":"exchange-148"},{"speaker":"堺委員","kind":"質問・要望","question":"そうすると、改善というか、要望の中身によっては、指定管理者制度に行く場合もあるし、直接区のほうに来る場合があるということですね。そうしますと最近、区のほう、あるいは宅建協会でもいい、両方どういう要望が来ているのかどうか、教えていただけますか。","respondent":"齋藤住宅課長","answer":"不法投棄があるといった要望がございましたり、ファミーユ西五反田の方からは、もちつき大会やフリーマーケットを開催したい。ついてはさくら会や都の用地も借りたいので調整してくれないかというような要望がございまして、私どものほうで対応しております。","voiceIndex":343,"id":"exchange-149"},{"speaker":"堺委員","kind":"質問・要望","question":"今、ファミーユ下神明の具体的な要望が寄せられた中身について教えていただきましたが、これは私どもも昨年の７月１３日の段階で、自治会の方からそういう要望がございまして、実は担当の課長にお会いしていただきました。今回の予算の中で計上されて、設置という方向になっているのかどうか、その辺ちょっと確認させていただけますか。","respondent":"齋藤住宅課長","answer":"ファミーユ下神明には４機、その他の区民住宅ではファミーユ西五反田しか防犯カメラは設置してございませんでしたが、そういった文書の要望や、自治会あるいは借り上げた区民住宅のオーナーの方からの要望もお聞きいたしまして。","voiceIndex":345,"id":"exchange-150"},{"speaker":"堺委員","kind":"意見","question":"区民住宅に入居されている方々の安心・安全といいましょうか、そういうことについてもやっぱりこちらがきちっと対応していかなければいけないのではないかと思うんですね。いかがでございましょうか。","respondent":"齋藤住宅課長","answer":"ファミーユ西五反田の自治会長とはメールでやりとりするなど、こんな形できめ細かく自治会のコミュニティということをつくるために、大変自治会長が努力されておりますので、積極的にお話を聞きながら、よりよい住宅、安心・安全に向けて整備をしてまいりたいと思います。","voiceIndex":347,"id":"exchange-151"},{"speaker":"堺委員","kind":"質問","question":"２点目は学校施設使用料に関連して、今回、６,２７３万３,０００円ですか、計上されておりますが、説明の中でも、学校の温水プールの使用料の増というのが見込まれているというご説明をいただいたんですが、ほかにも教室とか、あるいは屋内運動場等の使用料も計上されておりますが、主に教室とか屋内運動場についてはどのような種目というんですか、内容というんですか。","respondent":"富田生涯学習課長","answer":"屋内運動場というのは体育館ですが、主に平日の夜間ですとか、あるいはその他小学校につきましては土曜、日曜の日中も若干入ってまいりますけれども、１７地区のスポーツ・レクリエーション活動推進委員会のほうでもって、各学校施設の利用調整をしていただきまして。","voiceIndex":349,"id":"exchange-152"},{"speaker":"堺委員","kind":"質問","question":"最近、シルバー世代を含めた方々のダンスが、大変多くなってきているようですが、シルバーセンターとか文化センター等でも、シルバーダンスというんでしょうか、ダンスを利用している方々も大変多いんですが、今、おっしゃっておられたような学校等を利用されているサークル、グループはありますか。","respondent":"富田生涯学習課長","answer":"学校体育館を使っては、わりとシルバー世代で、ヨガですとか太極拳ですとか、そういった利用は聞いておりますが、シルバーダンスについてはまだ申し訳ございません、ちょっと承知しておりません。","voiceIndex":351,"id":"exchange-153"},{"speaker":"堺委員","kind":"質問・要望","question":"学校等はあまりそういう関係者が使っていないようですが、実はこういう要望があるんですけれども、大井第三地域センターを利用している、あるダンスのグループの方々が近々、近くにある原小学校、地域の活動あるいは交流拠点という形にした後、これから整備されるに当たって、体育館になるのか校舎になるのかわかりませんが、そういうところでもダンスに利用できるように。","respondent":"田村地域活動課長","answer":"お尋ねの原小学校跡地についても、防音設備等、ダンス等、活用できるような形で、今後基本設計、実施設計を進めてまいりますので、その中で検討してまいりたいと考えております。","voiceIndex":353,"id":"exchange-154"},{"speaker":"堺委員","kind":"質問","question":"それから３点目ですが、昨日も補正予算審議の中で、公共施設整備基金積立金、約９３億円の中には、約半数が国文学研究資料館跡地取得のための基金であるという回答をいただいたんですが、今日、１０３ページの中に、５目の土木費補助金の中の１節、都市計画交付金の中にも、国文学研究資料館跡地取得として、新規に１５億７,２５０万円申請されているわけですが、これについては。","respondent":"日下部企画財政課長","answer":"国文学研究資料館でありますけれども、これにつきましては、都市計画交付金の対象事業ということで、都と区の間でルール化されておりまして、その対象として、これが対象になる案件ですので、そういうことで、これから本格的な協議に入っていきますけれども。","voiceIndex":355,"id":"exchange-155"},{"speaker":"堺委員","kind":"質問","question":"いわゆる都市計画交付金の対象だからというお話ですね。じゃなくて、私がお尋ねしたのは、明確に金額が交付金として来たんですから、この金額を区のほうで申請した金額が予定どおり来たのか、あるいは交付金の対象だから、幾らかつけてくださいよという形で申請して、こういう金額になったのか、どういうことなんでしょうかということを聞いているわけです。","respondent":"日下部企画財政課長","answer":"申請は平成１９年度の対象の案件になりますので、これについては来年度に入りましてから、正式な申請の手続をとることになります。","voiceIndex":357,"id":"exchange-156"},{"speaker":"堺委員","kind":"質問","question":"そういうルールがあってということですね。今度１１２ページにあります、１７款の繰入金の中で新たに公共施設整備基金繰入金で、８１億９,０００万円計上されている。この中にも説明では国文学研究資料館跡地取得の費用が含まれているという説明がされておりましたけれども、この中にはどの程度の金額が含まれているんですか。","respondent":"日下部企画財政課長","answer":"実は私どももちょっとそういう心配をしておりますが、基本的には昨日申し上げました半額を丸々積み立てしたものを繰入金として、平成１９年度、この都市計画交付金の残り分として、財源として手当をするということで予定をしております。","voiceIndex":359,"id":"exchange-157"},{"speaker":"沢田委員","kind":"質問・要望","question":"区は区民に対し、十分に説明を尽くすとともに、区民の意見を反映するための仕組みづくりが求められていますと、パブリックコメントの問題に及んでおりますし、昨年、区長に就任した直後、私は決算特別委員会で、質問に対して区議会を初めとする、区民の声をお聞きして、政策をまとめるという、前区長はどちらかというと、スピード。","respondent":"濱野区長","answer":"要するに議会に物事をご提案する場合の手順と申しますか、これは従来どおりの手順でやってまいりますし、ものによっては、議案説明会の中での説明に若干の詳しい事柄を付与するということでやってまいりたいと思っていますので、その辺。","voiceIndex":362,"id":"exchange-158"},{"speaker":"沢田委員","kind":"質問・要望","question":"特段に変わった方向でお願いしたいと思いますけれども、ちょっとここで一例を、まだ区長が変わったばかりですから、これがすべてだという思いで言うんじゃなくて、この点を改めたほうがいいんじゃないかという立場で提起させていただきたいんですが、今度の荏原西地区の小中一貫校の母体校に荏原第二中学校を加える。２月６日にＰＴＡの役員に説明をして、所管委員会は２６日にならないと聞けなかった。","respondent":"古里学務課長","answer":"この件につきましては２月９日、１０日に新入学生徒の入学説明会が予定されておりました。","voiceIndex":364,"id":"exchange-159"},{"speaker":"沢田委員","kind":"質問・要望","question":"ごめんなさい、ここでやっているのは歳出のものではなくて、手順でどう決めたかということに限って聞かせてもらっています。いつ、品川区教育委員会として決定をしたのかということがわからないんです。一体、所管委員会って何なのか。教育委員会にいつかけて、それを承認したのかということを、事務局での決定と、教育委員会での区教育委員会の決定、その日程を教えていただきたいと思います。","respondent":"古里学務課長","answer":"先ほどから申し上げているとおり、地域でのいろいろな建設に当たっての説明の中、それから従来から、この地域で出ていた区民の方々のさまざまなご意見を考慮し、教育委員会として、今年度の予算編成の中で。","voiceIndex":366,"id":"exchange-160"},{"speaker":"沢田委員","kind":"意見","question":"どこの時点が区としての決定か。予算はわかりましたよ。だけど、荏原第二中学校を入れるということ、母体校にするというのを決めた最終的なのはいつなのか。私が聞いているのでは、傍聴した方から教育委員会は１３日に決定したと。だけど実態的にはもう現地で説明会に入っている。「あれ」と思ったんです。教育委員会って何なんだ。なぜこんな手順の違いが出てきたのかと聞いているんです。","respondent":"古里学務課長","answer":"先ほど申し上げたとおり、２月１３日の教育委員会で、ご報告を申し上げ、確認したところですけれども、これらの情報につきましては、昨年来の経過の中では、教育委員会に状況の説明は適宜行ってきてあります。","voiceIndex":368,"id":"exchange-161"},{"speaker":"沢田委員","kind":"提案","question":"だから私はこれ、期待を持っているわけです。次の問題は、これまで何度も取り上げてきたんですが、行政をチェックし、区民の要望を行政が取り上げなければ、条例提案だとか予算修正案で区民の声を直接議会が行政のほうに反映をする。指定管理者のときに、いろいろな資料を議会に提出して、十分安全な審議を経て指定管理者をやろうというのは、議会側の要望ですよね。","respondent":"堀越行財政改革担当課長","answer":"指定管理の部分でお答えをしますと、議会に対してはその都度議決をいただく際にその審議に資するような資料をお出しさせていただいて、議決をいただいていると考えております。","voiceIndex":370,"id":"exchange-162"},{"speaker":"沢田委員","kind":"意見","question":"私は具体的に聞いたんですよ。指定管理にこの仕事をお願いするときに、相手先が常勤が何人で、非常勤が何人ということは、最低限契約時に詰めている話でなければ、危なっかしくて、任せられないじゃないか。それが不存在だというふうに出たんです。これがうそなのか、実際にそういう資料が不存在なのかということを聞いているわけです。","respondent":"木下福祉高齢事業部長","answer":"当時、まだ指定管理の体制に入っていなかったかと思いますけれども、私どもといたしましては、個々の各法人の職員の体制、常勤・非常勤という部分については、細かい数字の部分では把握して、当時数字としては持っていなかったということで。","voiceIndex":372,"id":"exchange-163"},{"speaker":"沢田委員","kind":"質問・要望","question":"今後、指定管理者の制度に入っていくので、非常に神経をとがらせて、鈴木ひろ子委員は質問したわけです。今後要望したいと思いますけれども、こういうのをつまびらかに出していただきたい。どういう職員体制で仕事がやられるかということは、非常に大事だと。それからもう１つ、今度私はワーキングプアに均等待遇の原則をということで、今度の議会で質問させていただきました。私、これは改めてほしい。","respondent":"堀越行財政改革担当課長、中川原広報広聴課長","answer":"平成１９年度以降、そのガイドラインに沿いまして、施設の特性に応じて適切に管理をしていくということで、議会の報告については適宜、必要に応じてご報告をさせていただきたいと考えております。情報公開制度の公開・非公開の運用についてですが、個人情報保護という観点から、個人が特定するものについては、公開できないということで運営しております。","voiceIndex":374,"id":"exchange-164"},{"speaker":"沢田委員","kind":"質問・要望","question":"議会と行政の側が緊張感を持って、それで区民の立場でお互いに論じ合う。たまたま私ども、野党ですから、下手を出しちゃうと追及されて、墓穴を掘るという気持ちがわからないじゃないですけど、それは違う。民主政治じゃないと思います。ぜひ今日、私が指摘した点については、改善できる点は早急に改善してもらうということの検討をしてもらうことを要請いたしまして、私の質問を終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":377,"id":"exchange-165"},{"speaker":"須藤委員","kind":"質問","question":"４６ページの特別区たばこ税、それから８４ページの国庫負担金、１１８ページの競馬組合、１２０ページ、雑入、その他時間があれば５２ページの特別交付金等々について。４６ページ、たばこ税について質問できる、数少ない議員の１人として質問します。来年度、５,０００万円増額してありますけれども、このプラスした考え方というのは何でしょうか。","respondent":"太田税務課長","answer":"考え方といたしましては、昨年の７月１日にたばこ税の改定がございました。そうしますと、４、５、６の３カ月分が平成１９年度増えますので、平成１８年度は９カ月でしたけれども、平成１９年度は１２カ月分になると。この部分を加味して、増額させていただいたものです。","voiceIndex":379,"id":"exchange-166"},{"speaker":"須藤委員","kind":"質問","question":"これは全部当てなさいということじゃなくて、何割か当てれば相当な金額になってくるわけなので、そういったたばこ税自体が品川区でこういうところに使われていますよというのが見えるような考え方の使い方というのか、そういうことをお考えになることはできないでしょうか。そういったものを底上げするような、何かたばこ税でこうやっていますよというのが見えるような使い方はできないでしょうか。","respondent":"日下部企画財政課長","answer":"具体的な事例を出されましたけれども、例えばたばこのポイ捨てのいろいろな普及・啓発のほうに活用するとか、それはおっしゃるようなご趣旨はわかりますので、その辺、使途の特定はできないまでも、そういう区民向けのＰＲの中で、どういうことが可能なのか。","voiceIndex":381,"id":"exchange-167"},{"speaker":"須藤委員","kind":"質問","question":"もう１つ、公共の喫煙の場所がだんだん狭くなってきているので、そのあたりも一生懸命税金を払っている人たちの処遇というのが逆に肩身の狭いようなところでたばこを吸うような状況になっているように思うんだけれども、ソファーを用意しろとかは言いませんけれども、少し目隠しをして、外から見にくいよとか、おりに入っているようなところでたばこを吸わされているので、何かもう少し工夫がないかなと。","respondent":"中島経理課長","answer":"庁舎におきます喫煙室につきましては、それぞれ工夫しながら、喫煙者のこと、あるいはたばこを吸わない方のことも含めて、バランスをとりながら、現在設置しています。","voiceIndex":383,"id":"exchange-168"},{"speaker":"須藤委員","kind":"質問","question":"それから国庫負担金、都負担金に関連するんだろうと思うんだけれども、予算のほうに載っているんですが、後期高齢者の医療制度の準備費というのが、この間、厚生委員会で１８億円ぐらい準備費がかかりますよという話だけど、この入りでは何もそこに見当たるものがないんだけれども、先ほど来、いろいろな国の施策がおりてきてどうのというようなときに、そういうものの国のほうから補助みたいなのは。","respondent":"冨岡高齢事業課長","answer":"これにつきましては、国からなかなか明示がございませんで、１月の半ば過ぎ、２０日ぐらいにやっと全国で２３７億円の補助金が出るというような示しがございまして、今のところ、これは平成１８年度も含めてなのですが、区としては平成１８年度の歳出を組んでおりませんので。","voiceIndex":385,"id":"exchange-169"},{"speaker":"須藤委員","kind":"質問・要望","question":"それから１１８ページの競馬組合の配分金ですけれども、年々あれが少なくなっているので、４億円を切ってきましたという数字になってきましたけれども、このこともどんどん分配金が少なくなりますよという場合に、いかに考えておくかなと。そういったときに、この分配金自体が各区に対してどの程度まで少なくなってきたときには、危険水域だよというような考え方をしているのか、そのあたりを教えてください。","respondent":"桑村総務課長","answer":"平成１９年度の予算をどういうふうに考えているかといいますと、競馬組合のほうでは、ここで下げどまったので、売得金額とすれば、これまでと同様の金額ぐらいできるだろうと考えているところです。","voiceIndex":387,"id":"exchange-170"},{"speaker":"須藤委員","kind":"意見","question":"１２１ページの雑入の中で、私用光熱水費で特別養護老人ホームほかの電気、ガス、水道料となっておりますけれども、このあたりはどういう考え方でとってくればいいのかなと。そこの私用というのはどういう、特別養護老人ホームで私用であるというのはどういうことかなと思うんですが。","respondent":"蓼沼高齢福祉課長","answer":"ここに計上しております私用光熱水費、特別養護老人ホームほかですけれども、これにつきましては荏原の複合施設、特別養護老人ホームとそれから保健所の複合施設になっておりますけれども、これにつきまして、保健所のほうが大家ということになっておりますので。","voiceIndex":389,"id":"exchange-171"},{"speaker":"須藤委員","kind":"質問","question":"そうすると、荏原の特別養護老人ホームの部分がここに入っていますよという形になる。そうすると、ほかの特別養護老人ホームは全然関係ないよという話になる。ほかにどこかに入れているところがあるんですか。","respondent":"蓼沼高齢福祉課長","answer":"基本的にその施設で、特別養護老人ホームで要した光熱水費の経費については、それぞれの施設でお支払いいただくということになっております。","voiceIndex":391,"id":"exchange-172"},{"speaker":"須藤委員","kind":"質問・要望","question":"先ほど来、ずっと聞いていると、品川区では２０億円ぐらいのマイナス要因があるよというようなお話を伺うんですけれども、その２０億円というのも何年間かかけての２０億円になる。住民税はある程度、逆に何年間かかけて、やはり４０億円ぐらいのプラスになってきている。そうすると、終局的にはその影響というのが逆になってくるのかなという思いがあるんだけれども、そのあたりはどうでしょうか。","respondent":"日下部企画財政課長","answer":"税源移譲に伴うマイナス約１億６,０００万円程度で見込んでおりますが、これは平成１９年度からフラット化になりますので、そこで発生した２億円ということで、合わせて約２０億円と。","voiceIndex":393,"id":"exchange-173"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=876#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":119589,"voices":395}},{"id":"h19-20070308-3","meetingId":"h19-c-budget","date":"2007年3月8日","dateIso":"2007-03-08","committee":"予算特別委員会","time":"午前１０時０３分～午後６時０３分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を168件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"○午前１０時０３分開会 ただいまより、予算特別委員会を開会いたします。 それでは、第５号議案、平成１９年度品川区一般会計予算","agenda":"○午前１０時０３分開会 ただいまより、予算特別委員会を開会いたします。 それでは、第５号議案、平成１９年度品川区一般会計予算","exchanges":[{"speaker":"原（浩）委員","kind":"質問・要望","question":"事業概要といたしまして、５項目の内訳がありますが、これの数字割合がおおむね把握されているようであれば、そこをお教えいただきたいということと、それから、まだ国際法自体が世界的に共通の認識に立って全体が流れてきているわけではありませんので、確立されていないということもありますので、そこも踏まえて次の質問をします。初めの２点、お願いできればと思います。","respondent":"桑村総務課長","answer":"国際友好協会のほうの職員数です。常勤の職員が７名、非常勤の職員が１名、それから、予算の中には、臨時職員の給与も３名分も入ってあります。これは、そのたびごとに執行するということになろうかと思います。","voiceIndex":4,"id":"exchange-001"},{"speaker":"原（浩）委員","kind":"質問","question":"この辺につきまして、これは補助金が出ているんですけれども、また新しい教室の生徒さんというんですか、その辺のところからも学費等、授業料と言っていいのかどうかわかりませんけれども、これが、日本語、英語、時にはイタリア語があるのかわかりませんけれども、それから、外国関係、花をやっていたり、いろいろあるんですけれども、この辺の、年間でもいいですし、月でも結構なんですけれども。","respondent":"桑村総務課長","answer":"生け花教室につきましては、１万４,０００円。料理教室につきましては、そのたびにちょっと違いますけれども、基本的に大体１,０００円程度というものを組んでいるものです。","voiceIndex":6,"id":"exchange-002"},{"speaker":"原（浩）委員","kind":"意見","question":"ご丁寧に説明していただいたんですけど、そこの数字はわかったんですけれども、おおむね区として、数字的にどうかというのは、高いか安いかというのは一概に決められないんですけど、私も２度ほど見学者として参加させていただいておるんですけれども、その辺をちょっともう少し詳しくお教えいただければと思います。","respondent":"桑村総務課長","answer":"そういう意味で、いわゆるカルチャースクールの経費との比較ということで考えれば、３分の１から４分の１ぐらいの経費というふうに一般的にとらえておりますが、教室の制度とか、いろいろあろうかと思いますけれども。","voiceIndex":8,"id":"exchange-003"},{"speaker":"原（浩）委員","kind":"質問","question":"私もそう感じました。２度ほど出て、わきあいあいと楽しそうに、いろんな国の方自体が、交流もされていますし、教室的には、そういう形で、やはり楽しく参加していただくというのが一番、交流という意味では非常に大事なことだと思いますので、その辺は私もそう思っております。次に、ホストファミリーについて、もう１点お聞きしてまいりたいと思います。","respondent":"桑村総務課長","answer":"あるいは、私どものほうがポートランド等に行ったときに、向こうのホストとの関係というのが一番大きな、気持ちとして交流につながっていくんだと思っていますので、ぜひ多くの方に参加していただこうと思ってあります。","voiceIndex":10,"id":"exchange-004"},{"speaker":"原（浩）委員","kind":"意見","question":"この辺のホストファミリーに対する、区、もしくは国際友好協会のほうからのケア、例えば感謝状ですとか、その辺というのは、具体的な形でどういうふうになっているのか、お教えいただければと思います。","respondent":"桑村総務課長","answer":"そういう意味で、集まっていただきまして、まず説明会等でしていただきまして、その後滞在をやっていただくわけですが、その他、いわゆる最後にさよならパーティーみたいなことで、交流会みたいなのをやらせていただいています。","voiceIndex":12,"id":"exchange-005"},{"speaker":"原（浩）委員","kind":"質問","question":"そうしますと、全体的なところとしては、ボランティアが基本というところとして理解します。財団法人ですから、社団法人と違いますので、先ほど申し上げたように、国際法のもとでのいろんな手かせ足かせが出てこようかと思いますけれども、基本的なところとしては、区としての考え方をプラスアルファということで、財団等の連係プレーをとっていただいて、一層の親善拡大をしていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-006"},{"speaker":"安藤委員","kind":"質問・要望","question":"私自身、学生時代は奨学金を、当時の育英会、これは２００４年に廃止になりまして、独立行政法人日本学生支援機構に変わりましたけれども、当時の育英会が行っていた奨学金を受けまして、それを全部授業料に充てることができまして、何とか卒業、学ばせていただいたという経験もあるんですが、やっぱりこの奨学金をより一層充実させていくということが、国としても。","respondent":"鷹倉区民課長","answer":"奨学金の制度の発足ですけれども、奨学金貸付条例ということで、昭和６１年に制度を発足させてあります。目的です。","voiceIndex":16,"id":"exchange-007"},{"speaker":"安藤委員","kind":"質問・要望","question":"素朴な疑問なんですけれども、今、対象が高等学校、専修学校などということだったんですが、大学というのは、現在品川区の制度では、区内、他区の大学にかかわらず、区内に住む大学生の方は対象になっていないんですけれども、これは率直に言って、国の制度とかがあると思いますけれども、まだまだ不十分な点があると思いますので、日本学生支援機構の制度ともあわせて受給できるような形で。","respondent":"鷹倉区民課長","answer":"ただ、こういう奨学金の制度を運営していく場合に、それぞれの役割分担というものが当然あろうかと思います。基礎自治体としての品川区とすれば、先ほど申し上げたような形の対象のところを手厚くしてやっていくというところがまず第一かなと考えているところです。","voiceIndex":18,"id":"exchange-008"},{"speaker":"安藤委員","kind":"質問","question":"役割分担という話がありましたけれども、そういったことを飛び越えて、やはり必要とされているんじゃないかなとすごく思っているんですね。現在、品川区内で、難しいかもしれないんですが、区民で大学に進学している学生の数と、そのうちの私学の学生さんの数とか、比率ですとか、わからないですかね。もう一つ、大学はやってないんですかという問い合わせは窓口には寄せられていないんでしょうか。","respondent":"鷹倉区民課長","answer":"前段の部分の数字は、申しわけございませんが、わかりません。それから、後段の部分の問い合わせがあるかどうかということなんですけれども、私どもまず、公立の中学校とかなり連携を深めてあります。","voiceIndex":20,"id":"exchange-009"},{"speaker":"安藤委員","kind":"質問・要望","question":"完全にローン化すると私は思うんですけれども、そういった点で、今、役割分担と話しておりましたけれども、日本学生支援機構は、先ほど教育基本法にありましたような高等教育の機会均等を保障していないと私は思うんですけれども、その点で、再度、品川区に、大学生もぜひ対象にしていただきたいと思うんですけれども、いかがでしょうか。","respondent":"鷹倉区民課長","answer":"基礎自治体の品川区とすれば、高等学校など、先ほど申し上げたところで、まずがっちり勉強していただいて、力をつけて次の段階に行っていただければと思っているところです。","voiceIndex":22,"id":"exchange-010"},{"speaker":"安藤委員","kind":"質問・要望","question":"例えばこの方は心理学を志している方で、本が１冊３,０００円から６,０００円ぐらいするんですよ。せめて本の部分ですとか、あるいは交友費ですね。これはぜひ、品川区に、思い切って、最初は小さな穴でもいいですから、あけていただいて、大学生にもぜひ奨学金制度拡大ということを再度私は力強く求めたいと思うんですが、この状況に対して、こういう方もいるということも踏まえた上で、いかがでしょうか。","respondent":"鷹倉区民課長","answer":"世の中、いろいろ勉強する方、いらっしゃいますけれども、刻苦勉励だとか、そういう言葉を大事にしながら、一生懸命働きながら勉強されている方もいらっしゃいますし、そういう本当に困った方々に奨学金を出していくべきかなと私は思います。","voiceIndex":24,"id":"exchange-011"},{"speaker":"安藤委員","kind":"質問・要望","question":"今、地方公共団体でも、２００３年のデータになっちゃうんですが、全国２万５,０００人の方が地方公共団体の奨学金制度を利用しておりますので、ぜひ品川区さんにも前向きにこの制度を大学生まで拡大していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":26,"id":"exchange-012"},{"speaker":"武内委員","kind":"質問・要望","question":"近隣セキュリティシステムの運営経費のほうは、昨年の第４回定例会のほうで質問させていただきまして、その際に、地域の利用者の方、区民の方からの要望ということで、中学校への希望者の、また決して無料とかじゃなくて、有料でもいいんじゃないかと。","respondent":"金子生活安全担当課長","answer":"この問題につきましては、前回のとき、質問等ございまして、検討していますけれども、中学生への導入に関しましては、以前もお答えしたとおりですが、中学生となりますと、半ば大人の部分もあります。","voiceIndex":28,"id":"exchange-013"},{"speaker":"武内委員","kind":"提案","question":"ただ、私もそういったご答弁いただいた後に、区民のお母さん方と懇談をする機会があって、そのときにいろいろそういうご質問をしました。今、こういうことを私は何人かのお母さんから聞いて、区にも提案したけれども、今、検討中だと。皆さんどう思いますかと。例えば中学生でも希望者だったら、有料で持たせてあげるということも検討すべきじゃないかなと思うんですけれども、改めていかがでしょうか。","respondent":"河野指導課長","answer":"そういう意味でいいますと、中学校教育においては、個々の自立ということについては、かなり重い意味を持っておりますので、委員ご指摘の部分についても、先ほどの答弁のとおり、中学生の自立を促すという点では妥当な考え方ではないかなと考えます。","voiceIndex":30,"id":"exchange-014"},{"speaker":"武内委員","kind":"質問・要望","question":"東京都が１月に素案を発表しまして、パブリックコメントを求めまして、５月の予定で策定されると聞いているんですけれども、これを受けた品川区のスケジュールをもう一度確認させていただきたいのと、あと、スケジュールによると、１月から２月の間に、都民に対してのパブリックコメントと同時に、また、事業者の意見公募、さらに区市町村に対しての意見の公募もされているということなので、品川区としては。","respondent":"久保田防災課長","answer":"具体的なスケジュールについては、防災会議を開催しなくちゃならないということで、今年は２回ほど予定しております。","voiceIndex":32,"id":"exchange-015"},{"speaker":"武内委員","kind":"質問・要望","question":"１つ、前回の平成１５年の地域防災計画の改訂の中で、ブロック塀について５３ページで書かれていまして、安全化計画ということで、区民がブロック塀等を生け垣等へ改修する場合の生け垣助成だとか、さまざまなことでブロック塀については、安全化を図っていきますよという計画があるんですけれども、これは、民間の方なので、生け垣助成という形でやってくれる方はいいんですけれども、なかなか強制的には。","respondent":"宍戸施設担当課長","answer":"具体的にどのような量ということでは、今、手元に資料はございませんが、少なくとも改修等に際しましては、フェンスか、あるいは生け垣かということで、心がけてあります。","voiceIndex":34,"id":"exchange-016"},{"speaker":"武内委員","kind":"確認","question":"去年、冨士見台児童センターの隣のブロック塀がありまして、そこの裏に住んでいる方からご相談がありまして、そのブロック塀、冨士見台児童センターができる前からのもので、今は冨士見台児童センターの所有物として、人の背よりも高い、２ｍ以上ぐらいの古いブロック塀がありまして、それが万が一地震で倒れたときに非常に怖いということで、お話をいただいて、私も見させてもらったら、どう見ても。","respondent":"宍戸施設担当課長","answer":"ご趣旨につきましてはごもっともだと思いますので、至急調査した上で、適切に対応してまいりたいと考えております。","voiceIndex":36,"id":"exchange-017"},{"speaker":"武内委員","kind":"質問","question":"最後に、１５９ページの原小学校跡の件についてですけれども、原小学校跡の交流拠点整備ということで、西側の別棟のことだと思うんですが、これについてのスケジュールは、学校の本体のほうと同じで、来年の１月から６月までの工事だと聞いているんですけれども、この管理運営について、当初お聞きしているところは。","respondent":"田村地域活動課長","answer":"これから地域と具体的に説明に入って、ご推薦をいただきたいと考えております。","voiceIndex":38,"id":"exchange-018"},{"speaker":"武内委員","kind":"質問・要望","question":"ただ、それも、これからですというお話はしているんですけれども、非常に期待をされているということがありますので、これも管理運営主体が決まった段階で、区にも入っていただいて、相談をされていく中で、どういうふうに使っていくかということをコンセンサスを図っていくと思いますので、その中で、特にいろんな意見があるんですけれども、それを全部聞いてはいられないということもあるんですけど。","respondent":"田村地域活動課長","answer":"ただし、西側の建物、あるいは耐震補強工事が必要な体育館については、セキュリティー上の問題もあるので、基本的には一帯を機械警備する予定なので、やはりそれは使えない状況になるだろう。","voiceIndex":40,"id":"exchange-019"},{"speaker":"川西委員","kind":"質問・要望","question":"平成１９年度、あるいは平成１８年度まで実施したものをどう変えていくか、膨らませて、区民の要望をどういうふうに聞こうとなさっているか、伺います。それから、アドバイザー経費も、同じような考え方のもとに、これまでの実施形態とどう変わっていくのかということを伺います。同じページなので、１４９ページの民間委託経費につきましては、これは内容についてお知らせいただければ結構です。","respondent":"中川原広報広聴課長、堀越行財政改革担当課長","answer":"タウンミーティングについてのお尋ねです。今回、新しい区長のもとで２月２４日に第１回のタウンミーティングを開催いたしました。来年度につきましては、基本的には同様な形で行っていく予定ですけれども、新しい委員の方も加わっていただきまして、区政全般について。１９年度は、荏原、品川、大崎と大井地区、そういった地区ごとに開催する予定です。","voiceIndex":43,"id":"exchange-020"},{"speaker":"川西委員","kind":"質問","question":"そうしますと、人数なんですけれども、今の手法でいいとは思いますけれども、もっと大勢の方に参加をしていただく。私は前の区長のときも申し上げたけれども、区長の顔を見ながら、交流をしたいという希望もあるものですから、人数を増やすための努力はどういうふうにお考えになっていますか。","respondent":"中川原広報広聴課長","answer":"今回応募者、３０名定員のところ、２１名でしたので、全員の方に来ていただきました。傍聴者も２０名弱の方がお見えになっていますので、直接区長の考えを聞きたいという方については、会場にもよりますけれども、傍聴の枠を設けまして、対応したいと思います。","voiceIndex":47,"id":"exchange-021"},{"speaker":"川西委員","kind":"質問・要望","question":"これは要望です。１４１ページ、生活安全推進事業のことですけれども、大体説明のときに内容も伺っておりますが、この事業は今回、定員を増やされたりして、事業を進めておられるんですが、例えば登下校の安全を守るために８３運動というのを進めていらっしゃる。あるいは、防犯のために、月に何回かまちの人が回るということとの関連性についてはどのようになさっているかということを伺いたいと思います。","respondent":"金子生活安全担当課長","answer":"このほかの児童の登下校という部分につきましては、特に低学年の児童の方の下校時につきましては、それぞれ５つの警察署の管内、それぞれ担当者を決めまして、登下校に合わせた警戒、パトロールを実施しています。","voiceIndex":49,"id":"exchange-022"},{"speaker":"川西委員","kind":"質問","question":"あなたの関係しているところの人じゃないかと言われまして、これは匿名でお電話をいただいたので、８３運動についてとか、防犯パトロールについて、町会の方々にいろいろ伺いました。そういう点で、８３運動というのは、ボランティアで、ご苦労が多くて、実施１００％というのは無理かとは思いますけれども、その辺について、今後、例えば事業所に働きかけるとか、いろんな工夫はできないものでしょうか。","respondent":"富田生涯学習課長","answer":"私ども教育委員会といたしましても、それをできる限り支援したいということで、小Ｐ連が歌をつくったり、バッチをつくったり、さまざましておりますけれども、新年度につきましては、ぜひ各町会での掲示ですとか、あるいは、庁有車にステッカーを貼って、さらに浸透。","voiceIndex":51,"id":"exchange-023"},{"speaker":"川西委員","kind":"質問","question":"今の８３運動と安全推進事業の所管課との日々の関連、連絡体制はどういうふうになっているか、伺っておきたいと思います。","respondent":"田村地域活動課長","answer":"それと、お尋ねの生活安全サポート隊ですが、やはり生活安全サポート隊も、近隣セキュリティの対応等がございまして、朝７時半から夜８時までということで、２ローテーションで回っております。","voiceIndex":53,"id":"exchange-024"},{"speaker":"川西委員","kind":"質問","question":"１３３ページ、私立幼稚園関係費の中で、補助金の入園料が１０万円というふうに上がりまして、関係保護者にとっては大変ありがたいことだと思います。それで伺いますが、実際の保護者がそれぞれ幼稚園に入園を希望されて、支払っている入園料と区の補助金との差異は調査をされているのか。これと区の補助金との差はどのぐらい現況においてあるのか、お知らせください。","respondent":"高橋幼保一元担当課長","answer":"入園料のほうですけれども、入園料は、１０万円を補助することによって、保護者負担につきましては、大体３万円ぐらいの自己負担になる。１０万円ぎりぎりの園もありますけれども、大体平均すると３万円ぐらいが自己負担になるところもあるということです。","voiceIndex":55,"id":"exchange-025"},{"speaker":"川西委員","kind":"質問","question":"１３３ページに出ています１,３２０人入園料、保育料２,０４０人というのは、どういうふうに掌握したらよろしいでしょうか。","respondent":"高橋幼保一元担当課長","answer":"保育料の２,０４０人につきましては、これは私立幼稚園保護者補助費で、所得制限をまだ品川区はきちっととっていますので、その部分で、約６１.５％の方が保護者補助費を支給されるというところで、その人数が私立幼稚園におきましては、３,３００人強いますので。","voiceIndex":57,"id":"exchange-026"},{"speaker":"川西委員","kind":"意見","question":"１３１ページ、職員給与に関連してですけれども、清掃職員が都から区に完全に移りまして、都職員のときと区職員になってから、給料の差はどのように出ているのか。それから、同じページの基幹事務管理システムについても、一緒にご答弁ください。","respondent":"榎本人事課長","answer":"基幹事務管理システムについては、質問の趣旨がわからなかったので、もう１回お願いします。","voiceIndex":59,"id":"exchange-027"},{"speaker":"藤原委員","kind":"質問","question":"１３７ページの職員互助会補助金で、職員住宅資金関係費、それと１４９ページの事業部支援プロジェクトについてお伺いします。私は、歳入のときに、特別区職員互助組合からの返還金のことをお伺いさせていただきましたが、その返還金の使い道に関して、歳出のときになりますがということで、この辺の住宅のことだと思うんですけれども、返還金の使い道の説明をもう一度お願いいたします。","respondent":"榎本人事課長","answer":"今現在、職員待機寮は７寮あるんですけれども、７寮のうち、新耐震基準になっていない寮が、荏原職員待機寮だけということになりますので、そこの待機寮の改築をしていきたいというものです。","voiceIndex":63,"id":"exchange-028"},{"speaker":"藤原委員","kind":"質問","question":"ということは、２,０００万円使われるわけですよね。戻ってくるお金が１億９,６００万円ですから、まだ１億７,０００万円という大きなお金が残っていると思うんですけれども、そのお金の使い道はどのように考えているのでしょうか。","respondent":"榎本人事課長","answer":"ここに計上されているのが、平成１９年度の改築設計費の部分だけですので、実際に荏原職員待機寮全体を改築しますと、今現在の見積もりで３億４,０００万円ぐらいの総経費、設計と工事と移転等にかかる経費ということで見込んでおりますので、考え方としては、その分。","voiceIndex":65,"id":"exchange-029"},{"speaker":"藤原委員","kind":"質問","question":"これで計上しているのはわかるんですけれども、この返還金を、ここの分野にこういう形で全部使っちゃって、戻ってきたお金をこういう形で使うというのは、判断としてはよろしいんでしょうか。それと、他区もこういうふうに戻ってきていると思うんですけれども、わかる範囲でいいんですけれども、他区はどのような使い道をしているか、教えていただけますか。","respondent":"日下部企画財政課長、榎本人事課長","answer":"ただ、互助組合の返還金でありますので、職員の福利厚生に充て込むという、１つの考え方としてはあり得るということで説明をさせていただきましたが、実質的には、あくまでも色がないお金でありますので、私どもとしましては。他区の状況ですけれども、もともと特別区互助組合返還金をどういうふうに各区に返還するかというところで議論がありまして、福利厚生のために積み立てたんだけれども、各区は財政難のところもありますので、戻してほしいという中で。","voiceIndex":67,"id":"exchange-030"},{"speaker":"藤原委員","kind":"質問・要望","question":"平成１９年度に関しては、補助金は、もし何かで見直されていたら、具体的にこういう形で見直されましたということがあれば、教えていただきたいんですけれども。","respondent":"榎本人事課長","answer":"補助金自体の見直しについては、互助会については、平成１７年度に見直しをしまして、給付を大分切り下げた部分がありますので、それをほぼ継続する形で考えています。","voiceIndex":70,"id":"exchange-031"},{"speaker":"藤原委員","kind":"質問","question":"事業部制の支援経費についてお伺いします。平成１８年度に政策支援情報システム管理経費というのが、たしか３００万円ついていたんですけれども、こことの関連というのは、この経費はあるんでしょうか。","respondent":"堀越行財政改革担当課長","answer":"これまで、事業部支援の経費の中に、地図情報システム、政策支援情報システムという形で入っていたんですが、それが情報システム課のほうに移管となりましたので、その関係で変わっている部分です。","voiceIndex":72,"id":"exchange-032"},{"speaker":"藤原委員","kind":"質問","question":"事業部制を始めまして四、五年たって、私もそれを評価しているんですけれども、これから濱野新区長になられて、基本構想をつくっていかれると思うんですが、その中において、事業部制を維持していくのか。維持していくのであるならば、どういう改革をその中でしていくのでしょうか。","respondent":"日下部企画財政課長","answer":"この組織の体制をどうするかということにつきましては、ここ数年にわたるしっかりした検証をいたしまして、基本的にはこれまでの成果をどう発展させるかという観点になろうかと思いますので、それはそれとして、例えばいろいろ問題があり、課題があれば。","voiceIndex":76,"id":"exchange-033"},{"speaker":"三村委員","kind":"質問","question":"先日、議会費のところでお伺いしました、議長公用車にかかわる経費について、款が違うということだったので、こちらのほうで、車のリース代、ガソリン代、運転手の人件費など、どれぐらいの経費がかかっているのか、その１点だけお伺いしたいと思います。","respondent":"中島経理課長、榎本人事課長","answer":"ガソリン代ですけれども、１台ずつとってございませんので、走行距離等からしますと、年間で約２０万円ぐらいになるのかなと考えています。人件費の部分は、個別の部分になってしまうので、平均の人件費からいきますと、事業主の負担も含めて８５０万円ぐらいという形です。","voiceIndex":79,"id":"exchange-034"},{"speaker":"三村委員","kind":"質問","question":"それを受けて、１年前の３月の予算特別委員会で、この補助金の支出を見直すべきではないかということで質問させていただいたんですけれども、先般、待遇者会のほうから良識ある判断をされて、受け取らないということを判断されたということを新聞報道で見ましたけれども、ただ、１年前の品川区としての回答としては、この判例を受けても、議員待遇者会の補助金８０万円と実際の活動について。","respondent":"桑村総務課長","answer":"その意味で、その中で、最終的な意味では、平成１９年度については辞退をされるというご判断になったわけですよね。私どもとしては、それを追認いたしまして、今回４０万円という予算を組みましたけれども、執行する予定はないという形でいきたいと考えているものです。","voiceIndex":82,"id":"exchange-035"},{"speaker":"三村委員","kind":"質問","question":"これについては、今後出費はされないとは思うんですけれども、それ以外に、事務局機能として、事務事業概要のほうの明細のほうを見ますと、大体０.２人ということなので、先ほどの人件費の平均からすると、年間で１６０万円ぐらい人件費、事務局の作業としてかかっているかとは思うんですけれども、事務局の機能については、今後どのように考えられているのか、その点についてお伺いしたいと思います。","respondent":"桑村総務課長","answer":"これは告示までして、その意味では、対外的にも明らかにしているものです。その意味で、８年経たれた方が待遇者として一定の対応を私どもがするというのは、基本的な対応は特に変わることはないんだろうと思っています。","voiceIndex":84,"id":"exchange-036"},{"speaker":"三村委員","kind":"質問・要望","question":"十分ご検討いただきたいと思います。次に、ＮＰＯとの連携についてお伺いしたいと思います。平成１８年度実態調査が行われましたけれども、ＮＰＯとの連携というところで、今回、予算化されておりまして、平成１８年度については、実際のＮＰＯに対して聞き取り調査や何かをされたということですけれども、そのまとめについて、どういったまとめがされているのか、お伺いしたいと思います。","respondent":"堀越行財政改革担当課長","answer":"ＮＰＯ等との連携ということで、平成１８年度、いろいろな検討を行ってきたわけですけれども、区と連携、協力、今さまざま進めているわけですが、その中で、一定の成果もあり、また職員のほうとしても、いろいろな戸惑いを感じたりとか、ＮＰＯの特性等ですとか。","voiceIndex":86,"id":"exchange-037"},{"speaker":"三村委員","kind":"質問","question":"その実態調査の結果、どういったまとめがされたのかをお伺いしたいんですけれども、よろしいでしょうか。","respondent":"堀越行財政改革担当課長","answer":"今、庁内で連携している事業としては、１１４事業ございまして、そういった形で連携をしているという形の調査をしたところです。","voiceIndex":88,"id":"exchange-038"},{"speaker":"三村委員","kind":"質問・要望","question":"もう少し具体的にまとめの部分についてお聞きしたいんですけれども、先ほど言わなかったんですけれども、別の部分の質問を先にさせていただきたいんですけれども、次世代育成支援、今回中小企業への支援というところで新たに入ってきて、私どもとして、中小企業への支援が必要だということで、長年言い続けてきたので、こういった予算が入ったことについては大変喜ばしいことだと思っているんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":90,"id":"exchange-039"},{"speaker":"三村委員","kind":"質問","question":"その前に行いましたＮＰＯとの連携のまとめのところをもう少し詳しくお伺いしたかったということで、先に述べさせていただいたかと思うんですけれども、その点についてご回答をお願いしたいと思います。","respondent":"堀越行財政改革担当課長","answer":"大変失礼いたしました。ＮＰＯとの部分で、まとめですけれども、まだまとめの作業をしている段階でございまして、区としての基本方針ですとか、そういうのを定めていきたいと考えています。","voiceIndex":93,"id":"exchange-040"},{"speaker":"三村委員","kind":"質問","question":"ぜひ運用段階で、どういうふうにＮＰＯの方にかかわっていくかということで、これから職員の方のマニュアルをつくられるということなんですけれども、特にＮＰＯの方々を見ていますと、少人数でいろいろな事業を手がけられていて、事業を継続していくことが本当に大変だろうなと思うんですけれども、そういったところへの人の支援、行政側からの支援というところも必要かと思うんですけれども。","respondent":"堀越行財政改革担当課長","answer":"いろいろな金銭的な部分ですとか、そういった部分については、直接的な補助という形よりかは、区民の方々にとってどのような形で有効に役立っているか、そういった観点から、いろいろな課題もありますので、検討をしていく必要があると考えています。","voiceIndex":95,"id":"exchange-041"},{"speaker":"三村委員","kind":"提案","question":"平成１７年に政策課題研修ということで、課長も入られて、品川らしい協働を目指してということで、公共的サービスの提供におけるＮＰＯ、企業、地域住民との連携についてということで研修されたかと思うんですけれども、その研修の中での協働推進のための提案ということで、地域に合ったルールづくり、推進支援部署の新設、１人のやろうという勇気、区民フォーラムの開催、ＮＰＯ等の人材育成支援。","respondent":"堀越行財政改革担当課長","answer":"いろいろな区民意識の変化とか、いろいろな地域の課題、多様化とか、そういった部分、それから、地域の方々で解決していただける部分ですとか、そういった部分、それから、これまでの実績、成果を踏まえまして。","voiceIndex":97,"id":"exchange-042"},{"speaker":"三村委員","kind":"意見","question":"これからすべて区の事業として賄っていくということは難しいと思いますし、実際の区民の方の視点に立ったきめ細かい対応というのは、ＮＰＯの方々でありますとか、現場にいらっしゃる方々のほうが、いろいろ手厚い支援でありますとか、当事者の気持ちに寄り添った支援ができるかと思いますので、ぜひ安定・継続的にＮＰＯの方々が活躍できるような場づくりをぜひよろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":99,"id":"exchange-043"},{"speaker":"山内委員","kind":"質問・要望","question":"物騒な世の中になってきまして、まちのお巡りさんだけでは治安の維持の確保に間に合わないと言われている中、まちの皆様のご協力をいただきまして、警察との連携をとりながら、このような日ごろの安全の確保等に努めていただいておるところなんですけれども、ちょっと疑問があったんですけれども、これは警察との連携ということになりますと、警視庁。","respondent":"金子生活安全担当課長","answer":"これまで生活安全担当は平成１５年１０月に発足になっておるんですけれども、それ以降、都の補助金関係を受けているような事実はございません。","voiceIndex":101,"id":"exchange-044"},{"speaker":"山内委員","kind":"質問","question":"東京都の協力があっても私はいいと思うんですけれども、その辺は今後どういうお考えでいくんでしょうか。","respondent":"田村地域活動課長","answer":"補助金に関しては、そういうお話ですが、例えば生活安全パトロール隊、あるいは生活安全担当課長を含めまして、警視庁から２年という形で、警視庁のほうと連携しながら、あるいはサポート隊についても、人的交流を含めて。","voiceIndex":103,"id":"exchange-045"},{"speaker":"山内委員","kind":"質問","question":"我が町パトロール隊、これはいわゆるボランティアでやっていただいているんですけれども、先ほども川西委員から質問がありまして、主に低学年の登下校時にパトロールが実施されるということでお伺いをさせていただいたんですが、具体的な数字なんですけれども、今、パトロール隊というのは区内でどれぐらいの方々が１日に活動していただいているのかというのを教えてください。","respondent":"金子生活安全担当課長","answer":"現在私どもでも把握しているのは、１３８団体、約５,０００名弱いるようにように聞いております。これも、我が町パトロール隊の１つの成果ではないかと考えております。","voiceIndex":105,"id":"exchange-046"},{"speaker":"山内委員","kind":"質問・要望","question":"車について３点お伺いをさせていただきたいんですけれども、ルートの選択という部分が非常に大事になってくるのではないかと思うんでけれども、先ほどもご答弁がありましたけれども、要望があれば、その地域を重点的に回るというお答えがありましたけれども、例えば、１週間のうち月曜日は大井地区だったら、山中小学校の地域を回りましょうとか、戸越地域だったらば、戸越小学校の地域を回りましょうとか。","respondent":"金子生活安全担当課長","answer":"それと、スピーカーにつきましては、まさしくご指摘のとおり、聞こえない地区もあります。それは学校の授業に支障のないように、そういったところも見ながら運行しています。ただ、情勢を踏まえて、活発な広報をこれからもやっていきたいと考えております。","voiceIndex":107,"id":"exchange-047"},{"speaker":"南委員","kind":"質問","question":"１４５ページのタウンミーティング、２つ目は、１７２ページの指定統計、簡単に伺うだけです。よろしくお願いします。それから、統計のほうですが、１７２ページには、何種類かの統計があるんですけれども、この統計のほかに、例えば教育委員会関係では、学校保健統計とかありますが、全体的にどのぐらいあるのか、そして、どういうふうな活用をしているのか、それを伺いたいと思います。","respondent":"中川原広報広聴課長、鷹倉区民課長","answer":"これまでタウンミーティングを実施してきた中で、もう少し時間を短めに設定していまして、言い足りないという方もおられましたので、今回そういう時間設定です。どういう活用をしているのかということですけれども、国勢調査だとか、いろいろな大きな調査、これが区の大きな統計実施計画だとか、統計学だとか、そういうときの基本的なベースにもなりますし。","voiceIndex":111,"id":"exchange-048"},{"speaker":"南委員","kind":"質問・要望","question":"そういうところの活用も含めて、品川区では、企画部長をプロジェクトの責任者にして、プロジェクトチームをつくって、今後の八潮のあり方ということで、去年の６月から検討を始めているという話も紹介されておりましたので、この際改めて、どんな内容で検討しておられるのか、どういうまちづくりをしていこうと区のほうはとりあえずこの問題では考えておられるのか、そこを伺いたいと思います。","respondent":"日下部企画財政課長","answer":"ただ、そうは申しましても、都市計画の権限というのは東京都が持っておりますし、そういうことも含めまして、今後の将来の八潮の活性化を念頭に置いて、都市計画の取り扱いもどうしていったらいいのか、そういうことを１つの軸にしまして、検討を進めているという状況です。","voiceIndex":114,"id":"exchange-049"},{"speaker":"南委員","kind":"質問・要望","question":"私は、先ほども意見として出ていたというところで紹介したんですけれども、公団のところで、調査をしてみましたら、数十件、五、六十件ぐらいの空き家があって、日常的に応募されたら、その場でどこそこに入れますよ、こういう感じで掲示をしているわけですから、住宅政策も含めて、非常に高い家賃があってなかなかというところがありますので、そういうことも含めて。","respondent":"日下部企画財政課長","answer":"これも都市計画にかかわる問題でありますが、その辺のところを１つの柱にしまして、検討を進めている。ただ、例えば八潮につきまして、ほかの地区との違いは、例えば熱供給ですね。あそこは、通常のライフライン、電気や水道は、熱供給、温水を活用しております。","voiceIndex":116,"id":"exchange-050"},{"speaker":"若林委員","kind":"質問","question":"１４９ページの行政評価システム経費につきまして、まずお聞かせ願いたいと思います。区政総合業績評価制度というものが平成１３年度からの第三次長期基本計画の中で位置づけをされております。地方分権絡みで、自律的な行政運営、そういったものに対応する役割を担っているとお聞きをしております。そこで、総括をした上で、今後の行政評価の取り組みについてお考えをお聞きしたいと思います。","respondent":"堀越行財政改革担当課長","answer":"これまでの取り組みを踏まえまして、ＰＤＣＡサイクルをどのように果たしていって、事業の改善等を図っていくかという部分について、どのような指標があるか検討を進めていきたいと考えております。","voiceIndex":119,"id":"exchange-051"},{"speaker":"若林委員","kind":"質問・要望","question":"健全財政、健全財政といつも私も言っているわけですが、具体的に比較検討しながらわかりやすくお話をいただきたいと考えています。２月２７日号によりますと、特集の中で、首都圏の自治体サービスを比較する、そういう記事が掲載されておりました。そこで、財政の健全性について、経常収支比率から言えることを狛江市と、また品川区、できるだけ両者を比較しながらわかりやすく教えていただきたいと思います。","respondent":"日下部企画財政課長","answer":"今ご質問にございました経常収支比率でありますけれども、これにつきましては、人件費でありますとか、扶助費、公債費のように、容易に縮減することが難しい経常的な経費に税を中心とした一般財源がどの程度充てられているかということを示す指標でございまして。","voiceIndex":121,"id":"exchange-052"},{"speaker":"若林委員","kind":"質問","question":"ワースト１の狛江市が財政力指数が０.９１と。財政力指数というのは、１をめどに、これはまたご説明があればと思いますけれども、この狛江市の０.９１というのは、１を基準に、比較的財源に余裕があるよというふうに私は見ております。１００.２だと。これは一見矛盾しているように私には見えるんですけれども、原因としてはどういうものが財政当局として考えられますでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":123,"id":"exchange-053"},{"speaker":"若林委員","kind":"意見","question":"今、企画財政課長からご指摘があったように、狛江市においては、現市長が就任前、基金が５５億円あった。これがこの１０年間で５０億円減って、今、残高が５億円だと。これは品川区の財政規模に換算すると、基金の残高が１,１００万円と。これは私のはじきですので、誤差があったらすみません。市債残高、これは借金のほうですけれども、同じくこの１０年間で６億円増の２４５億円に膨れ上がった。","respondent":"日下部企画財政課長","answer":"詳細は、また分析しないと何とも言えませんが、そういう心配も出てくるのかなと、このように受けとめております。","voiceIndex":126,"id":"exchange-054"},{"speaker":"若林委員","kind":"質問・要望","question":"今の企画財政課長のご指摘のとおりの現象も起こっております。先日、私、夕張市の話にも若干触れましたけれども、首都圏で言いますと、ワースト１に狛江市が入るということで、こういう財政状況を生まないために、さらに行政評価制度を通じた健全財政、また、それによって区民福祉の向上のための施策をしっかりと展開をしていただきたいというのが私の要望です。","respondent":"日下部企画財政課長","answer":"行政評価というのは、成果をしっかりと検証して、次の政策につなげていくということ。そしてまた、それが１つのコストのチェックも含めて、健全財政の源になるわけでもありますので、今後ともしっかりと進めてまいりたいと考えております。","voiceIndex":128,"id":"exchange-055"},{"speaker":"本多委員","kind":"質問","question":"最初に自衛隊のほうなんですけれども、この募集事務費というのは、根拠としては、都道府県知事および市区町村長が自衛官の募集に関する事務を行うということで、政令に定める法定受諾事務ということで、何年も同じ４万４,０００円ということで、受託事務ですから、わかりますけれども、昨今の応募者、入隊者の状況を教えてください。","respondent":"鷹倉区民課長","answer":"平成１５年あたりから見てみますと、応募者が８７人に対して、入隊者が１２人、平成１６年度が、応募者が１０３人に対して、入隊者というか、合格者が１１人、そして、平成１７年度が応募者８３人に対して、合格者、入隊者が１８人。","voiceIndex":131,"id":"exchange-056"},{"speaker":"本多委員","kind":"質問・要望","question":"麻生外務大臣が国際貢献で日本の評価を上げたのは自衛隊の働きがあったからこそというふうに述べております。防衛庁も、今年から防衛省と変わりまして、こういった事務のことを、国からの受託事務で各自治体やっておりますけれども、国からレベルアップですとか、自治体として何らかのかかわりというか、レベルアップできないか、その辺を教えていただきたいと思います。","respondent":"鷹倉区民課長","answer":"募集事務ということで、先ほど委員ご紹介のとおり、募集に関する事務の一部を行うという形で、国と連携しながらやっていくということです。応募状況だとか、合格者の数、この辺のところと連動しながら、予算を措置していただいているです。","voiceIndex":133,"id":"exchange-057"},{"speaker":"本多委員","kind":"質問","question":"これまで自衛隊の防災訓練ですとか、参画をという、議会でも議論がありましたけれども、都道府県知事レベルで、いろんな派遣とか、出していくものですから、なかなか難しい部分もあるとは思うんですけれども、何らかの自衛隊との連携、防災的というか、危機管理的というか、防災性とかでも、何か連携がこの後、進まないか、ちょっと教えてください。","respondent":"久保田防災課長","answer":"具体的に日常的な連携ということで申し上げますと、毎年私ども、１月１７日前後、阪神・淡路大震災の前後ということで、防災フェアを開催しておりまして、ここに自衛隊のほうの、例えばいろんな車両とか、そういうものを持ってきていただいて、披露していただくとか、あるいは。","voiceIndex":135,"id":"exchange-058"},{"speaker":"本多委員","kind":"質問・要望","question":"ある町会が今年度をもって解散するということがあるそうですが、私の知っている範囲では、集合住宅の自治会とかの構成が変わるというのは今までに知っているんですけれども、町会という単位が解散してしまうという事例を初めて聞きまして、その辺、区役所ですとか、地域センターの今までの連携、困ってしまう部分とかもあると思うので、どうとらえるかを教えてください。","respondent":"田村地域活動課長","answer":"今、町会の解散というお話ですが、町会には、まず２つの面があります。１つは、各地域ごとに、いわゆる地縁に基づく任意の団体で、結成する、しないは、各地元に住まれた方が中心となって結成するという形の考え方。もう一面は、区政協力委員会の委員です。","voiceIndex":137,"id":"exchange-059"},{"speaker":"本多委員","kind":"質問・要望","question":"解散をできる限り防ぐというか、継続をしていっていただきたいと思います。任意団体とはいえ、その辺の補い方というか、あくまで任意団体ですから、自発的なそれが望ましいとはわかりますが、今後の支援の仕方といいますか、地域の自助、公助、共助の後方支援については、どのように考えているか、教えてください。","respondent":"田村地域活動課長","answer":"そういう意味からしますと、地域センターの所長が、人事案件まではできないですけれども、当然アドバイスはできませんが、町会存続についてのほかの事例も、同じような形で、同じような課題を背負った話も私ども聞いておりますので、アドバイスという形で。","voiceIndex":139,"id":"exchange-060"},{"speaker":"本多委員","kind":"質問・要望","question":"その辺の理由については、警察や消防ですとか、いろんな分担金が多くて、実際の町会運営に支障を来しているという意見もありましたので、すぐには対応が難しいとは思いますが、そういったことがありますので、できる限りの支援をお願いしたいという要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":141,"id":"exchange-061"},{"speaker":"本間委員","kind":"質問","question":"先にテーマだけ言います。１３５ページの職員研修費について、１３９ページの水と緑の市町村との交流事業について、１５５ページ、１５７ページに絡んで、区民斎場運営費、臨海斎場運営費、１６３ページ、誕生記念品支給経費についてお伺いします。順次進めていきます。この件についてまず最初にお伺いしていきたいと思います。その必要性、ねらいとするものについて、お伺いします。","respondent":"榎本人事課長","answer":"実際には６名の枠をとっておりまして、平成１９年度から６名枠もいっぱいで応募が出てきているところです。","voiceIndex":143,"id":"exchange-062"},{"speaker":"本間委員","kind":"質問","question":"６名枠もいっぱいだということですね。そうしますと、これを頭数で割ったらいいのかもしれませんが、助成枠の費用の中身について、ついでにお伺いします。","respondent":"榎本人事課長","answer":"細かいところまではわからないんですけれども、１人当たりですと９,０００円ということになりますので、実際の授業料の８５％等を補助するという形です。","voiceIndex":145,"id":"exchange-063"},{"speaker":"本間委員","kind":"意見","question":"立派な技術を身につけて、よい仕事をされるように期待しています。そして、研修助成の下のほうになりますが、職員研修体系の再構築についての内容、ここに６３０万という形で出ておりますが、職員研修体系の再構築について、これは新しい言葉みたいに思いますので、この意味合い、中身についてお知らせください。","respondent":"榎本人事課長","answer":"それで、今年度既に人材育成基本方針というものを検討しておりまして、大分固まってきているんですけれども、今度、それに基づいた具体的なプログラムを構築していこうという形です。","voiceIndex":147,"id":"exchange-064"},{"speaker":"本間委員","kind":"質問","question":"続きまして、一番下のところなんですけれども、代替職員雇用経費という部分があります。代替職員の雇用ということが、中身的に受け取りがはっきりとできないものですから、その内容、それから人数とか、仕事の中身、例えば現業、事務職などの内訳はどうなっているのか。そして、資格を必要とするような仕事があるのかということについて、お願いします。その採用の仕方はどうなっているのか。","respondent":"榎本人事課長","answer":"資格につきましては、アルバイトの場合ですと、無資格でほとんど入っております。人材派遣につきましては、それぞれのスキルに合ったところなので、有資格でないと配置できないところについては、有資格者を配置するような考えでおります。","voiceIndex":149,"id":"exchange-065"},{"speaker":"本間委員","kind":"質問・要望","question":"もうちょっと私のほうは、受けとめ方として、短時間労働に携わるという部分で理解して、この人々に対して、将来的には正規雇用の昇格みたいな形で、もっと前向きな部分での仕事の進め方、いわゆるワークシェアリングを実際に現場でどのようにやっていくのかというとらえ方をしておりましたものですから、話はここでやめておきます。次に１３９ページ、水と緑の市町村との交流です。","respondent":"鷹倉区民課長","answer":"ヘルシー美里、ヴィラ雨畑の一般利用という部分です。一般利用につきましては、通常７,０００円のところを１割引をしているという、まず基本的なものがあります。そしてさらに、区民利用助成ということで、年間連続３泊までの助成というものがあります。","voiceIndex":151,"id":"exchange-066"},{"speaker":"本間委員","kind":"意見","question":"新しい今年度の方針を見ますと、地元の有力な方が品川区に山を提供し、その活用方を区民とともに今後進めていくという中身を聞いておりますが、早川町というのは、私たちが子どもたちなんかと一緒に行く場合に、大変喜びのメニューがあるところでございまして、有利な条件的なものとしましては、アルプスの山々、早川という川、野鳥の森、湖、滝、キャンプ場等々。","respondent":"鷹倉区民課長","answer":"そこから、いろいろ話をする中、まちの森林組合の方々と話すこと自体がまず交流である。そういう形で、具体的に一歩一歩着実に計画を立てて、１０年ぐらい考えながら、着実に進めていきたいと考えているところです。","voiceIndex":153,"id":"exchange-067"},{"speaker":"本間委員","kind":"質問・要望","question":"今後とも、子どもたちの遊びがどんどん増えるという意味で、期待の持てるところとなるように、子どもたちの希望がその中に入るような形でひとつ進めていただきたいと思います。次にいきます。１５５ページの区民斎場運営費、１５７ページの臨海斎場運営費についてですが、それぞれ利用されている実績と最近の傾向についてお尋ねします。","respondent":"鷹倉区民課長","answer":"なぎさ会館のほうですが、なぎさ会館につきましては、今年度は２カ月間、夏休み、空調関係の工事がございました。その関係で若干落ちてありますが、平成１５年あたりからは、３９０、あるいは４００、この辺のオーダーで来ています。","voiceIndex":155,"id":"exchange-068"},{"speaker":"本間委員","kind":"意見","question":"なぎさ会館はまたもとに戻るですが、それでは、臨海斎場の件で、前にもお話ししたかと思いますけれども、今後の課題について何かあると承知しているのでしたら、お知らせください。なければないで結構ですが。","respondent":"鷹倉区民課長","answer":"これは必然的に多くなってくるなと。そうすると、今の施設規模で大丈夫かなということが少し懸念され始めております。したがって、その部分を何とか検討しなければいけないなというところに来ている状況です。","voiceIndex":157,"id":"exchange-069"},{"speaker":"本間委員","kind":"意見","question":"最近タクシーの利用者が多くなってきていると思います。そのような面で、時々交通の至便について問われることがありますが、その辺についてのお考えはいかがでございましょうか。","respondent":"鷹倉区民課長","answer":"したがって、私どもとすれば、できるだけ、どういう形で使えるかというところを、時間帯も含めて、できるだけわかっていただけるような形で、皆様方に便を供していきたいと考えているところです。","voiceIndex":159,"id":"exchange-070"},{"speaker":"本間委員","kind":"質問・要望","question":"京急バスともお話し合いを進めているということですが、この葬儀に絡む問題は、大体時間帯が決まっていると思います。その辺の部分、今後とも話し合いをさらに進めていただきたいと思っています。この件につきましては、前にお話が質問として出ておりましたけれども、その内容についてお伺いします。単価がどれぐらいで、人数がどうなんだということについて、簡単で結構ですけれども、お知らせください。","respondent":"上川内戸籍住民課長","answer":"単価は１,０００円程度です。人数としましては、住民である新生児に対して渡すものですので、今、出生が若干増えておりますが、２,６００～２,７００名程度に渡しています。","voiceIndex":161,"id":"exchange-071"},{"speaker":"本間委員","kind":"質問・要望","question":"時間がなくなりましたので、要望にとどめておきたいと思いますが、後ほどご検討いただければと思います。緑の部分での問題意識といいますか、花の種をいろいろな団体の中で配っていたり、あるいは、地方の自治体なんかに行きますと、小さな花壇、草花の苗木をお渡ししていたりしているところもあります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":163,"id":"exchange-072"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１５０ページの防災対策費について伺います。避難所の充実とか、長周期地震動の対策について質問いたします。予算の１５０ページのところに防災予算が載っているわけですけれども、昨年と比べると増になっていますが、この中で、国と都の負担がどうなっているのかを教えていただきたいと思います。区として、国や都に防災予算へのコメントがあれば、聞かせていただきたいと思います。","respondent":"久保田防災課長","answer":"これらについては一通り品川区の場合にはもういただいてしまっているところがありまして、新たなものについては、いろんな段階で出てきていますので、私ども、国への要望とか、東京都に対する区長会要望の中で、要望をしてまいっておりますけれども。","voiceIndex":165,"id":"exchange-073"},{"speaker":"飯沼委員","kind":"質問・要望","question":"一般会計に占める割合が０.５８％なんですよね。こういった面で、税金をだれのためにどう使うのかという視点の上からおいたらば、もっともっと防災予算は増やしていくべきであると思っています。人口も増えていますけれども、人口の集中をしている地域とか、そういった面で、避難所の機能の充実が求められているんですが、現状がどうなっているのかお聞かせをいただきたいと思います。","respondent":"日下部企画財政課長、久保田防災課長","answer":"最初の１点目でありますけれども、これにつきましては、防災対策関係ですが、区としてもこの間、予算編成の１つの大きな柱として、安心・安全、防犯・防災、こういう形で重点的に取り組んでまいりました。日野学園は、従来は第二日野小ということで、それを継続していますので、２４３人ですけれども、地域防災改革の中での見直しも一定程度考えていくんですけれども、日野学園はかなりスペース的にありますので。","voiceIndex":167,"id":"exchange-074"},{"speaker":"飯沼委員","kind":"質問・要望","question":"全体の大きな枠のところも教えてほしかったんですが、そこは後でお願いしたいのですが、避難所としての収容能力は、小・中学校、あと、高校もあると言っていましたけれども、十分ではないし、これはもっとほかの面での対策が必要ではないかなと思っています。家具の固定などがほとんど効かないというところでは、住民の避難をどうするのか。今後の予測の推移なんかも聞かせていただきたいと思います。","respondent":"久保田防災課長","answer":"そういう点では、自助、あるいは隣近所と力を合わせてやる共助、そういうような意識を高めていただくということがまず基本だと考えておりますので、そういうような啓発・普及に今後とも努めていきたいと考えております。","voiceIndex":170,"id":"exchange-075"},{"speaker":"飯沼委員","kind":"質問・要望","question":"マンションのところは、こちらに部長もいらっしゃるので、現状どのぐらいか、ぜひお答えをしていただきたいと思います。ちょっと怖いなと思って読んだんですけれども。しかし、ビルが壊れなくても、内部の施設は大きな被害を受ける可能性がある。そういった人たちが避難難民になってしまうという状況は明らかにあるので、この辺は何とかしてほしいと思います。その辺もお答えいただきたいと思います。","respondent":"片田建築課長","answer":"超高層のお話が出ましたので、軒数という意味では、１年以上前に１度同じようなご質問のときに３５軒ぐらいと言ったような記憶がありますけれども、それ以降、６０ｍ以上の建築物、かなり建ってありますので、現時点での軒数まで、恐縮ですが、把握してございません。","voiceIndex":172,"id":"exchange-076"},{"speaker":"大沢委員","kind":"質問","question":"１４３ページの近隣セキュリティシステム運営経費と特別区人事・厚生事務組合、１４９ページ、ボランティアのところで伺います。最初に、近隣セキュリティシステムですけれども、前年に比べますと、４,０００万円近く予算の計上が減っております。これはシステム変更に伴う経費が今年は用がなくなったから減ったということでとらえてよろしいのでしょうか、教えてください。","respondent":"金子生活安全担当課長","answer":"運営経費の内容ですけれども、昨年まで子機の基本料金が全体の大多数を占めるといいますか、約１億円ほどかかっておったんですけれども、来年度につきましては、長期割引による子機の基本料金が大幅に減額になっております。","voiceIndex":175,"id":"exchange-077"},{"speaker":"大沢委員","kind":"質問","question":"子機の割引率が上がったということで下がった。先ほど私が考えていました、新規変更に伴う経費の削減分ではないということでいいわけですね。わかりました。今おっしゃっていました中で、システムの管理経費、これはセンターシステムの保守管理、そしてサーバーの賃借料とありますけれども、保守管理の経費、サーバーの賃借料は大体幾らぐらいなものか、教えてください。","respondent":"金子生活安全担当課長","answer":"子機のデータベースの運用保守管理が、１,９００万円。業務従事者の派遣委託が１,６００万円。","voiceIndex":177,"id":"exchange-078"},{"speaker":"大沢委員","kind":"質問","question":"後で詳しく。賃借料を伺ったんですけれども、何が聞きたかったのかというと、近隣セキュリティシステム、これは著作権が出てきますね。近隣セキュリティシステム、他区から本区に対してご興味をお持ちで、勉強に来る区はどのぐらいあるのか、教えてください。","respondent":"金子産業振興課長","answer":"今、委員お尋ねのとおり、他区、あるいは他県の自治体の行政担当者、議員、たくさんお見えいただいていますけれども、件数は数えておりませんけれども、お見えになって、私どもが対応した方が大体２０件ぐらいということでご承知いただきたいと思います。","voiceIndex":179,"id":"exchange-079"},{"speaker":"大沢委員","kind":"質問","question":"２０件、それはたくさんととらえていいわけですね。たくさんととらえます。ここで言う著作権ということですけれども、近隣セキュリティシステムというものの著作物、これは著作権ということで、区としては守るべき著作権ととらえているのか。それとも、周りに対して普及すべき著作権ととらえているのか、どちらなのか、教えてください。","respondent":"金子産業振興課長","answer":"これにつきましては、当然ほかの方々、ほかの自治体で活用なさる場合には、提供するつもりですけれども、その場合には、確定したお答えはできませんけれども、一定の使用料等があり得るのではないかなと考えているところです。","voiceIndex":181,"id":"exchange-080"},{"speaker":"大沢委員","kind":"質問","question":"これは歳出なので、それは別ですけれども、特許のほうは登録しなければいけないわけですけれども、仮にその間に、著作権ないし、このシステムはいいからうちでも独自で使いたいと、かすめ取られた場合、どういうふうにするんですか。","respondent":"金子産業振興課長","answer":"勝手に使われた場合ということですけれども、これは私どもの権利ですので、そういう意味では、私どもの権利をしかるべく主張して、しかるべく対応していきたいと考えています。","voiceIndex":183,"id":"exchange-081"},{"speaker":"大沢委員","kind":"質問・要望","question":"もう１回繰り返しますけれども、著作権というものが高いハードルにならないような形でもっていっていただきたいと思います。次に移りますが、特別区人事・厚生事務組合ということなんですけれども、杉並区で特別区人事委員会を脱退して独自につくろうという動きがありますけれども、それについて何かコメント、ご感想があれば、聞かせてください。","respondent":"榎本人事課長","answer":"私も新聞記事で見たところですけれども、特別区人事・厚生事務組合の中に特別区人事委員会があるということで、その場合に、品川区でもかつて、いろいろな一部事務組合についての関係で調べたときに、１回東京都の許可を得て。","voiceIndex":185,"id":"exchange-082"},{"speaker":"大沢委員","kind":"質問","question":"品川区が独立した自治を確立すべく、将来船をこいでいくのであれば、やることの難しさ云々もあるでしょうけれども、これは議論の中に乗せるべきだと思うんですけれども、行政の中では、話し合われて。私は調べてないので、過去にどのような議論が行われたかは勉強不足でわかりませんけれども、そのような話が行われたことがあったのかどうか、教えてください。","respondent":"榎本人事課長","answer":"ちょっと検討しただけなんですが、今現在、特別区人事・厚生事務組合の中で、人事委員会が持っている予算が１億５,０００万円ほど年間でかかっている。事業費だけで１億５,０００万円。それを単純に２３区で割りますと、６５２万円という形での負担になります。","voiceIndex":187,"id":"exchange-083"},{"speaker":"大沢委員","kind":"質問","question":"これから聞きたいことの呼び水として今伺ったんですけれども、今度、品川区で先生の独自採用ということを予定されております。そういう意味からいって、本区においても、そのような形の中で、一般の職員にも波及する可能性があるのかどうか、教えてください。","respondent":"榎本人事課長","answer":"今現在採用については、２３区で人事委員会を通して採用しているものと、あと各区に任されて、委任をされている選考があります。","voiceIndex":189,"id":"exchange-084"},{"speaker":"大沢委員","kind":"質問","question":"今のやり方を改善していくというお話です。仮の話なんですけれども、人事委員会をつくって、人事権を本区に移した場合に、メリット、デメリットを教えていただければと思います。","respondent":"榎本人事課長","answer":"メリットとしましては、その区で使いたい人材を直接採用ができるということです。デメリットとしましては、その区が魅力をかなり継続的に持たない限り、人が集まらない場合があるということ。それからあとは、費用負担が大きくなるというものがあります。","voiceIndex":191,"id":"exchange-085"},{"speaker":"大沢委員","kind":"質問","question":"今、本区に魅力がなければ人が集まらないということでお話しいただきました。次に移ります。ボランティアのところなんですけれども、先ほどＮＰＯとのボランティアの協働ということで伺いましたけれども、ＮＰＯではなくて、ボランティア同士の協働といいますか、ボランティア同士の横のつながりの仕組みは、区ではどのように構築をされているのか、教えてください。","respondent":"堀越行財政改革担当課長","answer":"先ほど答弁させていただいたＮＰＯ、ボランティア等の連携の仕組みづくりの中で、ボランティアの部分についても、実態調査を行わせていただいているところです。","voiceIndex":193,"id":"exchange-086"},{"speaker":"大沢委員","kind":"質問・要望","question":"意外とボランティアというのは無報酬、自発的な意思に基づくボランティア、ご自身の興味がわいた部分でボランティアをされるわけですけれども、そこのもう一歩先の部分で、ボランティア組織間の連携がうまくいっていないような気がしております。連携、連携ということで言われて久しいですけれども、もう１回再度見直していただきまして、より充実したシステム構築をしていただきたいと思います。","respondent":"堀越行財政改革担当課長","answer":"今あるシステムと、この調査をしたところ、それからご要望等もお伺いしながら、いろいろ課題もあると思いますけれども、検討していきたいと考えております。","voiceIndex":195,"id":"exchange-087"},{"speaker":"中島委員","kind":"質問","question":"短い時間ですので、まとめて質問したいと思います。一般管理費の１３５ページ、職員研修費の中で、先ほど職員研修体系の再構築という質問が出ておりました。それから、その上に、建築士養成研修プランニングというのがあります。これは、プランニングですから、これから始めるものなのでしょうか。次に、広報費の中の１４５ページ、法律相談に関連して質問したいと思います。以上、３点お願いします。","respondent":"榎本人事課長、中川原広報広聴課長、太田税務課長","answer":"建築士プランニングにつきましては、平成１７年度受験分から既に補助をしておりまして、今現在、実績、４名がこれを受けて、それぞれ建築士の１級。これは、弁護士さんのご協力を得まして、開始しまして、受講した者も、効果的だということで、今後続けていきたいと考えています。普通徴収については、調定額そのものが上がってありますけれども、２月末現在で、全体の収納率で０.７％ほどアップしているという状況です。","voiceIndex":198,"id":"exchange-088"},{"speaker":"中島委員","kind":"質問・要望","question":"職員の研修ということなんですが、建築士の養成で今４名の方がというお話がありました。今の区のいろいろな体制を見ておりますと、委託事業もかなり出てきております。先ほど特別区と各区でできるものとそれぞれあるということで、その辺で支障はないのか。各区に任せられたときに、受けられないものが出てくるのではないかという懸念もありますが、この辺はどうなんでしょうか。","respondent":"榎本人事課長","answer":"区の中で集められるものについては、区の中で独自に、区に合わせた形でカリキュラムを組んでいきたいと考えております。","voiceIndex":202,"id":"exchange-089"},{"speaker":"中島委員","kind":"質問・要望","question":"特に私なんかが一番感じているのは、建築士ということで、いろんな区の建設物を見ておりますと、もっと早くしっかりとチェックができていたら、こんなむだはなかったのになと思うことが時々感じられることがありますので、この辺のところもしっかり取り組んでいただきたいと思います。この辺はいかがでしょうか。","respondent":"中川原広報広聴課長","answer":"法テラスにつきましては、毎日電話相談で、お問い合わせがあったときに、お急ぎの方にはお知らせをしているところです。広報紙で載せられるかどうかは、今後、相談のコマの中で考えさせていただきたいと考えています。","voiceIndex":204,"id":"exchange-090"},{"speaker":"中島委員","kind":"意見","question":"私ども、いろんな相談を受けるときに、何かで見つけて、ここなら電話してみようと思って電話をかけていれば、もっと早く解決できたのにと思うこともたくさんあります。コンビニの点では、いろいろな点でアップされているということで、これからの時代、コンビニの活用について、さらにいろいろ考えていく価値があるのではないかなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":206,"id":"exchange-091"},{"speaker":"須貝委員","kind":"質問","question":"私は総務全般で質問をします。昨今各地の自治体等の公共工事に対する談合事件が起きております。ある場合には、その制裁内容について、大まかでいいですが、教えてください。","respondent":"中島経理課長","answer":"さらに加えまして、品川区の指名停止基準にのっとって、指名停止をかけるということになろうかと考えています。","voiceIndex":208,"id":"exchange-092"},{"speaker":"須貝委員","kind":"質問","question":"そうすると、他の自治体、例えばある大手のゼネコンがやった場合には、談合ということが発覚した場合には、品川区でもそういう処置をとるという考え方でよろしいですね。次にお聞きしたいのですが、品川区では、一般競争入札と随意契約がありますが、随意契約とはそもそもどういうものなのか、お聞かせください。","respondent":"中島経理課長","answer":"区で契約する場合に、これはもちろん地方自治法にのっとってやっておりますけれども、３種類ございまして、一般競争入札と指名競争入札、それと随意契約とあります。随意契約につきましては、政令で定める場合に限られております。","voiceIndex":210,"id":"exchange-093"},{"speaker":"須貝委員","kind":"意見","question":"例えば大手ゼネコン、河川工事とか、大型工事の場合でも、特殊な工事に関しては、随意契約していると思うんですが、随意契約するときに、業者が提示する金額をそのまま区のほうとしては受け入れているのかどうか、その辺をお聞かせください。","respondent":"中島経理課長","answer":"特異な事例ですけれども、ただ、いずれにしましても、随意契約をとる場合は、先ほど申しました、政令に基づいた理由に基づいてやっておりますけれども、私どもは、工事につきましては、従来から一般質問等でご答弁申し上げていますけれども、きちっとした積算基準のもとに。","voiceIndex":212,"id":"exchange-094"},{"speaker":"須貝委員","kind":"確認","question":"再確認なんですが、随意契約の場合でも、品川区のほうとしては、きちんと積算をして、予算がありますが、その基準に対して、基準内で出していただいているということでよろしいですか。","respondent":"中島経理課長","answer":"予算の範囲内でやっていくということが当然のことです。","voiceIndex":214,"id":"exchange-095"},{"speaker":"須貝委員","kind":"質問","question":"その場合、お聞きしたいんですが、積算ですが、それはどこの部署、どの課でやっていて、何人ぐらいの人が積算に従事しているんでしょうか、お聞かせください。","respondent":"宍戸施設担当課長","answer":"それは工事の種別によって違いますけれども、例えば建築工事であれば、経理課の職員が担当していますし、その他まちづくり事業部、各部署でそれぞれきちっと積算しているです。人数につきましては、それぞれの技術職員です。","voiceIndex":216,"id":"exchange-096"},{"speaker":"須貝委員","kind":"質問","question":"今、積算という話をしているんですが、積算の金額ですが、それは、経理課、それぞれ各事業部でやっているというお話ですが、実際今積算専門にやっている会社もありますよね。そういうところに相談するとか、そういうことはなくて、あくまで品川区内の各事業部でやっているということでよろしいでしょうか。","respondent":"宍戸施設担当課長","answer":"例えば建築工事の場合ですと、国土交通省が定めた積算基準があります。それに基づきまして、我々は積算しているわけでございまして、ほかの河川工事、土木工事についても同様です。","voiceIndex":218,"id":"exchange-097"},{"speaker":"須貝委員","kind":"質問・要望","question":"ですから、私が思うに、ほかの自治体等もありますが、東京都内２３区でもそうですが、今せっかく電算化システムの導入に向かっていると思うんですが、そういう積算に関して、各区とも連携をとって、今も国交省の基準でしょうが、世の中の適正な基準もあると思いますので、より勉強していただいて、連携をとって、もっと安く上がるように、経費が安く済むように努力していただきたいと思います。","respondent":"宍戸施設担当課長","answer":"あくまでも構造計算で、客観的なものですから、そういう意味では、新築派、補強派というふうに分かれているわけでは決してなくて、補強工事をどういうふうに進めていけばいいかという構造基準に基づいて診断がなされているです。","voiceIndex":220,"id":"exchange-098"},{"speaker":"須貝委員","kind":"質問・要望","question":"業者間のほうで話を聞きますと、最終的には人間が判断すると思うんですね。そのときに、いや、これは十分耐震補強で済むよと。ですから、耐震診断に関しても、私は、２社とか３社に見てもらって、そんなに費用がかかるものではないと思いますので、きちんとそういうふうに正確な判断を出してもらうようなことを求めていくべきじゃないかと思うんですが、その点に対してご見解をお聞かせください。","respondent":"宍戸施設担当課長","answer":"耐震診断というのは、先ほども申し上げたとおり、構造計算ですから、非常に客観的なものです。建て直したほうがいいかどうかというのは、総合的に区として判断するです。","voiceIndex":222,"id":"exchange-099"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"財政管理費の中の契約関係事務費に絡んでなんですが、指定管理者制度について基本的なところをもう一度確認をさせていただきたいと思います。そこら辺のところがまず１点、確認のところから。それからもう１点、先ほどの防犯マニュアル作成事業のほう、この２,１５６万円の予算を計上している中身を、先に状況を教えていただきたいと思います。","respondent":"金子生活安全担当課長、堀越行財政改革担当課長","answer":"全世帯に配布する予定ですから、１,４００万円。それと、防犯マニュアルの配布委託につきまして、２００万円。防犯マニュアルの作成委託、これはＮＰＯ法人等のコンサルタントをするところですが、５００万円。こういった内容です。指定管理の事業費のお尋ねですけれども、新築の場合、公の施設を設置して、指定管理者を導入するとなった場合には、基本的には公募という形で募集をかけて、管理者を決定していく、そういう考え方です。","voiceIndex":225,"id":"exchange-100"},{"speaker":"鈴木（真）委員","kind":"確認","question":"防犯マニュアルのほうを先に確認させてください。ＮＰＯ法人というお話が今あったんですが、具体的に言うと、どんなものが配布されるのかなというのが、あまりイメージがわからなかったんですね。つくるのはＮＰＯ法人ということになるんですが、例えばそれは、区内でも範囲が広い。それとも、一括で、区内としてはこんな状況があるんですよという話で出てくるのか。それを先に確認させてもらいます。","respondent":"金子生活安全担当課長","answer":"結論から申し上げますと、地区ごと、おおむね４つの箇所になるかと思いますが、地区ごとの特殊性を生かした防犯マニュアルプラス、区民の方全員が気をつけなければいけない防犯関係、これについて集約した形で発行する予定です。","voiceIndex":228,"id":"exchange-101"},{"speaker":"鈴木（真）委員","kind":"質問","question":"４つということでわかりました。そうすると、例えば警察との関係の絡みということでの４つという意味でいいんでしょうか。","respondent":"金子生活安全担当課長","answer":"そのとおりです。警察と付近住民の方、こういった方々の参加型による特殊性を出した防犯マニュアルといった形になります。","voiceIndex":230,"id":"exchange-102"},{"speaker":"鈴木（真）委員","kind":"質問","question":"よく連携をとって、また、区民の方にもよく理解できるような形で、発行のほうをお願いしたいと思います。ただ、その時点では、まだ正式決定をしていないというところが、先方にとっても不安だと思いますし、我々議会のほうとして考えたときには、何も議案として出てきていない中でスタートしていく話になるんじゃないかと思うんですが、そこら辺はどう考えているんでしょうか。","respondent":"堀越行財政改革担当課長","answer":"新築の施設の場合のお尋ねですけれども、施設の設置目的等に沿いまして、より効果的によい施設として運営していくためには、今回の場合も、条例設置の前に、そういった形で、運営事業者という形があったわけですけれども、運営事業者についても、公募で決めておりますので。","voiceIndex":232,"id":"exchange-103"},{"speaker":"鈴木（真）委員","kind":"質問","question":"結局議決する前の段階でスタートしているわけですよね。なぜかというと、私も気になっているのは、議会が４月に解散、選挙が終わって、５月から新しい議会になったときに、極端に言ったら、４０人全員違う議員が入ってくるかもしれない。極論ですけど。要するに議決の時期というのは、今やっている形でないとすべて議決できないのかどうか、そこら辺はどうでしょうか。","respondent":"堀越行財政改革担当課長","answer":"議決までの期間のお話で、条例の設置の時期のお尋ねですけれども、議決の前の段階でも、継続して、ご報告をさせていただいたりしておりますので、新規の施設をどう効果的に運営していくかということと、また、指定管理者制度についても、効果的に運営しつつ。","voiceIndex":234,"id":"exchange-104"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"当然報告はいただいているのはわかります。指定管理者になるべき方を批判するのではなく、条例の議案としての流れ方が、このままでいいのかなという思いが非常にあります。その辺もう１回お聞きしたいのと、これから指定管理者制度を導入されて、すべてそうですけれども、指定管理者に対するチェックがどこまでできるのかなと。すべての経理を見なければいけない。その辺も教えていただきたいと思います。","respondent":"新美企画部長","answer":"公の施設、特に新設の場合の条例との関係ですが、やはり公の施設、着工し、施設が竣工見込みが立った時点で、設置条例を提案するという性格上、特に設計段階から運営事業者を決めて、効果的な施設運営という観点からは。","voiceIndex":236,"id":"exchange-105"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"流れ上、やむを得ないと思いながらも、非常に疑問を持っている部分なので、その辺、これからも、先方にもわかりやすいような形をとりながら、議会に対する説明もしていっていただきたいと思います。それと、会社の内容等に関しては、確実なチェックをしていただきたいという思いがあります。今やっているのが基準ですよという話になるのか、そこら辺はどうなんでしょうか。","respondent":"日下部企画財政課長","answer":"要するに何のためにバランスシートを作成するか、１つには、他の自治体との比較という、そういった１つの分析評価、これも大きな目的でありますので、基本的には総務省基準をベースにして進めていくことになろうかとは思いますけれども、ただ、都でもいろんな動きもありますので。","voiceIndex":238,"id":"exchange-106"},{"speaker":"鈴木（真）委員","kind":"質問","question":"この資料の中で、バランスシートの中で、非常に見やすくしてもらっているんですけれども、将来の世代に残る財産等の金額とか、将来の世代が負担しなければならない金額、今までの世代が負担した金額、非常にわかりやすく書いてもらっている中で、資産合計４,３１６億という大きな金額になっている中で、ちょっと気になったのは、土木費がやはり大きいんですね。そこら辺はどうなんでしょうか。","respondent":"日下部企画財政課長","answer":"その辺に重点が置かれているということでもありますので、私どもがしっかり勉強して、対応してまいりたいと考えています。","voiceIndex":240,"id":"exchange-107"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"いろいろ新しい基準に基づいてやっていくと、資料をつくるのが大変な作業になってくると思いますが、その辺よく研究してやっていただきたいのと同時に、最後に、経営状況の資料は、職員の方、皆さんに配付しているのかなと。皆さんもやっぱり理解しているんでしょうねというのを確認しておきたいんですけど。","respondent":"日下部企画財政課長","answer":"全員に配るということではなくて、所属単位で配っております。昨年は、関係の収入役室と経理課、私どもが一緒になって勉強会を開いた経緯もありますが、そういう取り組みも含めて、進めていきたいと考えております。","voiceIndex":242,"id":"exchange-108"},{"speaker":"菊地委員","kind":"質問・要望","question":"１３５ページの同和生活相談員費をお聞きいたします。同和対策特別措置法が２００２年で失効しましたけれども、これによって法的な根拠はなくなったわけですけれども、品川区がこの法律が失効した後も同和相談員を置いて、３２８万円の支出をしていますけれども、そこの根拠を教えていただきたい。それから、もう１点ですけれども、事業評価として、Ａ、Ｂ、Ｃ、Ｄ、どのランクになっているのか。","respondent":"武内人権啓発課長","answer":"今、委員ご案内のとおり、同和対策事業措置法というのは、平成１４年に失効しました。ご存じのとおり、これは昭和４４年に同和対策事業の特別措置法の事業が３３年間続いたというものです。元来この事業法というのは、特別事業法ですから、時限立法です。","voiceIndex":248,"id":"exchange-109"},{"speaker":"菊地委員","kind":"質問・要望","question":"詳しくご説明をいただきましたけれども、私、先日、総務部分室へお訪ねしました。このときに、相談室なるものを見せていただきたいとお願いしましたけど、見せていただけませんでした。ですから、相談内容についてもお聞きをすることはできませんでした。こういう状況でこれを認定をしろと言われても、大変困ってしまうんですけれども、どうして相談室さえ見せることができないのか、ここをお聞きします。","respondent":"武内人権啓発課長","answer":"そういった意味で、決して見せないとか、見せるとか、そういう議論ではなくて、たまたま先週お見えになったときは、９時の時間帯でお見えになっていまして、９時になりますと、生活相談員の方は執務時間になりますので、この時間帯ですと。","voiceIndex":250,"id":"exchange-110"},{"speaker":"菊地委員","kind":"質問","question":"今度行けば見せていただけるわけですね。さっき差別とおっしゃいましたけれども、差別問題をやめようよということで、人権という大きな枠の中で考えていこうということで行われているわけですから、ここは、どうしても一般相談に移行していくべき内容だと思います。先ほど６区とおっしゃいましたけれども、私も見ました。そうしたら、５区ですね。質問は、一般相談に移行すべきというところです。","respondent":"武内人権啓発課長","answer":"一般相談への移行ということですけれども、現実にこのような問題があるということをご理解いただければ、ここで相談することによって、そういう方が、心の問題という部分では、非常にためになるというか、力になるのかなと考えておりますので。","voiceIndex":252,"id":"exchange-111"},{"speaker":"菊地委員","kind":"意見","question":"インターネットを見ていますと、９年前に行われた東京都の同和問題に関する調査があるんです。そこでは、同和にかかわる差別は１件もないと東京都の調査の中で出されているんですね。もちろんおっしゃるように、かつて劣悪な生活環境に置かれて、結婚や就職のところで差別がまかり通っている、こういう時代もあったことは確かです。こういう状況は大きく切りかえていくべきだと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":254,"id":"exchange-112"},{"speaker":"堺委員","kind":"質問","question":"私のほうから２点お尋ねをします。最初に、職員研修費に関連いたしまして、今回新たな研修が、人材育成という視点で行われるわけですが、前段としては、まず人材を確保してから育成、こういう手順かなと思いますので、最近の入区状況といいますか、応募者と採用、３年間ぐらいで結構でありますが、もしお手元にございましたら、教えていただけますでしょうか。","respondent":"榎本人事課長","answer":"採用の状況ですけれども、採用につきましては、特別区人事委員会のほうで事務系は行っておりますので、最近の状況を申し上げますと、平成１６年度が受験者数７,４３６人に対し、４１８人の合格。","voiceIndex":256,"id":"exchange-113"},{"speaker":"堺委員","kind":"質問","question":"今回、人材の育成ということにつきましては、区長の施政方針の中で述べられております。明らかに今後１０年間で職員が４割も入れ替わるということですから、どうしても確保していく必要性があるだろうという気がするんですね。ですから、確保のためのいろんな方策も講じていかなければならないと思いますが、その辺についてのお考えはどうでしょうか。","respondent":"榎本人事課長","answer":"特に品川区の場合については、小中一貫教育、福祉の充実等をはじめ、そういう目玉の施策がいっぱいありまして、知名度はトップクラスですので、そういったもので魅力を増して、人材の確保に努めていきたいと考えています。","voiceIndex":258,"id":"exchange-114"},{"speaker":"堺委員","kind":"質問","question":"確かに魅力のあるところには人が集まってくるだろうなと思います。そこで、さっき建築士は４名、社会福祉士の方は６名というお話がございましたが、公共政策大学院派遣研修について、職員の政策形成能力の向上を図るために公共政策大学院の修学に際して、授業料その他の費用を助成する、こういうふうになっておりますが、この辺の応募状況はどうなっているんでしょうか。","respondent":"榎本人事課長","answer":"実際上、実績のところは今のところ品川区では１名なんですけれども、２年間毎日、夜５時間以上の授業と土日の研究を重ねて、２年間通わなければいけないという、かなりハードルが高いものですので、なかなか応募者は少ない状況なんですけれども。","voiceIndex":260,"id":"exchange-115"},{"speaker":"堺委員","kind":"提案","question":"人材の確保という視点で、いろいろな魅力がというお話もございました。この件については、平成１４年の第１回定例会のときに一般質問の中で、最後に、区独自のワークシェアリングの考え方に基づく雇用の導入を検討されるようにということで提案をした経緯があります。こういう意味から、ワークシェアリングについての本格的な検討の時期に来ていると考えております」。","respondent":"榎本人事課長","answer":"その中では、特に並立任用というのがありまして、２０時間勤務の人を２人組み合わせることで常勤職員１人分というような形もできるという法案の改正内容になっておりますので、そういうものも踏まえて、今後検討を進めていきたいと考えています。","voiceIndex":262,"id":"exchange-116"},{"speaker":"堺委員","kind":"質問・要望","question":"そこで１点、前提になることということで確認をしておきたいんですが、これは先ほど述べておりましたような、今後１０年間で職員が４割入れ替わるですので、当然お考えになって、研修の中にも含まれるだろうと思いますが、私、１９９５年２月２０日付のふれあい臨時号、職員の服務規律についてということで、今の区長が人事課長のときに執筆をされた文章があります。","respondent":"榎本人事課長","answer":"民間企業を指導していく立場になるわけですから、公務員として、全体の奉仕者として恥ずかしくない立場の職員で、なおかつ、今後退職に伴う補充の数は減っていきますので、少数精鋭の中で、きちんとした行政運営ができるような形に努めていきたいと考えています。","voiceIndex":264,"id":"exchange-117"},{"speaker":"堺委員","kind":"質問・要望","question":"現状と課題の分析をしながら、区民、議会において幅広く伺いながら策定をしていくということとあわせまして、プレス発表資料の中でも、この辺について述べられておりますが、品川区の区政の将来像とその達成方針を区民とともに新たな基本構想を策定する、こういうふうに言われておりますが、まず私は、区長の思いがどこまでここに反映されてくるかということが大事だろうと思います。","respondent":"濱野区長","answer":"基本構想の策定はこれからです。しかし、その中で、私が考えている品川のまち、どうしていくか。そして、それをどのようにやっていくか。この点についてもしっかりと自分の考えを盛り込んでいきたいと考えています。","voiceIndex":266,"id":"exchange-118"},{"speaker":"石田委員","kind":"質問・要望","question":"縦割りもわかるんだけど、区も一生懸命やっているんだけど、そこら辺の連携はとっていただかないと、先ほど町会の人にまた新たなボランティアをお願いするという話もあったけれども、ここの連携について、もう一度、どういうふうにしていったら、消防、警察と連携がとれるんだということを、区として、大変難しい話かもしれないけど、お考えを聞きたいなと思いますので、３点、お願いします。","respondent":"鷹倉区民課長、中川原広報広聴課長、久保田防災課長","answer":"したがって、これにこたえるべく、私どもも、いろいろな団体の方々に見ていただきながら、構想を立てながら、まちのほうも、あるいは都会の人のほうも。その中に、委員のお話にありました、投稿機能も設けまして、まちの方からも写真をいただくような機能も設けまして。具体的に、今回、防災計画改訂に当たって、防災会議の担当者会議を開く予定ですので、警察。","voiceIndex":269,"id":"exchange-119"},{"speaker":"石田委員","kind":"質問・要望","question":"今、国のＣＯ２削減をやろう、やろうと言っても、できていない。５０年を超えたらＣＯ２の削減効果が減る。そこには起債を発行したって、いいじゃないですか。地域にそれこそお願いして、各地域の、先ほど言った地域センター単位でもいいから、それの冊子みたいな、写真集みたいな、今昔物語みたいなものをつくるべきだと思っているので、そこら辺の感覚をもう一度教えていただきたいと思います。","respondent":"鷹倉区民課長、中川原広報広聴課長","answer":"そういう作業をしながら、環境問題の大切さ、そして人材を育てていく。そういうところから一歩一歩着実に進めていきたいと考えているところです。その中で応募してくださった方々とネットワークを組んで、この写真館のデータベースを充実させていこうという、ボランティアの方と組むネットワークをつくろうという構想も、私ども、来年度の仕事の中に考えておりますので。","voiceIndex":273,"id":"exchange-120"},{"speaker":"石田委員","kind":"質問・要望","question":"先ほど言った、各地域センター単位でいいわけなんだけど、それが例えば１３地域残ると、品川区全体の貴重な財産になるんじゃないですかということを言っているので、各地域でそういう話があったらと言ったら、各地域から上げてもらうような努力もするけれども、私は基本的に、行政側として、各地域センター単位でもいいけど、それをやることによって。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":276,"id":"exchange-121"},{"speaker":"西本委員","kind":"質問","question":"１３７ページ、庁舎等維持管理費、１３６ページ、職員研修費、１５３ページ、ワークショップ、防災区民組織になるんでしょうか、ワークショップについて、それから前後してしまうのですが、１４１ページの地域活動基盤整備補助、１５７ページの総合区民会館運営費、最後に地域センター等管理運営費。","respondent":"中島経理課長","answer":"通常の勤務時間帯につきましては、委託の交換も含めて、職員で対応しておりますけれども、夜間、休日につきましては、警備会社の警備員が電話対応するですけれども、私ども、警備会社の職員に対しましては、極力、丁寧な対応をするようにということで、適切な対応も含めて。","voiceIndex":278,"id":"exchange-122"},{"speaker":"西本委員","kind":"質問","question":"職員の方がいらっしゃるときには、職員の方が対応することができると思うんですが、管理会社の方たちがどのぐらい対応できるのかなと。丁寧にと言われても、かなりのストレスがたまるのではないかなと思うんですね。例えば何か起きたときに、臨時で残っていただくとか、そういう対応をする、臨時の方法、そういうのがあってもいいんじゃないかと思うんですが、いかがでしょうか。","respondent":"中島経理課長","answer":"例えば庁舎の管理の問題ですと、庁舎の設備に急に変なことが起こった、あるいは事故が起こったという場合につきましては、私どものほうに連絡が来ますし、そのほかの事故等が起きれば、所管の責任者のほうに緊急連絡が回るようになってあります。","voiceIndex":280,"id":"exchange-123"},{"speaker":"西本委員","kind":"質問","question":"一番初めに電話をとる人が、一番大変なわけですよね。その対応を区としてやっていくべきではないかなと思いますので、それは今後検討していただければと思います。それから次に、研修費の件ですけれども、研修をこれからいろいろされるということなんですが、いつも思うんですけれども、今回、平成１９年度のプレス発表がありました。その辺の現状はいかがでしょうか。","respondent":"榎本人事課長","answer":"他の所管の部分につきましては、区政の現状と課題という研修を講堂でやるんですけれども、それを３回やっております。その中で、こういうものを紹介しながら、区政の今のメインの事業はどんなものかというのを周知徹底を図っているところです。","voiceIndex":282,"id":"exchange-124"},{"speaker":"西本委員","kind":"質問・要望","question":"なぜそれを言うかというと、現場のところの人たちが一番区民の方と接するんですよ。窓口もそうですけれども。その人たちが、一つひとつ、ある程度は認識して、説明ができなきゃいけない。どういう品川区をつくろうとしているのかというところをどれだけ皆さん一人ひとりが理解できるかというところが大切なところだと思いますので、その辺の趣旨徹底の方法、考えをお聞きしたいと思います。","respondent":"榎本人事課長","answer":"要は、新しい政策が決まって、今年度はこれでいくよという形であれば、年度当初、人事異動があって、人が入れかわったときに、その部の今年の重点目標は何なんだという形の部分を、研修でもやりますけれども。","voiceIndex":284,"id":"exchange-125"},{"speaker":"西本委員","kind":"質問・要望","question":"ぜひよろしくお願いいたします。少なくとも品川区の区政に対して反するといいますか、反対のような動きではなくて、それに賛同する、一緒になってやっていくんだという動きになっていただきたいなと思っています。それで、防災の、どこに第１避難所があってというところも、全部入れ込んでつくっていました。それが今どういう動きになっているか、現状、それから、将来的な考え方があれば、教えてください。","respondent":"久保田防災課長","answer":"ワークショップについてですけれども、これは平成１５年にモデル的にやって、平成１６年から本格実施ということで、現在、７２町会のところで最低１回はワークショップをやっているという現状です。","voiceIndex":286,"id":"exchange-126"},{"speaker":"西本委員","kind":"質問・要望","question":"町会、自治会の方たちがいろいろ工夫をされているところがありますので、それを紹介しつつ啓発を進めていただきたいなと。それと、防犯マニュアルは、先ほどもありましたけれども、それもリンクするかとは思いますので、できる限りリンクできるものはリンクさせて、それが１つの大きなきっかけになると思いますので、ぜひお願いしたいと思います。そういう動きがあるかどうかの確認をしたいと思います。","respondent":"田村地域活動課長","answer":"私ども、西本委員からご指摘がありまして、月に２回所長会があります。実際に私のほうからも、そういう要望があるし、確かに難しい名前の町会がありますので、ぜひ地域ニュース、あるいはほかの情報等の発信源として、その内容を載せてほしいという形でやりました。","voiceIndex":288,"id":"exchange-127"},{"speaker":"西本委員","kind":"質問・要望","question":"１５７ページ、総合区民会館、これは指定管理者制度に入って、ここで利用料金収入を見込んでの金額が入っているんですが、ここの算定の方法、それから、利用状況はどうだったのか。その利用状況を見て、運営費という形で支出しているんだと思うんでけれども、その考え方をまずお聞きしたいと思います。","respondent":"鷹倉区民課長","answer":"指定管理者運営委託費利用料見込みということで、平成１９年度は２億９００万円何がしという数字になってあります。運営費が５,９００万円何がし。対前年度はどうなっていたかといいますと、利用料収入見込額が１億４,３７５万８,０００円。","voiceIndex":290,"id":"exchange-128"},{"speaker":"西本委員","kind":"質問","question":"よくわかりました。それで、指定管理者制度の１つの大きなメリットというのは、利用料の設定が新たにできるというところとか、いろいろメリットがあったと思うんですね。これはこれからも別立てになっていくものなのか。私の認識ですと、施設ということになりますので、清掃とか警備なんかも、全部入ってしまっているのではないかなという認識だったんですが、その辺はいかがですか。","respondent":"鷹倉区民課長","answer":"この部分は、再開発ビル１号の占有部分についての清掃費だとか、その部分が都市整備公社に流れている部分です。もう一つ、利用料の話をされていますけれども、その点については、今、２年目ですので、特に考えてございません。","voiceIndex":292,"id":"exchange-129"},{"speaker":"西本委員","kind":"質問・要望","question":"評価の方法については、指定管理者制度は、企画部のほうでいろいろ今年やろうとしているところですが、今後、ここの場合においてですけれども、指定管理者制度のメリット、改善しなければならない点というところ、それから自由度についての今後の考え方をお知らせいただきたいと思います。","respondent":"鷹倉区民課長","answer":"これはなかなか難しい言葉なんですけれども、砕いて言いますと、プラン・ドゥ・チェック・アクション、ここの部分のことを指していると言われています。具体的には、プラン・ドゥ、そしてチェックする、これをモニタリング、要するに区と指定管理者の中で計画を立てる。","voiceIndex":294,"id":"exchange-130"},{"speaker":"西本委員","kind":"質問","question":"これからいろいろと改善をしながら進んでいくかと思いますので、いい方向にいくようによろしくお願いします。それから、地域センターなんですけれども、今年児童センターが地域センター割り振りになったと聞いております。地域活動課として、児童センターとの関係をどういうふうに考えているのか。コラボレーションの考え方をお聞きしたいと思います。","respondent":"田村地域活動課長","answer":"特に私どもの所管であります町会、あるいは地区委員会と児童センターが、子どもの虐待を含めて、連携を、情報交換も含めて図っていくということの重要性も認識しておりますので、いろいろまだ課題も若干ありますが、引き続き地域センターと児童センター、児童課と連携を図って。","voiceIndex":296,"id":"exchange-131"},{"speaker":"西本委員","kind":"質問・要望","question":"これから児童センターも変わると思いますし、地域センターの役割もかなり変わってくると期待しております。部署がまたがってしまいますけれども、協働していただいて、いい地域につくり上げていただきたいと希望して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":298,"id":"exchange-132"},{"speaker":"宮崎委員","kind":"質問","question":"１４９ページの行政評価システム経費と民間委託推進経費について伺いたいと思います。その前に、先ほど人権啓発のところで、菊地委員からの質問がありまして、それに関連して質問したいのですが、人権啓発としてはＢ評価だという説明がありました。その一方で、同和事業については評価していないというお話でしたけれども、もうちょっとそこのところを詳しく説明していただければと思います。","respondent":"武内人権啓発課長","answer":"私が発言したのは、同和生活相談員の１つの大項目としては、ここに掲載するのは、一般の相談と違いまして、不特定多数の人を対象にしている相談ではないので、ここに掲載するのはいかがなのかなと、しようがないのかなということで、人権啓発事業費ということで。","voiceIndex":300,"id":"exchange-133"},{"speaker":"宮崎委員","kind":"質問","question":"つまり、同和事業、同和相談、この事業としての評価はやっているんですか。人権イコール同和なのか。人権と言えば、いろんな問題がありますよ。同和は同和として評価しているんですか。ここのところをはっきりしてください。","respondent":"武内人権啓発課長","answer":"人権啓発事業費という中で取り組んで、評価しています。","voiceIndex":302,"id":"exchange-134"},{"speaker":"宮崎委員","kind":"質問","question":"総務部分室、見せませんね。見せないし、評価が出てこないというのは、これは一体、同和というのは聖域なんでしょうか。一方では、奈良市では、５年間で８日しか出勤していなかった。実際、どういう実態で相談をやられているのか。出勤しているのか、どうなのか。そういう実態を、こういう今のやり方、これが果たして、行政評価と堂々と胸を張って言えるんでしょうか。そこのところを聞かせてください。","respondent":"武内人権啓発課長","answer":"同和生活相談員につきましては、品川区専門非常勤職員の取扱要綱の中で採用しておりまして、我々と同じように、タイムカードを使った出勤カードをやっております。委員ご存じのとおり、３階のフロアに私も毎日いまして、日々間違いなく出勤しておりますので、ご報告します。","voiceIndex":304,"id":"exchange-135"},{"speaker":"宮崎委員","kind":"質問・要望","question":"私の言うことを信じてください、そういう話じゃ、世の中通らないんですよ。次にいきたいと思うんですけれども、今回、行政評価のところでは、施政方針のところでも、民間委託のガイドラインの策定、価格だけでない、業務の質の評価、そういうことで委託先を選定していきたいということで言っておりましたけれども、先ほども質問がありました。そこの仕組みのところを説明していただきたいと思います。","respondent":"堀越行財政改革担当課長","answer":"モニタリングの件ですけれども、平成１９年度、民間委託の部分については、これからの民間委託の推進ということで、例えば事業者の選定、総合評価入札のあり方ですとか、実際に運営した後のモニタリングについて、これから検討を進めていくという予定です。","voiceIndex":306,"id":"exchange-136"},{"speaker":"宮崎委員","kind":"質問","question":"もうちょっと端的にお伺いしたいんですけれども、今まで、例えば人件費の問題等、委託先がどういうふうな労働条件なのか、そういうのを把握しませんと。要するに、出てくる過程、中身がどういうふうにチェックできるのか、そこの仕組みについてどういうふうに考えているのか。これからいろいろ検討もされるんでしょうけれども、そこの問題意識と今考えているところをお願いしたいと思います。","respondent":"堀越行財政改革担当課長","answer":"人件費の問題等がありましたけれども、私どもといたしましては、仕様書に定めてある業務水準を適切に運営しているかどうかという観点で、判断をしているものです。","voiceIndex":308,"id":"exchange-137"},{"speaker":"宮崎委員","kind":"質問・要望","question":"実際に、これについても、一昨日、沢田委員のほうで、行政情報の開示を求めた内容を紹介いたしました。２つの学校での学校給食調理の情報公開を求めたんですけれども、氏名住所等が黒塗りになるのは当然なんですけれども、資格を持っているかどうかとか、雇用形態がどうなっているかどうか、こういうことも秘密になっているわけです。","respondent":"中島経理課長","answer":"先ほどから行財政改革担当課長も申し上げていますように、私どもが契約する前提といたしまして、私どもが考えている業務がきちっと履行できるのかどうなのかということを判断して、それぞれ契約をしたり、見積もりをとったりしているものでございまして。","voiceIndex":310,"id":"exchange-138"},{"speaker":"宮崎委員","kind":"質問","question":"ここをどう抑えていくか、これが競争に勝っていく上での一番の命なんですよ。ですから、どういう雇用形態でやられているかというのは、ここが判断の基準になっていかないとなると、非常に危ないんじゃないかと思います。非常に厳しい批判をしております。そして悪循環に陥った。この例は、品川区とは違いますけれども、不二家の一連の不祥事について、区のほうはどういうふうに評価されていますか。","respondent":"日下部企画財政課長","answer":"今、不二家の件が出されましたけれども、委員ご自身のご質問にもございましたけれども、私ども、不二家と同じような形で比較検討の対象にされるということはあまり適切ではないと考えています。","voiceIndex":312,"id":"exchange-139"},{"speaker":"宮崎委員","kind":"質問","question":"私が不二家の問題を言ったのは、先日、農林水産省のほうでプレスのリリースをやっておりました。だから、私は、今質問したのは、結果オーライじゃなくて、どこまで内部の、やり方を含めて、その根幹になっていく人の配置なんかも含めて、どういうふうに行政がつかんでいくか。これをつかまなければ、行政の役割を放棄しているというふうにしか思えないんですけれども、そこの見解はどうでしょうか。","respondent":"堀越行財政改革担当課長","answer":"いろいろな定期的な報告等も受けて、今、モニタリングの部分をさらに検討を進めておりますが、これまでも定期的な報告、仕様書の確認、もちろん現場への確認等も行っておりまして、その部分については、適切に行ってきているものと認識しております。","voiceIndex":314,"id":"exchange-140"},{"speaker":"宮崎委員","kind":"意見","question":"法律を守るのは当然なんですけれども、今問題になっているのは、相次ぐ規制緩和のもとで、法律が実際に住民の命、健康を守れる、安全を守れる、そういう内容になっているのか、どうなのかというところが今問われているわけですよね。そこのところを、住民の感覚、サービスを受ける側の立場を忘れると、法律を盾にとっても、実際に住民の安全を守れないということを指摘しておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":316,"id":"exchange-141"},{"speaker":"伊藤委員","kind":"確認","question":"私は１３１ページの地域情報化計画作成支援経費と、１４５ページの区民チャンネル普及経費に関連して、質問をいたします。おそらくそういうことを将来構想としてにらんで計画を策定していくと思うんですが、確認したいのが、情報化計画作成の目的、考え方、それから、品川区は、どういう方向を持ってこの計画を策定していこうとしているのかをお聞かせください。","respondent":"小野情報システム課長","answer":"そのためには、品川区においては、地域情報化というのが一体どういうふうな状況にあるのかという現状をきちっと把握して、課題を整理し、行政として取り組むべき施策の方向だとか、あるいは、民間の活動が行うべき方向。","voiceIndex":318,"id":"exchange-142"},{"speaker":"伊藤委員","kind":"確認","question":"ご承知のように、今、品川区の約７割ぐらいでしょうか、視聴可能になっている。ですから、これからの１つの方向性としては、７割以上の方々が視聴可能となっているケーブルテレビ品川を通して、そこにデジタル化を通せば、相当いろんな品川区の情報がやりとりできる可能性が非常に近くなってくるわけですよね。ですから、地域情報化計画策定の中で、このケーブルテレビのシステムをどう活用していくのか。","respondent":"中川原広報広聴課長","answer":"デジタル化によるＣＡＴＶのこれからの活用ですが、今、総合庁舎の３階でキャンペーンをやってありますが、楽ビジョンという機能を今度開発しまして、今、テストをしているところです。","voiceIndex":320,"id":"exchange-143"},{"speaker":"伊藤委員","kind":"確認","question":"せっかく７割、８割ある資源を使っていきたい。ですから、そういうことまでずっと考えていくと、この地域情報化計画策定経費というのは、今の段階はそれでいいかもしれないけれども、将来はステップがたくさんあると思います。ですから、確認したいのが、デジタル放送を普及していくための区民チャンネル普及経費をどういうふうにこれから活用していくのかということが１つ。","respondent":"小野情報システム課長、中川原広報広聴課長","answer":"ケーブルテレビが地域情報化の中で非常に重要な役割を果たすというふうに私どもも考えておりまして、地域情報化のプランの中で、ケーブルテレビがどのような役割を果たすのか、あるいは区とどういうふうな形で連携をしていくのか。現在ＣＡＴＶがご覧になれる方々について、デジタル化の対応につきましては、セットトップボックスを購入いただければ、見れる形になるということで、ＣＡＴＶのほうでも、取りかえキャンペーンという形で。","voiceIndex":322,"id":"exchange-144"},{"speaker":"伊藤委員","kind":"質問・要望","question":"ぜひそういう支援をしていただきたいのが１つと、それから、ステップ、いろんな段階があると思います。今、７割、８割の世帯の方々と専用回線がつながっていることが１つ。それから、次に、デジタル化を着実にしていくことが１つ。最後に１つだけ確認したいのが、そういうデジタル技術を応用した大きな電子区役所の推進、構想、取り組み、計画等について、品川区の考え方をお聞かせください。","respondent":"小野情報システム課長","answer":"こういうふうな協働の連携の関係というものを、こういう地域の情報化の手段も十分有効に使いながらできるような形で、この課題を十分検討してまいりたいと考えております。","voiceIndex":325,"id":"exchange-145"},{"speaker":"土井委員","kind":"質問・要望","question":"私から、総務費全般になるんでしょうか、収入役の廃止、そして新たにつくられる会計管理者ということについて１つお伺いします。それから、１３１ページの電子計算組織ならびに基幹事務管理システムに関連して、お伺いすること。それから、午前中あったのに関連質問しようと思ったのですが、できませんので、ここで職員互助会補助金に関することでお伺いをしたいと思います。どんどんソフトも含めて。","respondent":"冨田副収入役、小野情報システム課長","answer":"それ以外の機能も実態として収入役が持っていたですけれども、今回の会計管理者に関しましては、地方自治法に例示があるものを基本的に引き継ぐもの、従前と変わらないという状況です。システムの保守という部分、これは制度改正等がありますと、システムの変更というものをやっていきますけれども、今までは、大型の汎用コンピューターの場合は、情報システム課の職員とベンダーのＳＥが協力して。","voiceIndex":328,"id":"exchange-146"},{"speaker":"土井委員","kind":"確認","question":"だから、２つに分かれているのよと。もうそろそろ、いろいろ考え直して、分け方をきちんとやってもらったほうがよろしいんじゃないでしょうか。そう思いませんか。というような形になるので、そこら辺がわかるように書いていただけたらありがたいなと思って見ていたんですが、ここだけじゃなくて、同じような指定管理者の問題があちこちで出てくると思うので、そこら辺はどういうふうにお考えでしょうか。","respondent":"中川原広報広聴課長、小野情報システム課長、榎本人事課長、日下部企画財政課長","answer":"今度、写真コンクールもやりますが、コンクールの結果の発表とか、いい写真の展示はインターネット美術館のほうでやらせていただく。予算のよりわかりやすい組み方ですけれども、委員ご指摘の点を十分踏まえまして、よりわかりやすくなるように検討してまいりたいと考えています。同じ所属で扱っているので、要らぬ皮算用をして、説明が誤解を招きました。申しわけありませんでした。ただ、まだその辺、さらに工夫の余地があるかどうかということも含めて、検討してまいりたいと思います。","voiceIndex":331,"id":"exchange-147"},{"speaker":"土井委員","kind":"質問","question":"最後のところだけ。要するに、指定管理者運営委託ということで、利用料金の入るのは、２億何ぼ入りますよ。委託料は、５,９９０万円、これでもう決まりという意味ですか。集めたものを一緒にして、委託の結果なんじゃないですかと。何だったら、利用収入をどんと上げれば、あんたの利益になるのよというのとは違うんですか、合っているんですか。","respondent":"日下部企画財政課長","answer":"その辺も指定管理者の制度の１つの大きなポイントではありますので、その辺については、実際に、これはあくまでも委託経費の中で、その辺はまたのみ込むような形で、整理をされていくというものでありますので、ご理解いただきたいと思います。","voiceIndex":336,"id":"exchange-148"},{"speaker":"土井委員","kind":"確認","question":"もう１回確認します。見込みとして、入ってくるのが２億円ありますよね。これはだれがとるんですか。そうすると、２億円入らなかったらどうするのという問題、半分になっちゃったらどうするのという問題があるわけでしょう。倍入ったときどうするの。しながわ水族館のとき、いっぱい入っちゃって、後からえらいもめたわけですから。そういうのをどうするのかと聞いているんです。","respondent":"堀越行財政改革担当課長","answer":"具体的な業務内容ですとか、そういったことによって、年度間において若干の変動等もありますが、より指定管理者が、利用料金制をとっておりますので、努力をしながら、適切な業務運営に努めていく、そういう趣旨のものです。","voiceIndex":338,"id":"exchange-149"},{"speaker":"土井委員","kind":"意見","question":"あえてもう１回聞きます。この利用料金は委託を受けたところに入るんですよね。そうすると、委託するときに、こちらが払うのは何ぼなのということになったときに、それが一定だとすれば、収入が入らなかったら補てんしてくださいと言うでしょう。余ったら、よかったねと言ってポケットに入れちゃうのということとの関連を聞いているんです。","respondent":"堀越行財政改革担当課長","answer":"失礼いたしました。事業計画を出していただく中で、十分に経営努力をしていただくです。","voiceIndex":340,"id":"exchange-150"},{"speaker":"三上委員","kind":"質問・要望","question":"近隣セキュリティシステムの運営経費についてということで。近隣セキュリティシステムについての、「まもるっち」については、小学生卒業時点で、本体そのものは回収されて、新１年生には、その中古品、６年生が使い古してというか、そこまでいっているかどうかわからないですが、先輩が使っていたものを渡す仕組みになっているのかということについて、お伺いさせていただこうと思います。","respondent":"金子産業振興課長","answer":"近隣セキュリティシステムの「まもるっち」の使い回しということですけれども、小学校６年では、３月の終わりのほうまで使いますので、それを４月の頭の１年生に回すということは、期間的に難しいので、３月の時点で回収して、それをリニューアルして、途中で。","voiceIndex":347,"id":"exchange-151"},{"speaker":"三上委員","kind":"質問","question":"そうしますと、回収したものは、それなりに余裕があるということになりますよね。ですから、それをあえて、武内委員のときに、使いたいという人に対して有料で貸し出したらどうなんですかということについて、有効活用するという考え方からいったら、これは貸したっていいんじゃないですか。特に、税金を投入して、開発を進める。","respondent":"山田区民生活事業部長","answer":"なおかつ登下校が一番犯罪の率が高いということで、一定の時間設定をする中で、皆さんにご理解とご協力をいただいたシステムということになってありますので、このシステムの中で、今、ご提案のあった中学生、そのほか、いろいろな活用方法はあろうかと思いますけれども。","voiceIndex":349,"id":"exchange-152"},{"speaker":"三上委員","kind":"質問・要望","question":"それはわかりますよ。高齢者の皆さんに拡大したっていい話でしょう。それから、歩きたばこについての現状なんですけれども、もう時間がないからいろいろ伺いませんけれども、平塚橋の交差点のところから２６号線、最近はたばこを吸って歩く人が非常に増えてきた。こういう現状について、品川区としてはどういうふうに理解して、新たにどういうふうな対策をこれからとろうとしているのか、お伺いしたい。","respondent":"金子生活安全担当課長","answer":"したがいまして、町会を中心に、手前どもで、最近でやった活動といたしましては、町会回覧にチラシ数千枚を活用して、啓発活動、こういったものをやっております。地味ではありますが、こういった活動を繰り返し繰り返しやっていくことが必要であるかなと考えております。","voiceIndex":351,"id":"exchange-153"},{"speaker":"三上委員","kind":"質問","question":"商店街だって、ずっと朝、歩いているんじゃないですか。武蔵小山商店街の中だって歩いているし、そうであるならば、２６号線の通りだって、歩いたっておかしくないはずでしょう。はがれたのかどうか、まだ残骸は残っているのかわかりませんけれども、非常に目立たない。そういうふうになってきたならば、なぜもうちょっと改善しようという答えが出てこないんですか。人の目に見えるように。","respondent":"金子生活安全担当課長","answer":"その辺は、もう一度こちらでも調整して、適切な指導をやっていきたいと思うんですけれども、いずれにしても、啓発・指導徹底に関しましては、今後も禁止区域、そうでなくても、美化活動等含めて、啓発活動の徹底を図っていきたいと思います。","voiceIndex":353,"id":"exchange-154"},{"speaker":"三上委員","kind":"質問・要望","question":"啓発活動をやっていただきたいんですよ。そのシールが。そうであるならば、ここが禁止区域ですよと、電信柱にしたって、何にしたって、貼り出したっていいじゃないですか。路面に貼るんだったら、もうちょっと明確に、簡単にはがれないような、そういうようなものをきちっと路面に貼るとか、そういうことをなぜやろうとしないんですかとお伺いしているんです。","respondent":"金子生活安全担当課長","answer":"その禁止区域に関しましては、もう一度こちらのほうで確認をしまして、貼るべきところにはきちんと表示をして、啓発活動の徹底を図っていきたいと思います。","voiceIndex":355,"id":"exchange-155"},{"speaker":"三上委員","kind":"質問・要望","question":"そういったことについてしっかりやっていただきたいとお願いしているわけですから、しっかり取り組んでいただきたいと思います。時間がないので、これでやめますけれども、近隣セキュリティシステムについての取り組みについても、宿題として、やっておきますけれども、よろしくお願いしいたと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":357,"id":"exchange-156"},{"speaker":"沢田委員","kind":"質問・要望","question":"１３０ページの職員給与費に関連して質問をさせていただきたいと思います。先日、私、一般質問で、ワーキングプアを解消するために品川区から頑張ってほしいという思いで質問をいたしました。改めてこのような実態について、区側はどう思うのか、お答え願いたいと思います。","respondent":"榎本人事課長","answer":"ですから、実態上の部分はいろいろあるとは思いますけど、そういう時間のあいたところを、希望する方に対して応募してもらって、きちんと働いてもらうという形を考えております。","voiceIndex":359,"id":"exchange-157"},{"speaker":"沢田委員","kind":"質問・要望","question":"地方自治法の第２条の最少の経費というのを持ち出しましたけれども、じゃあ、第２条の前半は何て書いてあるんでしょうか。そこを読み上げていただきたいと思います。それから、もう一つ言いますけれども、もともと労働者派遣法というのは、１９８５年までなかった。私は歯どめが必要だと思うし、２条にそこは書いてあると思います。ちょっと読み上げて、考え方を聞かせていただきたいと思います。","respondent":"榎本人事課長","answer":"２条の第１４項、「地方公共団体は、その事務を処理するに当っては、住民の福祉の増進に努めるとともに、最少の経費で最大の効果を挙げるようにしなければならない」と書いてあります。このとおりです。","voiceIndex":361,"id":"exchange-158"},{"speaker":"沢田委員","kind":"質問","question":"不まじめなんですよ。だから、いくら働いても働いても、生活保護基準に届かない人が出ても構わないんだという論理は一体どこにあるんでしょう。私は憲法２５条で、国民が文化的で最低限度の生活を営む権利がある。それよりも低い品川区民サービスを提供している職員の方、派遣だとか、非常勤の人が生活保護基準以下でいいなんていうことは一体どこにあるんでしょうか。その考えを聞いているんです。","respondent":"榎本人事課長","answer":"最低賃金法によりますと、たしか東京の最低賃金は時間単価７２０～７３０円だったと思いますけれども、それを下回っているような形は一切とっておりませんので、法令にのっとった形でやっているところです。","voiceIndex":363,"id":"exchange-159"},{"speaker":"沢田委員","kind":"意見","question":"最低賃金制は今、世界で比べても最低ですよ。アメリカが日本の下にいたんだけど、この間、８００円ぐらいまで上げたために、品川区はＯＥＣＤ加盟国では最低になっているんです。そういうのが一方にありながら、こういう生活保護基準以下で使って問題ないという地方自治体は、憲法２５条を語る資格がないと思います。私は改めてこれは、部長なり助役なり区長なり、考え方の根本をお尋ねしたいと思います。","respondent":"榎本人事課長","answer":"均等待遇についてですけれども、均等待遇の部分については、いろいろ法制審議会等で意見は出ておりますけれども、まだ法制の審議段階というところになっておりますし、雇用のあり方自体が、第１回定例会の答弁でも申し上げましたとおり。","voiceIndex":365,"id":"exchange-160"},{"speaker":"沢田委員","kind":"質問・要望","question":"パートタイム労働法の第３条に、均衡ある待遇の確保を規定しろと。これを政府に求めているんです。品川区の人権尊重宣言ですけど、人間は生まれつき平等で、差別があってはならないと高らかにうたっているのが、現実に品川区の進める労働政策の中で、大きな差別が生じているじゃないですか。それは正していただきたいと思います。","respondent":"榎本人事課長","answer":"非常勤職員については、短時間の勤務ということで、基本的に時間外はないという前提で任用をしております。","voiceIndex":367,"id":"exchange-161"},{"speaker":"沢田委員","kind":"質問","question":"明日のどういう仕事をするかというのができないので、結局帰りは６時５０分ぐらいになる。前、私ども、この問題を議会で質問しました。早出と残業が事実上なければ、すまいるスクールが運用できないような状況なのに、時間外手当を払わないというのは、サービス残業そのものじゃないでしょうか。払うべきお金を払わないで、それを前提にすまいるスクールが動かされていると言えないでしょうか。","respondent":"市川庶務課長","answer":"日々の仕事の始業前、あるいは終業後の処理に時間をとることはあるでしょうけれども、それについては、非常勤職員に対する適正な指導を行っているという認識です。","voiceIndex":371,"id":"exchange-162"},{"speaker":"沢田委員","kind":"質問","question":"ないと言ったんですけれども、すまいるスクールをはじめとして、区内の非常勤や派遣労働の人たちが置かれている労働条件について、品川区が責任を持って、大事な仕事をやっているわけですから、調査をしてほしいと思いますが、いかがでしょうか。聞いたら、だれがどう受け取ったのか、さっぱりわからないという事態でしたけれども、この問題がどうなったのか、見解をお尋ねしたいと思います。","respondent":"榎本人事課長、桑村総務課長","answer":"労働条件の話ですけれども、非常勤職員の職場はかなり多岐にわたっております。その中で、各所属がきちんと任用の部分を把握しておりますので、調査するつもりはありません。この間ご質問ありましたので、そういう意味では、丁寧なアンケートをして、今回、春闘共闘会議のその時間には私がお会いして、お話を申し上げたところです。","voiceIndex":373,"id":"exchange-163"},{"speaker":"沢田委員","kind":"質問","question":"アンケートのほうは一歩前進したので評価をしたいと思います。それから、十分に知り尽くしていると言うけど、私は具体的に、現場の人の声と実態を示したんです。それにまともに反論しないまま、問題ないという、この姿勢はどうなんでしょうか。批判は受けないという、あまりにも不誠実な態度だということを強調して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":376,"id":"exchange-164"},{"speaker":"須藤委員","kind":"質問","question":"１３５ページ、危機管理室経費、１４９ページ、新基本構想について、まずお聞かせ願いたいと思います。危機管理室の経費ですけれども、どういったことをなされている、どのようなことが危機管理として意識をされているのか。そこに区長の考え方をどうやって入れ込んでいくのか。そんないろんな要素があると思うんですが、そのあたりの因子というか、そのあたりをどういうふうに考えているか、教えてください。","respondent":"桑村危機管理室長、堀越行財政改革担当課長","answer":"危機管理はどういうことを考えているかということなんですけれども、いわゆる不測の事態、通常では予測できない事態が起こる。検討委員会のメンバーですけれども、学識委員、公募区民、各種団体の代表者の方等を考えているところです。","voiceIndex":378,"id":"exchange-165"},{"speaker":"須藤委員","kind":"質問","question":"いろんな問題がここに入ってくると思うんですが、今お話にありましたようなメンバーに、有識者という形が、どういう方々が選ばれるのかというのがちょっと懸念しているところなんですが、そういった全体を見ていって、人口動態であるとか、健康であるとか、医療であるとか、地球の温暖化問題であるとか、いろんなことが入ってくるんだけれども、そのあたりはどの辺まで入れ込んでいらっしゃるのか。","respondent":"新美企画部長","answer":"基本構想についてですが、これから早急に策定委員会、検討委員会のメンバー構成を、今、課長が述べましたようなことで、具体的に早急に固めていきたいと考えています。","voiceIndex":381,"id":"exchange-166"},{"speaker":"須藤委員","kind":"質問・要望","question":"外部とか、それはそこでいいんですが、そこで、先ほどご意見がありましたように、区長の考えがしっかりそこで生きてこなきゃいけないので、そこがどういう印象を区長はお持ちなんですかと。","respondent":"濱野区長","answer":"したがって、この基本構想の中に区議会議員の方が加わっていただくかどうかということについては、まだ慎重に考えなければいけないだろうと考えておりまして、この辺についてはまだペンディングですが、基本的に区議会での議決をいただく事項についての案件ですので。","voiceIndex":383,"id":"exchange-167"},{"speaker":"須藤委員","kind":"質問・要望","question":"１５１ページの医療救護体制の整備と無線スピーカーの取りかえについてお尋ねします。できれば一遍に、無線ですから、何かあったらすっとできるようにしておかないと、これはうんと高価なものだったらと思うんだけれども、１,１００万円ぐらいの数字ですから、３年かかるなら、３,３００万円だったらば、１年間で整備をしてあげたらいいと思うんですが、いかがでしょうか。","respondent":"桑村総務課長、久保田防災課長","answer":"その意味で、一定の検討をさせていただきましたけれども、その形でやらせていただければという形で考えているところです。医療救護班のメンバーの構成ですけれども、医療救護班については、災害が発生したときに、医療救護班を編成して、救護場、これは１３カ所、学校に予定しておりますけれども、そこに派遣することになっております。","voiceIndex":385,"id":"exchange-168"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=878#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":118079,"voices":388}}]);
